window.ETSDATA=window.ETSDATA||{};window.ETSDATA[13]={"lc":{"p1":[{"n":1,"opts":["She's cleaning an oven.","She's moving a pot.","She's opening a cabinet.","She's holding a towel."],"vi":["Cô ấy đang lau chùi lò nướng.","Cô ấy đang di chuyển một cái nồi.","Cô ấy đang mở một cái tủ.","Cô ấy đang cầm một chiếc khăn."],"ans":"D","xp":"Ảnh một người phụ nữ: cô ấy đang cầm (holding) một chiếc khăn → chọn (D).\n(A) không lau lò nướng, (B) không di chuyển nồi, (C) không mở tủ → sai động tác.","a":"E24-T03-01.mp3","img":"q1.jpg"},{"n":2,"opts":["They're putting trash in a bag.","They're taking off their jackets.","They're facing a shelving unit.","They're painting a room."],"vi":["Họ đang bỏ rác vào túi.","Họ đang cởi áo khoác.","Họ đang đứng quay mặt về phía một kệ tủ.","Họ đang sơn một căn phòng."],"ans":"C","xp":"Ảnh hai người đang đứng đối diện (facing) một kệ tủ (shelving unit) → chọn (C).\n(A) bỏ rác vào túi, (B) cởi áo khoác, (D) sơn phòng đều là động tác không có trong ảnh.","a":"E24-T03-02.mp3","img":"q2.jpg"},{"n":3,"opts":["One of the men is removing his hat.","A line of customers extends out a door.","Some workers are installing a sign.","Musicians have gathered in a circle."],"vi":["Một trong những người đàn ông đang cởi mũ.","Một hàng khách kéo dài ra tận ngoài cửa.","Vài công nhân đang lắp một tấm biển.","Các nhạc công đã tụ tập thành vòng tròn."],"ans":"D","xp":"Ảnh các nhạc công (musicians) đang ngồi/đứng thành vòng tròn (in a circle) → chọn (D).\n(A) không ai đang cởi mũ. (B) không có hàng khách, (C) không có tấm biển (sign) trong ảnh.","a":"E24-T03-03.mp3","img":"q3.jpg"},{"n":4,"opts":["Some tools have been left on a chair.","Some tool sets have been laid out.","A cup of coffee has spilled.","A table leg is being repaired."],"vi":["Vài dụng cụ được để lại trên ghế.","Vài bộ dụng cụ đã được bày ra.","Một tách cà phê đã bị đổ.","Một chân bàn đang được sửa."],"ans":"B","xp":"Ảnh không có người, các bộ dụng cụ (tool sets) được bày ra (laid out) trên bàn → chọn (B).\n(A) không có ghế (chair). (C) cà phê không bị đổ. (D) 'is being repaired' cần có người đang sửa → sai.","a":"E24-T03-04.mp3","img":"q4.jpg"},{"n":5,"opts":["A railing is being removed.","A roof is under construction.","Some workers are carrying a ladder.","Some workers are holding sheets of metal."],"vi":["Một lan can đang được tháo dỡ.","Một mái nhà đang được thi công.","Vài công nhân đang khiêng một cái thang.","Vài công nhân đang cầm những tấm kim loại."],"ans":"B","xp":"Ảnh một mái nhà đang trong quá trình xây dựng (under construction) → chọn (B).\n(A) lan can không bị tháo. (C) không có công nhân khiêng thang. (D) không thấy tấm kim loại (sheets of metal).","a":"E24-T03-05.mp3","img":"q5.jpg"},{"n":6,"opts":["A ladder has been leaned against a tree.","There are piles of tree branches discarded in a field.","Wooden benches have been arranged in a circle.","A wooden structure has been built near some trees."],"vi":["Một cái thang được dựng tựa vào cây.","Có những đống cành cây bị vứt bỏ trên cánh đồng.","Những chiếc ghế dài bằng gỗ được xếp thành vòng tròn.","Một công trình bằng gỗ đã được dựng gần mấy cái cây."],"ans":"D","xp":"Ảnh một công trình bằng gỗ (wooden structure) dựng gần các hàng cây → chọn (D).\n(A) không có thang tựa vào cây. (B) không có đống cành cây (piles of tree branches). (C) không có ghế dài gỗ.","a":"E24-T03-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Why is there no flour on the shelf?","qvi":"Sao trên kệ không có bột mì vậy?","opts":["Because it's out of stock.","Those roses smell nice.","No, the other cake."],"vi":["Vì nó hết hàng rồi.","Mấy bông hồng đó thơm quá.","Không, cái bánh kia."],"ans":"A","xp":"Câu hỏi Why (tại sao) không có bột mì trên kệ → (A) đưa ra lý do: hết hàng (out of stock) → đúng.\n(B) bẫy âm: 'flour' (bột mì) nghe giống 'flower' (hoa) → roses. (C) câu hỏi Why không trả lời bằng Yes/No.","a":"E24-T03-07.mp3"},{"n":8,"q":"When will the catering company arrive?","qvi":"Khi nào công ty cung cấp đồ ăn sẽ đến?","opts":["At four o'clock.","That's a delicious flavor.","Many vegetarian options."],"vi":["Lúc 4 giờ.","Đó là một hương vị rất ngon.","Nhiều lựa chọn món chay."],"ans":"A","xp":"Câu hỏi When (khi nào) → (A) trả lời thời gian cụ thể 'lúc 4 giờ' → đúng.\n(B), (C) dùng từ liên tưởng đến 'catering' (đồ ăn): delicious, vegetarian, nhưng không trả lời thời gian.","a":"E24-T03-08.mp3"},{"n":9,"q":"When's the meeting scheduled to start?","qvi":"Cuộc họp dự kiến bắt đầu lúc nào?","opts":["At a networking event.","I started this job six years ago.","Right after lunch."],"vi":["Tại một sự kiện giao lưu kết nối.","Tôi bắt đầu công việc này 6 năm trước.","Ngay sau bữa trưa."],"ans":"C","xp":"Câu hỏi When về giờ bắt đầu họp → (C) 'ngay sau bữa trưa' là mốc thời gian → đúng.\n(A) trả lời nơi chốn (Where). (B) bẫy lặp từ: start → started, nhưng nói về công việc của mình.","a":"E24-T03-09.mp3"},{"n":10,"q":"How much will the repairs cost?","qvi":"Việc sửa chữa sẽ tốn bao nhiêu tiền?","opts":["I have two pairs of shoes.","Around 200 dollars.","The restaurant downtown."],"vi":["Tôi có hai đôi giày.","Khoảng 200 đô-la.","Nhà hàng ở trung tâm thành phố."],"ans":"B","xp":"Câu hỏi How much (bao nhiêu tiền) → (B) đưa ra số tiền 'khoảng 200 đô' → đúng.\n(A) bẫy âm: 'repairs' nghe giống 'pairs'. (C) không liên quan.","a":"E24-T03-10.mp3"},{"n":11,"q":"You went to the dentist this morning, didn't you?","qvi":"Sáng nay bạn đi nha sĩ phải không?","opts":["Oh, I've already had breakfast.","Yes, for an annual checkup.","Let's take the bus."],"vi":["Ồ, tôi ăn sáng rồi.","Đúng vậy, để khám định kỳ hằng năm.","Mình đi xe buýt đi."],"ans":"B","xp":"Câu hỏi đuôi xác nhận việc đi nha sĩ → (B) 'Yes' + giải thích thêm: đi khám định kỳ hằng năm (annual checkup) → đúng.\n(A) liên tưởng 'morning' → breakfast. (C) không liên quan.","a":"E24-T03-11.mp3"},{"n":12,"q":"Where should we put the new printer?","qvi":"Chúng ta nên đặt cái máy in mới ở đâu?","opts":["In the corner by the stairs.","The third page of the document.","A reusable ink cartridge."],"vi":["Ở góc phòng cạnh cầu thang.","Trang thứ ba của tài liệu.","Một hộp mực có thể tái sử dụng."],"ans":"A","xp":"Câu hỏi Where (ở đâu) → (A) chỉ vị trí cụ thể 'góc cạnh cầu thang' → đúng.\n(B) không liên quan. (C) liên tưởng 'printer' → ink cartridge (hộp mực).","a":"E24-T03-12.mp3"},{"n":13,"q":"What type of plant do you have in your office?","qvi":"Bạn có loại cây gì trong văn phòng?","opts":["Whenever I sit at my desk.","Thanks—I just bought it.","One that doesn't require much water."],"vi":["Mỗi khi tôi ngồi vào bàn làm việc.","Cảm ơn, tôi mới mua nó.","Loại không cần nhiều nước."],"ans":"C","xp":"Câu hỏi What type (loại gì) → (C) mô tả loại cây: loại không cần tưới nhiều nước → đúng.\n(A) liên tưởng 'office' → desk, và trả lời thời gian. (B) không trả lời câu hỏi.","a":"E24-T03-13.mp3"},{"n":14,"q":"There was a sale at the furniture store.","qvi":"Cửa hàng nội thất đã có đợt giảm giá đấy.","opts":["No, it wasn't in storage.","Did you buy anything?","Some old receipts."],"vi":["Không, nó không có trong kho.","Bạn có mua gì không?","Vài hóa đơn cũ."],"ans":"B","xp":"Câu trần thuật báo tin có đợt giảm giá → (B) hỏi lại một cách tự nhiên 'Bạn có mua gì không?' → đúng.\n(A) bẫy âm: 'store' → 'storage'. (C) liên tưởng 'sale' → receipts (hóa đơn).","a":"E24-T03-14.mp3"},{"n":15,"q":"Can you show me how to submit a tech help ticket?","qvi":"Bạn có thể chỉ tôi cách gửi phiếu yêu cầu hỗ trợ kỹ thuật không?","opts":["Let me send you the link.","A broken power cable.","No, over ten minutes."],"vi":["Để tôi gửi đường link cho bạn.","Một sợi dây nguồn bị hỏng.","Không, hơn mười phút."],"ans":"A","xp":"Lời nhờ chỉ cách gửi phiếu hỗ trợ → (A) 'để tôi gửi link cho bạn' là cách giúp đỡ phù hợp → đúng.\n(B) trả lời 'hỏng cái gì' (What). (C) không liên quan.","a":"E24-T03-15.mp3"},{"n":16,"q":"Where is the power button on this device?","qvi":"Nút nguồn của thiết bị này ở đâu vậy?","opts":["I've never used that model before.","Ten euros per hour.","We charge more for color photographs."],"vi":["Tôi chưa từng dùng mẫu đó bao giờ.","Mười euro mỗi giờ.","Chúng tôi tính phí cao hơn cho ảnh màu."],"ans":"A","xp":"Câu hỏi Where về nút nguồn → (A) trả lời gián tiếp: 'tôi chưa dùng mẫu đó bao giờ' = tôi không biết → đúng (kiểu trả lời 'không biết' rất hay gặp).\n(B) trả lời giá tiền (How much). (C) không liên quan.","a":"E24-T03-16.mp3"},{"n":17,"q":"Do you want to take a walk now, or would later be better?","qvi":"Bạn muốn đi dạo bây giờ, hay để lát nữa thì tốt hơn?","opts":["A nearby lake.","I'm free to walk now.","No, I don't use a fitness tracker."],"vi":["Một cái hồ gần đây.","Tôi đang rảnh để đi dạo bây giờ.","Không, tôi không dùng thiết bị theo dõi sức khỏe."],"ans":"B","xp":"Câu hỏi lựa chọn: bây giờ hay lát nữa → (B) chọn 'bây giờ' (I'm free to walk now) → đúng.\n(A) liên tưởng 'walk' → lake. (C) liên tưởng 'walk' → fitness tracker.","a":"E24-T03-17.mp3"},{"n":18,"q":"I ordered some new equipment for the factory.","qvi":"Tôi đã đặt mua một số thiết bị mới cho nhà máy.","opts":["The news program on Channel Ten.","Great—I can't wait to use it.","The car dealership."],"vi":["Chương trình thời sự trên kênh 10.","Tuyệt quá, tôi rất mong được dùng nó.","Đại lý ô tô."],"ans":"B","xp":"Câu trần thuật thông báo đã đặt thiết bị mới → (B) phản hồi tích cực 'Tuyệt, tôi rất mong được dùng' → đúng.\n(A) bẫy âm: 'new' → 'news'. (C) không liên quan.","a":"E24-T03-18.mp3"},{"n":19,"q":"There's a nice place to rent on Mercer Street.","qvi":"Có một chỗ cho thuê đẹp trên phố Mercer đấy.","opts":["I just renewed my current lease.","It was a great show.","A standard rental application."],"vi":["Tôi vừa gia hạn hợp đồng thuê hiện tại rồi.","Đó là một buổi diễn tuyệt vời.","Một mẫu đơn xin thuê nhà tiêu chuẩn."],"ans":"A","xp":"Người nói giới thiệu chỗ thuê đẹp → (A) 'tôi vừa gia hạn hợp đồng thuê (renewed my lease)' = ngầm nói không cần tìm chỗ mới → đúng.\n(B) liên tưởng 'nice' → great. (C) bẫy từ cùng gốc: rent → rental.","a":"E24-T03-19.mp3"},{"n":20,"q":"Is the heating system working?","qvi":"Hệ thống sưởi có hoạt động không?","opts":["Yes, that's my Web site.","A five-kilometer run.","I just called maintenance."],"vi":["Vâng, đó là trang web của tôi.","Một cuộc chạy 5 km.","Tôi vừa gọi cho bộ phận bảo trì rồi."],"ans":"C","xp":"Hỏi hệ thống sưởi có chạy không → (C) 'tôi vừa gọi bảo trì (maintenance)' = ngầm cho biết máy đang hỏng → đúng.\n(A) có 'Yes' nhưng nội dung không liên quan. (B) không liên quan.","a":"E24-T03-20.mp3"},{"n":21,"q":"Isn't the roadwork in front of city hall finished yet?","qvi":"Việc sửa đường trước tòa thị chính vẫn chưa xong à?","opts":["I just finished my conference presentation.","A lot of traffic in the evening.","No, they still have another month to go."],"vi":["Tôi vừa hoàn thành bài thuyết trình ở hội nghị.","Buổi tối xe cộ đông lắm.","Chưa, họ vẫn còn một tháng nữa."],"ans":"C","xp":"Câu hỏi phủ định hỏi việc sửa đường xong chưa → (C) 'Chưa, còn một tháng nữa' → đúng.\n(A) bẫy lặp từ 'finished'. (B) liên tưởng 'roadwork' → traffic.","a":"E24-T03-21.mp3"},{"n":22,"q":"Who will lead the new-employee training today?","qvi":"Ai sẽ phụ trách buổi đào tạo nhân viên mới hôm nay?","opts":["We're using a recorded video.","Yes, right after lunch.","Classroom 124."],"vi":["Chúng tôi dùng một video đã quay sẵn.","Vâng, ngay sau bữa trưa.","Phòng học 124."],"ans":"A","xp":"Câu hỏi Who (ai) → (A) 'chúng tôi dùng video quay sẵn' = không có người hướng dẫn trực tiếp → đúng (trả lời gián tiếp).\n(B) câu hỏi Who không trả lời bằng Yes. (C) trả lời địa điểm, liên tưởng 'training' → classroom.","a":"E24-T03-22.mp3"},{"n":23,"q":"Is the safety inspection scheduled for this month or next month?","qvi":"Buổi kiểm tra an toàn được lên lịch vào tháng này hay tháng sau?","opts":["I thought I saved the file.","The factory supervisor.","It's this Wednesday."],"vi":["Tôi tưởng tôi đã lưu tập tin rồi.","Quản đốc nhà máy.","Vào thứ Tư tuần này."],"ans":"C","xp":"Câu hỏi lựa chọn về thời gian kiểm tra → (C) đưa ra thời điểm cụ thể 'thứ Tư tuần này' (tức là tháng này) → đúng.\n(A) bẫy âm: 'safety' → 'saved'. (B) liên tưởng 'inspection' → supervisor, trả lời Who.","a":"E24-T03-23.mp3"},{"n":24,"q":"When is the harvest festival taking place?","qvi":"Lễ hội mùa gặt diễn ra khi nào?","opts":["It's a week from tomorrow.","Sure, I can take it.","The park next to the art museum."],"vi":["Một tuần sau ngày mai.","Chắc chắn rồi, tôi có thể cầm nó.","Công viên cạnh bảo tàng nghệ thuật."],"ans":"A","xp":"Câu hỏi When → (A) 'một tuần tính từ ngày mai' là thời gian → đúng.\n(B) 'Sure' giống trả lời Yes, không hợp câu hỏi When. (C) trả lời địa điểm (Where).","a":"E24-T03-24.mp3"},{"n":25,"q":"Was your new laptop expensive?","qvi":"Cái máy tính xách tay mới của bạn có đắt không?","opts":["Do you have a new password?","I had a discount coupon.","On top of the cabinet."],"vi":["Bạn có mật khẩu mới à?","Tôi có phiếu giảm giá.","Ở trên nóc tủ."],"ans":"B","xp":"Hỏi laptop có đắt không → (B) 'tôi có phiếu giảm giá' = ngầm nói không đắt lắm → đúng.\n(A) bẫy lặp từ 'new'. (C) bẫy âm: 'laptop' → 'top'.","a":"E24-T03-25.mp3"},{"n":26,"q":"Why don't we go on our camping trip next weekend?","qvi":"Sao chúng ta không đi cắm trại vào cuối tuần tới nhỉ?","opts":["Yes, that table lamp is quite nice.","Should we go left or right?","I have a performance scheduled with my band."],"vi":["Vâng, cái đèn bàn đó khá đẹp.","Chúng ta nên rẽ trái hay phải?","Tôi có lịch biểu diễn với ban nhạc của tôi rồi."],"ans":"C","xp":"'Why don't we...?' là lời rủ rê, đề nghị → (C) 'tôi có lịch diễn với ban nhạc' = từ chối khéo → đúng.\n(A) không liên quan. (B) bẫy lặp từ 'go'.","a":"E24-T03-26.mp3"},{"n":27,"q":"The workshop for this afternoon was postponed, wasn't it?","qvi":"Buổi hội thảo chiều nay bị hoãn rồi phải không?","opts":["At the post office.","I haven't checked my e-mail.","A ticket for two o'clock, please."],"vi":["Ở bưu điện.","Tôi chưa kiểm tra e-mail.","Cho tôi một vé lúc 2 giờ."],"ans":"B","xp":"Câu hỏi đuôi xác nhận việc hoãn hội thảo → (B) 'tôi chưa kiểm tra e-mail' = tôi chưa biết → đúng.\n(A) bẫy âm: 'postponed' → 'post office'. (C) liên tưởng 'workshop/afternoon' → ticket, two o'clock.","a":"E24-T03-27.mp3"},{"n":28,"q":"How were our production figures last month?","qvi":"Số liệu sản xuất của chúng ta tháng trước thế nào?","opts":["They produce electric cars.","Nine o'clock in the morning.","We were closed down for a week."],"vi":["Họ sản xuất ô tô điện.","Chín giờ sáng.","Chúng ta đã phải đóng cửa một tuần."],"ans":"C","xp":"Hỏi số liệu sản xuất tháng trước ra sao → (C) 'chúng ta đóng cửa một tuần' = ngầm cho biết sản lượng giảm → đúng.\n(A) bẫy từ cùng gốc: production → produce. (B) trả lời giờ (When).","a":"E24-T03-28.mp3"},{"n":29,"q":"When can I see the speech therapist?","qvi":"Khi nào tôi có thể gặp chuyên viên trị liệu ngôn ngữ?","opts":["A one-hour session.","Just a microphone.","How about tomorrow afternoon?"],"vi":["Một buổi kéo dài một tiếng.","Chỉ một cái micro thôi.","Chiều mai thì sao?"],"ans":"C","xp":"Câu hỏi When → (C) đề xuất thời gian 'chiều mai được không?' → đúng.\n(A) liên tưởng → session (buổi), nói thời lượng chứ không phải thời điểm. (B) liên tưởng 'speech' → microphone.","a":"E24-T03-29.mp3"},{"n":30,"q":"Aren't you picking up the clients from the airport?","qvi":"Không phải bạn sẽ đi đón khách hàng ở sân bay sao?","opts":["A product demonstration.","No, I believe Tomoko is doing that.","He prefers an aisle seat."],"vi":["Một buổi giới thiệu sản phẩm.","Không, tôi nghĩ Tomoko sẽ làm việc đó.","Anh ấy thích ghế cạnh lối đi hơn."],"ans":"B","xp":"Câu hỏi phủ định xác nhận việc đón khách → (B) 'Không, Tomoko làm việc đó' → đúng.\n(A) không liên quan. (C) liên tưởng 'airport' → aisle seat; 'He' không rõ chỉ ai.","a":"E24-T03-30.mp3"},{"n":31,"q":"How was your morning client meeting?","qvi":"Buổi họp với khách hàng sáng nay của bạn thế nào?","opts":["It's great to meet you.","No, over in conference room two.","The contract is now officially signed."],"vi":["Rất vui được gặp bạn.","Không, ở phòng họp số hai.","Hợp đồng giờ đã chính thức được ký."],"ans":"C","xp":"Hỏi cuộc họp thế nào → (C) 'hợp đồng đã chính thức được ký' = ngầm nói buổi họp thành công → đúng.\n(A) bẫy từ cùng gốc: meeting → meet. (B) câu hỏi How không trả lời bằng No; nói địa điểm.","a":"E24-T03-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","The company's making a big change this year by moving offices. It's exciting that the new space will be much bigger.","Năm nay công ty sẽ có một thay đổi lớn là chuyển văn phòng. Thật hào hứng vì không gian mới sẽ rộng hơn nhiều."],["W","Yes. Do you know what the company's planning to do with our meeting tables and chairs?","Đúng vậy. Anh có biết công ty định làm gì với bàn ghế phòng họp của chúng ta không?"],["M","Well, the new location already has furniture, so we don't need them.","À, chỗ mới đã có sẵn đồ nội thất rồi, nên chúng ta không cần chúng nữa."],["W","Why don't we donate them? The Jebreen Foundation is a local organization that picks up old furniture for donation.","Sao chúng ta không quyên góp chúng nhỉ? Quỹ Jebreen là một tổ chức địa phương chuyên đến lấy đồ nội thất cũ để quyên góp."],["M","That's a good idea. Let's talk to our directors to see what they think.","Ý hay đấy. Mình hãy nói chuyện với các giám đốc xem họ nghĩ sao."]],"qs":[{"n":32,"q":"What change is a company making?","qvi":"Công ty đang thực hiện thay đổi gì?","opts":["It is lowering some prices.","It is hiring more staffers.","It is moving to a new location.","It is expanding a product line."],"vi":["Giảm một số mức giá.","Tuyển thêm nhân viên.","Chuyển đến địa điểm mới.","Mở rộng dòng sản phẩm."],"ans":"C","xp":"Người đàn ông nói: \"The company's making a big change this year by moving offices.\" → công ty chuyển văn phòng.\nmoving offices = moving to a new location → chọn (C)."},{"n":33,"q":"What suggestion does the woman make?","qvi":"Người phụ nữ đưa ra đề xuất gì?","opts":["Updating a handbook","Donating some furniture","Creating a schedule","Downloading a software program"],"vi":["Cập nhật sổ tay hướng dẫn","Quyên góp một số đồ nội thất","Lập lịch trình","Tải một phần mềm"],"ans":"B","xp":"Sau khi người đàn ông nói chỗ mới đã có nội thất, người phụ nữ đề xuất: \"Why don't we donate them?\" (them = bàn ghế phòng họp) → quyên góp đồ nội thất → chọn (B)."},{"n":34,"q":"What will the speakers most likely do next?","qvi":"Những người nói nhiều khả năng sẽ làm gì tiếp theo?","opts":["Train a new employee","Review an application","Check a list","Talk to some directors"],"vi":["Đào tạo một nhân viên mới","Xem xét một đơn đăng ký","Kiểm tra một danh sách","Nói chuyện với các giám đốc"],"ans":"D","xp":"Cuối hội thoại người đàn ông nói: \"Let's talk to our directors to see what they think.\" → họ sẽ nói chuyện với các giám đốc → chọn (D)."}],"a":"E24-T03-32-34.mp3"},{"ns":[35,37],"script":[["M","Welcome! I'm excited to show you both around the Southeast Medical Trade Show.","Chào mừng! Tôi rất vui được dẫn hai chị đi tham quan Hội chợ Y tế Đông Nam."],["W1","Thanks for allowing us to cover the event for our newspaper. We really wanted to interview you as the organizer.","Cảm ơn anh đã cho phép chúng tôi đưa tin về sự kiện này cho tờ báo của chúng tôi. Chúng tôi rất muốn phỏng vấn anh với tư cách là người tổ chức."],["W2","Yes. How many people are you expecting to attend this trade show?","Vâng. Anh dự kiến có bao nhiêu người tham dự hội chợ này?"],["M","I'm pleased to report that registration has increased this year. We have over 2,000 participants.","Tôi vui mừng thông báo rằng năm nay số lượng đăng ký đã tăng. Chúng tôi có hơn 2.000 người tham gia."],["W2","That's impressive.","Ấn tượng thật."],["M","It's our best turnout yet.","Đây là lượng người tham dự đông nhất từ trước đến nay của chúng tôi."],["W1","Actually, before we go into the main room, can we get a photo of you in front of the poster for the show? The one on that wall?","À, trước khi vào phòng chính, chúng tôi chụp một tấm ảnh anh đứng trước tấm áp phích của hội chợ được không? Tấm trên bức tường kia ấy?"],["M","Certainly!","Tất nhiên rồi!"]],"qs":[{"n":35,"q":"Who most likely are the women?","qvi":"Hai người phụ nữ nhiều khả năng là ai?","opts":["Company executives","Journalists","Health-care professionals","Safety inspectors"],"vi":["Lãnh đạo công ty","Nhà báo","Chuyên viên y tế","Thanh tra an toàn"],"ans":"B","xp":"Người phụ nữ thứ nhất nói: \"Thanks for allowing us to cover the event for our newspaper. We really wanted to interview you...\" → đưa tin cho tờ báo, phỏng vấn → họ là nhà báo (journalists) → chọn (B).\nLưu ý: 'Medical' trong tên hội chợ là bẫy cho (C)."},{"n":36,"q":"What does the man say he is pleased about?","qvi":"Người đàn ông nói anh ấy vui mừng về điều gì?","opts":["The number of event participants","The amount of money raised","The quality of vendors","The variety of presentations"],"vi":["Số lượng người tham gia sự kiện","Số tiền quyên góp được","Chất lượng của các nhà cung cấp","Sự đa dạng của các bài thuyết trình"],"ans":"A","xp":"Người đàn ông nói: \"I'm pleased to report that registration has increased this year. We have over 2,000 participants.\" → vui vì số người đăng ký/tham gia tăng → chọn (A)."},{"n":37,"q":"What will the women do next?","qvi":"Hai người phụ nữ sẽ làm gì tiếp theo?","opts":["Watch a demonstration","Get some refreshments","Register for an event","Take a photograph"],"vi":["Xem một buổi trình diễn","Lấy đồ ăn nhẹ","Đăng ký tham gia sự kiện","Chụp ảnh"],"ans":"D","xp":"Người phụ nữ hỏi: \"before we go into the main room, can we get a photo of you in front of the poster...?\" và người đàn ông đồng ý \"Certainly!\" → họ sẽ chụp ảnh.\nget a photo = take a photograph → chọn (D)."}],"a":"E24-T03-35-37.mp3"},{"ns":[38,40],"script":[["W","Murad, I need your help. Can you spare 30 minutes?","Murad, tôi cần anh giúp. Anh có thể dành ra 30 phút không?"],["M","I have some time after lunch. How can I help?","Sau bữa trưa tôi có chút thời gian. Tôi giúp được gì?"],["W","As you know, I've been redesigning Ace Bancorp's Web site to add new online banking functions.","Như anh biết đấy, tôi đang thiết kế lại trang web của Ace Bancorp để thêm các chức năng ngân hàng trực tuyến mới."],["M","This is the client that wanted streamlined menus on their home page too, right?","Đây là khách hàng cũng muốn menu trên trang chủ được tinh gọn, đúng không?"],["W","Yes. I wonder whether you could test out the redeveloped site for me.","Đúng. Không biết anh có thể chạy thử trang web đã được làm lại giúp tôi không."],["M","I can do that. Why don't you send me a list of the specific updates you made? I'll make sure I check those.","Được thôi. Chị gửi cho tôi danh sách những cập nhật cụ thể chị đã làm nhé? Tôi sẽ kiểm tra kỹ những phần đó."]],"qs":[{"n":38,"q":"What most likely is the woman's job?","qvi":"Nghề nghiệp của người phụ nữ nhiều khả năng là gì?","opts":["Professional chef","Bank executive","Administrative assistant","Web designer"],"vi":["Đầu bếp chuyên nghiệp","Lãnh đạo ngân hàng","Trợ lý hành chính","Nhà thiết kế web"],"ans":"D","xp":"Người phụ nữ nói: \"I've been redesigning Ace Bancorp's Web site to add new online banking functions.\" → cô ấy thiết kế lại trang web → nhà thiết kế web → chọn (D).\n(B) là bẫy: Ace Bancorp là khách hàng (ngân hàng), không phải nơi cô ấy làm."},{"n":39,"q":"What will the man most likely do?","qvi":"Người đàn ông nhiều khả năng sẽ làm gì?","opts":["Buy some materials from the woman","Check the woman's work","List investment options","Update some client information"],"vi":["Mua một số tài liệu từ người phụ nữ","Kiểm tra công việc của người phụ nữ","Liệt kê các lựa chọn đầu tư","Cập nhật thông tin khách hàng"],"ans":"B","xp":"Người phụ nữ nhờ: \"I wonder whether you could test out the redeveloped site for me.\" – người đàn ông đáp: \"I can do that.\" → anh ấy sẽ chạy thử trang web cô ấy làm.\ntest out the redeveloped site = check the woman's work → chọn (B)."},{"n":40,"q":"What will the woman most likely send to the man?","qvi":"Người phụ nữ nhiều khả năng sẽ gửi gì cho người đàn ông?","opts":["A cost estimate","A revised schedule","A building plan","A list of changes"],"vi":["Một bảng ước tính chi phí","Một lịch trình đã sửa đổi","Một bản kế hoạch xây dựng","Một danh sách các thay đổi"],"ans":"D","xp":"Người đàn ông nói: \"Why don't you send me a list of the specific updates you made?\" → cô ấy sẽ gửi danh sách những cập nhật.\na list of the specific updates = a list of changes → chọn (D)."}],"a":"E24-T03-38-40.mp3"},{"ns":[41,43],"script":[["M","Excuse me. I'm trying to catch a train from this platform, but I've been waiting, and no train has arrived.","Xin lỗi. Tôi đang định bắt tàu ở sân ga này, nhưng tôi chờ mãi mà chẳng có chuyến tàu nào đến."],["W","Oh, yes. Unfortunately, some tracks are being repaired, so no trains are departing from this platform.","À vâng. Rất tiếc là một số đoạn đường ray đang được sửa chữa, nên không có chuyến tàu nào khởi hành từ sân ga này."],["M","I see. I had no idea this was happening. And I'm upset that now I'm late for an appointment.","Tôi hiểu rồi. Tôi hoàn toàn không biết chuyện này. Và tôi bực mình vì giờ tôi bị trễ một cuộc hẹn."],["W","Well, they're providing free bus service to the next few stations. You can catch a shuttle bus from the south side of the station.","À, họ đang cung cấp dịch vụ xe buýt miễn phí đến vài ga kế tiếp. Anh có thể bắt xe buýt đưa đón ở phía nam nhà ga."]],"qs":[{"n":41,"q":"Why is a train platform closed?","qvi":"Tại sao một sân ga bị đóng cửa?","opts":["Safety inspections are being conducted.","New escalators are being installed.","Tracks are being repaired.","Waiting areas are being remodeled."],"vi":["Đang tiến hành kiểm tra an toàn.","Đang lắp thang cuốn mới.","Đường ray đang được sửa chữa.","Khu vực chờ đang được cải tạo."],"ans":"C","xp":"Người phụ nữ nói: \"Unfortunately, some tracks are being repaired, so no trains are departing from this platform.\" → đường ray đang sửa → chọn (C)."},{"n":42,"q":"What does the man say he is upset about?","qvi":"Người đàn ông nói anh ấy bực mình về điều gì?","opts":["Misunderstanding some instructions","Being late for an appointment","Losing a travel pass","Boarding the wrong train"],"vi":["Hiểu sai một số hướng dẫn","Bị trễ một cuộc hẹn","Làm mất thẻ đi lại","Lên nhầm tàu"],"ans":"B","xp":"Người đàn ông nói: \"I'm upset that now I'm late for an appointment.\" → bực vì trễ hẹn → chọn (B)."},{"n":43,"q":"What will the man most likely do next?","qvi":"Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?","opts":["Purchase a snack","Take a shuttle bus","File a complaint","Download a map"],"vi":["Mua đồ ăn vặt","Đi xe buýt đưa đón","Gửi đơn khiếu nại","Tải bản đồ"],"ans":"B","xp":"Người phụ nữ hướng dẫn: \"You can catch a shuttle bus from the south side of the station.\" → anh ấy sẽ đi xe buýt đưa đón.\ncatch a shuttle bus = take a shuttle bus → chọn (B)."}],"a":"E24-T03-41-43.mp3"},{"ns":[44,46],"script":[["M","Thanks for taking my call, Ms. Hazarika.","Cảm ơn chị đã nghe máy, chị Hazarika."],["W","I understand from your e-mail that you're looking for investors in your business.","Qua e-mail của anh, tôi hiểu là anh đang tìm nhà đầu tư cho việc kinh doanh của mình."],["M","Yes. Storing bikes in small apartments is tough. That's why I've developed this space-saving bicycle rack.","Vâng. Cất xe đạp trong những căn hộ nhỏ rất khó. Vì vậy tôi đã phát triển giá để xe đạp tiết kiệm không gian này."],["W","I've seen other indoor bike racks—what's unique about yours?","Tôi đã thấy những giá để xe đạp trong nhà khác rồi – sản phẩm của anh có gì độc đáo?"],["M","Most indoor racks are one size. But not all bikes are the same. My product can be adjusted to suit different types of bicycles.","Hầu hết giá để xe trong nhà chỉ có một kích cỡ. Nhưng không phải xe đạp nào cũng giống nhau. Sản phẩm của tôi có thể điều chỉnh để phù hợp với nhiều loại xe đạp khác nhau."],["W","That's interesting. Send me your business model. I need to determine if you have a reasonable plan for expanding production and increasing sales before I make any decisions.","Thú vị đấy. Hãy gửi cho tôi mô hình kinh doanh của anh. Tôi cần xác định xem anh có kế hoạch hợp lý để mở rộng sản xuất và tăng doanh số hay không trước khi đưa ra bất kỳ quyết định nào."]],"qs":[{"n":44,"q":"Why does the man call the woman?","qvi":"Tại sao người đàn ông gọi điện cho người phụ nữ?","opts":["To provide an update on his project","To get approval on some design changes","To receive the woman's feedback on a prototype","To persuade the woman to invest in his business"],"vi":["Để cập nhật tình hình dự án của anh ấy","Để xin phê duyệt một số thay đổi thiết kế","Để nhận góp ý của người phụ nữ về sản phẩm mẫu","Để thuyết phục người phụ nữ đầu tư vào việc kinh doanh của anh ấy"],"ans":"D","xp":"Người phụ nữ nói: \"I understand from your e-mail that you're looking for investors in your business.\" → anh ấy đang tìm nhà đầu tư, gọi để thuyết phục cô ấy đầu tư → chọn (D)."},{"n":45,"q":"According to the man, what is unique about a product?","qvi":"Theo người đàn ông, sản phẩm có điểm gì độc đáo?","opts":["It is inexpensive.","It is easy to assemble.","It is adjustable.","It is lightweight."],"vi":["Nó rẻ.","Nó dễ lắp ráp.","Nó có thể điều chỉnh được.","Nó nhẹ."],"ans":"C","xp":"Người đàn ông nói: \"My product can be adjusted to suit different types of bicycles.\"\ncan be adjusted = is adjustable → chọn (C)."},{"n":46,"q":"Why does the woman request some documents?","qvi":"Tại sao người phụ nữ yêu cầu một số tài liệu?","opts":["To open a customer account","To issue a certificate","To make some copies","To evaluate a proposal"],"vi":["Để mở tài khoản khách hàng","Để cấp giấy chứng nhận","Để sao chép tài liệu","Để đánh giá một đề xuất"],"ans":"D","xp":"Người phụ nữ nói: \"Send me your business model. I need to determine if you have a reasonable plan... before I make any decisions.\" → cô ấy muốn xem xét, đánh giá kế hoạch kinh doanh.\ndetermine if you have a reasonable plan = evaluate a proposal → chọn (D)."}],"a":"E24-T03-44-46.mp3"},{"ns":[47,49],"script":[["W","Alberto, it's time to leave the studio and head over to the central bank for our interview with the director.","Alberto, đến lúc rời studio và đến ngân hàng trung ương cho buổi phỏng vấn với giám đốc rồi."],["M","Yes, I have all the cameras we'll need today.","Vâng, tôi đã có đủ máy quay cần cho hôm nay."],["W","Great. And make sure you have the special low-light lenses. I'm concerned about the poor lighting at the bank. It's pretty dark in there, and that can ruin our key interview shots.","Tốt. Và nhớ mang theo ống kính chuyên dụng cho điều kiện thiếu sáng nhé. Tôi lo về ánh sáng kém ở ngân hàng. Trong đó khá tối, và điều đó có thể làm hỏng những cảnh quay phỏng vấn quan trọng của chúng ta."],["M","Oh, yes. I have those. And by the way, our new intern Marcel Lambert is interested in joining us.","À vâng, tôi có mang rồi. Mà nhân tiện, thực tập sinh mới của chúng ta là Marcel Lambert muốn đi cùng."],["W","That's a good idea. It'll be a good experience for him.","Ý hay đấy. Đó sẽ là một trải nghiệm tốt cho cậu ấy."]],"qs":[{"n":47,"q":"What are the speakers preparing for?","qvi":"Những người nói đang chuẩn bị cho việc gì?","opts":["A construction-site visit","A safety inspection","An interview","A film festival"],"vi":["Chuyến thăm công trường","Buổi kiểm tra an toàn","Buổi phỏng vấn","Liên hoan phim"],"ans":"C","xp":"Người phụ nữ nói: \"it's time to leave the studio and head over to the central bank for our interview with the director.\" → họ chuẩn bị cho buổi phỏng vấn → chọn (C)."},{"n":48,"q":"What is the woman concerned about?","qvi":"Người phụ nữ lo lắng về điều gì?","opts":["A lighting issue","A script mistake","A material shortage","A revenue decrease"],"vi":["Vấn đề ánh sáng","Lỗi kịch bản","Thiếu vật liệu","Doanh thu giảm"],"ans":"A","xp":"Người phụ nữ nói: \"I'm concerned about the poor lighting at the bank.\"\nthe poor lighting = a lighting issue → chọn (A)."},{"n":49,"q":"Who is Marcel Lambert?","qvi":"Marcel Lambert là ai?","opts":["A company accountant","A possible client","A supervisor","An intern"],"vi":["Kế toán công ty","Một khách hàng tiềm năng","Một người giám sát","Một thực tập sinh"],"ans":"D","xp":"Người đàn ông nói: \"our new intern Marcel Lambert is interested in joining us.\" → Marcel Lambert là thực tập sinh (intern) → chọn (D)."}],"a":"E24-T03-47-49.mp3"},{"ns":[50,52],"script":[["W","Waseem, I know you've been very busy this morning, but did you have time to take care of the photocopies I asked for?","Waseem, tôi biết sáng nay anh rất bận, nhưng anh đã có thời gian lo phần photo tài liệu tôi nhờ chưa?"],["M","Oh, yes, those are all ready.","À vâng, xong hết rồi."],["W","Excellent! Thanks. By the way, how are the preparations coming along for Sabine Hoffman's retirement party?","Tuyệt quá! Cảm ơn anh. Nhân tiện, việc chuẩn bị cho tiệc nghỉ hưu của Sabine Hoffman đến đâu rồi?"],["M","Great. I've booked a room and invited everyone on our team to the event. I'll call the caterer next.","Tốt lắm. Tôi đã đặt phòng và mời mọi người trong nhóm đến dự. Tiếp theo tôi sẽ gọi cho bên cung cấp đồ ăn."],["W","You know, I'm sure she would love to celebrate with her former colleagues from other teams as well, if it's not too much trouble to invite them.","Anh biết không, tôi chắc là bà ấy cũng muốn ăn mừng cùng các đồng nghiệp cũ ở những nhóm khác nữa, nếu mời họ không quá phiền."],["M","Sure. I booked conference room B, but I'll go ahead and change that.","Được chứ. Tôi đã đặt phòng họp B, nhưng tôi sẽ đổi phòng ngay."]],"qs":[{"n":50,"q":"What does the woman thank the man for?","qvi":"Người phụ nữ cảm ơn người đàn ông vì điều gì?","opts":["Distributing some fliers","Completing some calculations","Placing a catering order","Preparing some paper copies"],"vi":["Phát tờ rơi","Hoàn thành một số phép tính","Đặt đồ ăn","Chuẩn bị các bản photo"],"ans":"D","xp":"Người phụ nữ hỏi: \"did you have time to take care of the photocopies I asked for?\" – người đàn ông: \"those are all ready.\" – cô ấy nói \"Thanks.\" → cảm ơn vì đã chuẩn bị bản photo.\ntake care of the photocopies = preparing some paper copies → chọn (D)."},{"n":51,"q":"Why is a gathering being planned?","qvi":"Tại sao một buổi họp mặt đang được lên kế hoạch?","opts":["A colleague was promoted.","The company won an award.","A colleague will be retiring.","The company will be training employees."],"vi":["Một đồng nghiệp được thăng chức.","Công ty giành được giải thưởng.","Một đồng nghiệp sắp nghỉ hưu.","Công ty sẽ đào tạo nhân viên."],"ans":"C","xp":"Người phụ nữ hỏi: \"how are the preparations coming along for Sabine Hoffman's retirement party?\" → tiệc nghỉ hưu của một đồng nghiệp.\nretirement party → A colleague will be retiring → chọn (C)."},{"n":52,"q":"What does the man imply when he says, \"I booked conference room B\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"Tôi đã đặt phòng họp B\"?","opts":["A room is too small.","An invitation is incorrect.","No other conference rooms were available.","Another administrative assistant was too busy."],"vi":["Một căn phòng quá nhỏ.","Một lời mời bị sai.","Không còn phòng họp nào khác trống.","Một trợ lý hành chính khác quá bận."],"ans":"A","xp":"Câu hỏi hàm ý. Người phụ nữ muốn mời thêm đồng nghiệp cũ từ các nhóm khác. Người đàn ông nói \"I booked conference room B, but I'll go ahead and change that.\" → phòng B đã đặt sẽ không đủ chỗ khi mời thêm người nên phải đổi → phòng quá nhỏ → chọn (A)."}],"a":"E24-T03-50-52.mp3"},{"ns":[53,55],"script":[["M","Hi. I'm Kota Ogawa from Langston Limited. I have an appointment with Ms. Ishikawa to view your hotel facilities for my company's upcoming retreat.","Xin chào. Tôi là Kota Ogawa đến từ công ty Langston Limited. Tôi có hẹn với bà Ishikawa để xem cơ sở vật chất của khách sạn cho chuyến nghỉ dưỡng sắp tới của công ty tôi."],["W1","I know that she's been expecting you, and she just wrapped up an urgent phone call. She's on her way now.","Tôi biết bà ấy đang đợi anh, và bà ấy vừa kết thúc một cuộc điện thoại gấp. Bà ấy đang đến ngay đây."],["W2","Hi. You must be Mr. Ogawa. I'm Hikaru Ishikawa. Why don't we see our largest conference room first?","Xin chào. Chắc anh là anh Ogawa. Tôi là Hikaru Ishikawa. Chúng ta xem phòng hội nghị lớn nhất trước nhé?"],["M","Great. And I'd also like to look at the guest rooms. All the rooms have a high-speed Internet connection, right?","Tuyệt. Và tôi cũng muốn xem các phòng nghỉ. Tất cả các phòng đều có kết nối Internet tốc độ cao, đúng không?"],["W2","Yes, and we have a fully equipped recreation area as well.","Đúng vậy, và chúng tôi còn có một khu giải trí được trang bị đầy đủ nữa."]],"qs":[{"n":53,"q":"What type of event is the man planning?","qvi":"Người đàn ông đang lên kế hoạch cho loại sự kiện nào?","opts":["A retirement banquet","A company retreat","A press conference","A fund-raiser"],"vi":["Tiệc chia tay nghỉ hưu","Chuyến nghỉ dưỡng/tĩnh tâm của công ty","Buổi họp báo","Sự kiện gây quỹ"],"ans":"B","xp":"Người đàn ông nói đến xem khách sạn \"for my company's upcoming retreat\" (cho chuyến nghỉ dưỡng sắp tới của công ty) → chọn (B)."},{"n":54,"q":"Why was Ms. Ishikawa delayed?","qvi":"Tại sao bà Ishikawa bị chậm trễ?","opts":["She was stuck in traffic.","She was at lunch.","She was setting up a room.","She was on the phone."],"vi":["Bà ấy bị kẹt xe.","Bà ấy đang ăn trưa.","Bà ấy đang chuẩn bị phòng.","Bà ấy đang nghe điện thoại."],"ans":"D","xp":"Người phụ nữ thứ nhất nói: \"she just wrapped up an urgent phone call\" (bà ấy vừa kết thúc một cuộc gọi gấp) → bà ấy đến muộn vì đang nói chuyện điện thoại → chọn (D)."},{"n":55,"q":"What does the man inquire about?","qvi":"Người đàn ông hỏi về điều gì?","opts":["An airport shuttle","Late checkout","A fitness center","Internet capabilities"],"vi":["Xe đưa đón sân bay","Trả phòng muộn","Phòng tập thể dục","Khả năng kết nối Internet"],"ans":"D","xp":"Người đàn ông hỏi: \"All the rooms have a high-speed Internet connection, right?\" → hỏi về Internet → chọn (D)."}],"a":"E24-T03-53-55.mp3"},{"ns":[56,58],"script":[["W","Look at these results! Sales of pineapples have gone up a lot this month at our store.","Nhìn kết quả này xem! Tháng này doanh số dứa ở cửa hàng mình tăng lên rất nhiều."],["M","It must be the pineapple-peeling machine we installed in the fruit aisle. Customers like watching it peel and slice their pineapple for them.","Chắc là nhờ cái máy gọt dứa mình lắp ở dãy hàng trái cây. Khách hàng thích xem máy gọt vỏ và cắt dứa cho họ."],["W","It is a unique experience. I think we should install one in our other two store branches.","Đó là một trải nghiệm độc đáo. Tôi nghĩ chúng ta nên lắp một cái ở hai chi nhánh cửa hàng còn lại."],["M","I'm not sure about that. I think the novelty will wear off in a few weeks. Let's wait to see if sales numbers stay high before we invest in any more.","Tôi không chắc lắm. Tôi nghĩ sự mới lạ sẽ hết sau vài tuần. Mình hãy chờ xem doanh số có tiếp tục cao không rồi hẵng đầu tư thêm."]],"qs":[{"n":56,"q":"Where does the conversation most likely take place?","qvi":"Cuộc hội thoại nhiều khả năng diễn ra ở đâu?","opts":["At a restaurant","At a shipping dock","At a farm","At a supermarket"],"vi":["Ở nhà hàng","Ở bến bốc dỡ hàng","Ở trang trại","Ở siêu thị"],"ans":"D","xp":"Người phụ nữ nói: \"Sales of pineapples have gone up a lot this month at our store.\" và người đàn ông nhắc đến \"the fruit aisle\" (dãy hàng trái cây) → đây là siêu thị → chọn (D)."},{"n":57,"q":"What does the man say is popular?","qvi":"Người đàn ông nói cái gì được ưa chuộng?","opts":["A colorful package design","A self-service machine","A same-day delivery service","A television advertisement"],"vi":["Một thiết kế bao bì nhiều màu sắc","Một chiếc máy tự phục vụ","Dịch vụ giao hàng trong ngày","Một quảng cáo trên truyền hình"],"ans":"B","xp":"Người đàn ông nói: \"It must be the pineapple-peeling machine we installed... Customers like watching it peel and slice their pineapple for them.\" → khách thích chiếc máy gọt dứa tự động.\npineapple-peeling machine = a self-service machine; Customers like = popular → chọn (B)."},{"n":58,"q":"What does the man suggest doing?","qvi":"Người đàn ông đề xuất làm gì?","opts":["Waiting for some data","Issuing a refund","Hiring more staff","Rearranging some merchandise"],"vi":["Chờ thêm số liệu","Hoàn tiền","Thuê thêm nhân viên","Sắp xếp lại hàng hóa"],"ans":"A","xp":"Người đàn ông nói: \"Let's wait to see if sales numbers stay high before we invest in any more.\" → chờ xem số liệu doanh thu.\nwait to see if sales numbers stay high = waiting for some data → chọn (A)."}],"a":"E24-T03-56-58.mp3"},{"ns":[59,61],"script":[["M","Ingrid, we've had three patients this week who had to cancel their dental appointments at the last minute.","Ingrid, tuần này chúng ta có ba bệnh nhân phải hủy lịch hẹn nha khoa vào phút chót."],["W","Yes, that's a problem. Other patients might have taken those available appointments if we'd been able to contact them in time.","Đúng, đó là một vấn đề. Lẽ ra những bệnh nhân khác đã có thể lấy các lịch hẹn trống đó nếu chúng ta liên lạc với họ kịp thời."],["M","You know, I have an idea. I recently scheduled a doctor's visit online, and there was an option to receive a text-message notification if an earlier slot became available. You just have to check a box. What do you think about something like that?","Chị biết không, tôi có một ý này. Gần đây tôi đặt lịch khám bác sĩ trên mạng, và có một tùy chọn nhận thông báo bằng tin nhắn nếu có lịch trống sớm hơn. Chỉ cần đánh dấu vào một ô thôi. Chị thấy làm như vậy thế nào?"],["W","That would be helpful. I have some time this afternoon. I'll look into software packages that include that feature.","Như vậy sẽ hữu ích đấy. Chiều nay tôi có chút thời gian. Tôi sẽ tìm hiểu các gói phần mềm có tính năng đó."]],"qs":[{"n":59,"q":"What are the speakers discussing?","qvi":"Những người nói đang thảo luận về điều gì?","opts":["Relocating their office","Attracting new patients","Scheduling appointments","Finding qualified staff"],"vi":["Chuyển văn phòng","Thu hút bệnh nhân mới","Sắp xếp lịch hẹn","Tìm nhân viên có trình độ"],"ans":"C","xp":"Người đàn ông nói: \"we've had three patients this week who had to cancel their dental appointments at the last minute.\" – người phụ nữ: \"Other patients might have taken those available appointments...\" → họ bàn về việc sắp xếp lịch hẹn → chọn (C)."},{"n":60,"q":"Why does the man say, \"You just have to check a box\"?","qvi":"Tại sao người đàn ông nói \"Chỉ cần đánh dấu vào một ô thôi\"?","opts":["To request some performance feedback","To express concern about a procedure","To correct a misunderstanding","To support a suggestion"],"vi":["Để yêu cầu nhận xét về hiệu quả công việc","Để bày tỏ lo ngại về một quy trình","Để sửa một sự hiểu lầm","Để củng cố cho một đề xuất"],"ans":"D","xp":"Câu hỏi hàm ý. Người đàn ông đưa ra ý tưởng: cho bệnh nhân nhận tin nhắn thông báo khi có lịch trống sớm hơn, rồi nói \"You just have to check a box\" → nhấn mạnh cách này rất đơn giản, để ủng hộ đề xuất của mình → chọn (D)."},{"n":61,"q":"What does the woman offer to do this afternoon?","qvi":"Người phụ nữ đề nghị làm gì vào chiều nay?","opts":["Investigate options","Revise a budget","Contact a patient","Update a Web site"],"vi":["Tìm hiểu các lựa chọn","Sửa đổi ngân sách","Liên lạc với một bệnh nhân","Cập nhật trang web"],"ans":"A","xp":"Người phụ nữ nói: \"I have some time this afternoon. I'll look into software packages that include that feature.\"\nlook into software packages = investigate options → chọn (A)."}],"a":"E24-T03-59-61.mp3"},{"ns":[62,64],"script":[["M","Hi, Raquel. Have you had a chance to look for something I could buy the employees for the New Year? I want to be sure I thank everyone for their hard work.","Chào Raquel. Chị đã có dịp tìm món gì đó tôi có thể mua tặng nhân viên dịp năm mới chưa? Tôi muốn cảm ơn mọi người vì đã làm việc chăm chỉ."],["W","Well, a good quality travel mug would be appreciated.","À, một chiếc cốc giữ nhiệt mang đi chất lượng tốt chắc sẽ được mọi người thích."],["M","Interesting. Which one would you recommend?","Hay đấy. Chị gợi ý loại nào?"],["W","Take a look at this brochure. This company has a variety of designs—sea animals, sky scenes. I like the medium mug with the Desert Roaming design.","Anh xem tờ quảng cáo này. Công ty này có nhiều mẫu thiết kế – động vật biển, cảnh bầu trời. Tôi thích chiếc cốc cỡ vừa với mẫu Desert Roaming."],["M","That is nice. I'll sign off on that order request once you fill out the paperwork.","Đẹp đấy. Tôi sẽ ký duyệt yêu cầu đặt hàng đó khi chị điền xong giấy tờ."]],"qs":[{"n":62,"q":"Who will the man give some gifts to?","qvi":"Người đàn ông sẽ tặng quà cho ai?","opts":["Conference participants","Employees","Contest winners","Visitors"],"vi":["Người tham dự hội nghị","Nhân viên","Người thắng cuộc thi","Khách tham quan"],"ans":"B","xp":"Người đàn ông hỏi: \"Have you had a chance to look for something I could buy the employees for the New Year?\" → quà dành cho nhân viên → chọn (B)."},{"n":63,"q":"Look at the graphic. How much is the mug that the woman likes?","qvi":"Hãy nhìn hình. Chiếc cốc người phụ nữ thích giá bao nhiêu?","opts":["$15","$20","$23","$25"],"vi":["15 đô","20 đô","23 đô","25 đô"],"ans":"C","xp":"Người phụ nữ nói: \"I like the medium mug with the Desert Roaming design.\" Nhìn bảng: Desert Roaming – medium mug – $23 → chọn (C)."},{"n":64,"q":"What does the man say he will do?","qvi":"Người đàn ông nói anh ấy sẽ làm gì?","opts":["Submit a registration form","Adjust a work schedule","Approve an order","Ask for a bulk-pricing rate"],"vi":["Nộp mẫu đăng ký","Điều chỉnh lịch làm việc","Phê duyệt một đơn hàng","Hỏi giá mua số lượng lớn"],"ans":"C","xp":"Người đàn ông nói: \"I'll sign off on that order request once you fill out the paperwork.\"\nsign off on (ký duyệt) that order request = approve an order → chọn (C)."}],"a":"E24-T03-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Here's the map that you requested for next week's shoot, for the driving scene.","Đây là bản đồ chị yêu cầu cho buổi quay tuần sau, cho cảnh lái xe."],["W","Great—let's see. The actors will be driving north on Maple Street. Hmm...","Tốt quá – để xem nào. Các diễn viên sẽ lái xe về hướng bắc trên phố Maple. Hừm..."],["M","Is something wrong?","Có vấn đề gì sao?"],["W","We may need to alter the route so it'll be less difficult for our camera operators to follow the action.","Có lẽ chúng ta cần thay đổi lộ trình để những người quay phim đỡ vất vả hơn khi bám theo cảnh hành động."],["M","OK. What are you thinking?","Được. Chị đang nghĩ thế nào?"],["W","Instead of turning left on Elm Lane, let's have them turn right and park in front of the hair salon.","Thay vì rẽ trái vào đường Elm, hãy cho họ rẽ phải và đỗ xe trước tiệm làm tóc."],["M","OK. I'll arrange for that road to be closed while we're working and alert the business owners.","Được. Tôi sẽ sắp xếp để con đường đó được phong tỏa trong lúc chúng ta quay và báo cho các chủ cửa hàng."]],"qs":[{"n":65,"q":"What industry do the speakers most likely work in?","qvi":"Những người nói nhiều khả năng làm việc trong ngành nào?","opts":["Tourism","Film","Engineering","Transportation"],"vi":["Du lịch","Điện ảnh","Kỹ thuật","Vận tải"],"ans":"B","xp":"Người đàn ông nói: \"Here's the map that you requested for next week's shoot, for the driving scene.\" và người phụ nữ nhắc đến \"The actors\", \"camera operators\" → họ làm trong ngành điện ảnh (phim) → chọn (B)."},{"n":66,"q":"Why does the woman want to make a change?","qvi":"Tại sao người phụ nữ muốn thay đổi?","opts":["Some equipment is not available.","A new business is opening.","A process will be easier.","Costs will be lower."],"vi":["Một số thiết bị không có sẵn.","Một cửa hàng mới sắp khai trương.","Một công đoạn sẽ dễ dàng hơn.","Chi phí sẽ thấp hơn."],"ans":"C","xp":"Người phụ nữ nói: \"We may need to alter the route so it'll be less difficult for our camera operators to follow the action.\"\nalter = make a change; less difficult = easier → chọn (C)."},{"n":67,"q":"Look at the graphic. Which road should be closed?","qvi":"Hãy nhìn hình. Con đường nào nên được phong tỏa?","opts":["Bangalore Avenue","Dublin Avenue","Polly Street","Elm Lane"],"vi":["Đại lộ Bangalore","Đại lộ Dublin","Phố Polly","Đường Elm"],"ans":"A","xp":"Người phụ nữ đề xuất: \"let's have them turn right and park in front of the hair salon.\" Người đàn ông: \"I'll arrange for that road to be closed...\" → con đường có tiệm làm tóc (Hair Salon). Trên bản đồ, Hair Salon nằm trên Bangalore Avenue → chọn (A).\n(D) Elm Lane là hướng rẽ trái ban đầu, đã bị thay đổi."}],"a":"E24-T03-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["W","Hi, Pablo. I wanted to talk to you about the video game we designed—the one we're launching soon.","Chào Pablo. Tôi muốn nói chuyện với anh về trò chơi điện tử mà chúng ta thiết kế – trò mà chúng ta sắp ra mắt ấy."],["M","Sure. Did something come up?","Được chứ. Có chuyện gì à?"],["W","Well, I think the jungle level looks great. But in the underwater level, there's a problem with the part where the characters discover the lost city in the ocean. As I was going over the layout, I found a glitch in the game play.","À, tôi thấy màn rừng rậm trông rất tuyệt. Nhưng ở màn dưới nước, có vấn đề ở đoạn các nhân vật khám phá thành phố bị thất lạc dưới đại dương. Khi xem lại bố cục, tôi phát hiện một lỗi trong lối chơi."],["M","Oh, OK. We still have time to fix it.","À, được. Chúng ta vẫn còn thời gian để sửa."],["W","Yes, but we should work on it as soon as possible. I could put some extra time in over the weekend. How about you?","Đúng, nhưng chúng ta nên làm càng sớm càng tốt. Tôi có thể làm thêm vào cuối tuần. Còn anh thì sao?"],["M","Probably—just let me check my calendar.","Chắc là được – để tôi xem lịch đã."]],"qs":[{"n":68,"q":"What are the speakers preparing for?","qvi":"Những người nói đang chuẩn bị cho việc gì?","opts":["A video-game convention","An in-store demonstration","A product launch","A focus-group session"],"vi":["Một hội chợ trò chơi điện tử","Một buổi giới thiệu tại cửa hàng","Việc ra mắt sản phẩm","Một buổi thảo luận nhóm khảo sát"],"ans":"C","xp":"Người phụ nữ nói: \"the video game we designed—the one we're launching soon.\" → họ chuẩn bị ra mắt trò chơi.\nthe one we're launching soon = a product launch → chọn (C).\n(A) là bẫy vì lặp từ 'video game'."},{"n":69,"q":"Look at the graphic. Which level is the woman concerned about?","qvi":"Hãy nhìn hình. Người phụ nữ lo lắng về màn chơi nào?","opts":["Level 1","Level 2","Level 3","Level 4"],"vi":["Màn 1","Màn 2","Màn 3","Màn 4"],"ans":"B","xp":"Người phụ nữ nói: \"But in the underwater level, there's a problem...\" (màn dưới nước, nơi khám phá thành phố dưới đại dương). Trong bảng, màn liên quan đến biển là Ocean Kingdom – Level 2 → chọn (B)."},{"n":70,"q":"What does the woman suggest doing?","qvi":"Người phụ nữ đề xuất làm gì?","opts":["Contacting a colleague","Postponing an event","Working over the weekend","Making travel arrangements"],"vi":["Liên lạc với một đồng nghiệp","Hoãn một sự kiện","Làm việc vào cuối tuần","Sắp xếp chuyến đi"],"ans":"C","xp":"Người phụ nữ nói: \"we should work on it as soon as possible. I could put some extra time in over the weekend. How about you?\" → cô ấy đề xuất làm thêm vào cuối tuần → chọn (C)."}],"a":"E24-T03-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","At Volkov Tire and Auto Service, we're proud to serve the Livingstone Valley area. We offer quality automotive maintenance and repairs at affordable prices.","Tại Volkov Tire and Auto Service, chúng tôi tự hào phục vụ khu vực Livingstone Valley. Chúng tôi cung cấp dịch vụ bảo dưỡng và sửa chữa ô tô chất lượng với giá cả phải chăng."],["","Our mechanics are the best in the industry, and our dedication to customer service shows. Once again, readers of the Livingstone Valley Chronicle have awarded us with the title of Best in the Valley. That's five years in a row!","Thợ máy của chúng tôi giỏi nhất trong ngành, và sự tận tâm của chúng tôi với khách hàng thể hiện rõ. Một lần nữa, độc giả của tờ Livingstone Valley Chronicle đã trao cho chúng tôi danh hiệu Tốt nhất Thung lũng. Đó là năm năm liên tiếp!"],["","And to celebrate, we're offering ten percent off all oil changes in July. To get this deal, you must schedule an appointment, either by phone or online. Appointments are filling up fast!","Và để ăn mừng, chúng tôi giảm giá 10% cho tất cả các lần thay dầu trong tháng Bảy. Để nhận ưu đãi này, quý khách phải đặt lịch hẹn qua điện thoại hoặc trực tuyến. Lịch hẹn đang kín rất nhanh!"]],"qs":[{"n":71,"q":"What kind of business is being advertised?","qvi":"Loại hình doanh nghiệp nào đang được quảng cáo?","opts":["A health-care clinic","A computer service store","An auto repair shop","A real estate agency"],"vi":["Một phòng khám y tế","Một cửa hàng dịch vụ máy tính","Một tiệm sửa chữa ô tô","Một công ty bất động sản"],"ans":"C","xp":"Người nói giới thiệu: \"At Volkov Tire and Auto Service...\" và \"We offer quality automotive maintenance and repairs...\" → tiệm bảo dưỡng, sửa chữa ô tô → chọn (C)."},{"n":72,"q":"Why is a business celebrating?","qvi":"Tại sao doanh nghiệp đang ăn mừng?","opts":["It has been operating for ten years.","It has doubled its customer base.","It has won an award.","It has opened a new location."],"vi":["Nó đã hoạt động được mười năm.","Lượng khách hàng tăng gấp đôi.","Nó đã giành được giải thưởng.","Nó đã mở chi nhánh mới."],"ans":"C","xp":"Người nói: \"readers of the Livingstone Valley Chronicle have awarded us with the title of Best in the Valley... And to celebrate...\" → ăn mừng vì được trao danh hiệu.\nhave awarded us with the title = has won an award → chọn (C).\n(A) bẫy: 'ten percent', 'five years' không phải mười năm hoạt động."},{"n":73,"q":"What do the listeners need to do to obtain a discount?","qvi":"Người nghe cần làm gì để được giảm giá?","opts":["Make an appointment","Print out a coupon","Attend an open house","Refer a friend"],"vi":["Đặt lịch hẹn","In phiếu giảm giá","Tham dự buổi giới thiệu mở cửa","Giới thiệu một người bạn"],"ans":"A","xp":"Người nói: \"To get this deal, you must schedule an appointment, either by phone or online.\"\nschedule an appointment = make an appointment → chọn (A)."}],"a":"E24-T03-71-73.mp3"},{"ns":[74,76],"script":[["","Today's episode of the Financial Parade Podcast is about the possibilities and limitations of marketing on social media. How can businesses improve on their marketing efforts and do a better job of reaching their target audience?","Tập hôm nay của Financial Parade Podcast nói về những khả năng và hạn chế của việc tiếp thị trên mạng xã hội. Làm thế nào để các doanh nghiệp cải thiện hoạt động tiếp thị và tiếp cận khách hàng mục tiêu tốt hơn?"],["","To help us answer this, we are joined by Magali Bertrand, Marketing director at Blue Lane Consulting. Ms. Bertrand is a frequent guest on the show because she is good at taking complex business principles and breaking them down to offer clear, simple advice.","Để giúp chúng ta trả lời câu hỏi này, hôm nay có sự tham gia của Magali Bertrand, giám đốc tiếp thị tại Blue Lane Consulting. Bà Bertrand là khách mời thường xuyên của chương trình vì bà rất giỏi lấy những nguyên tắc kinh doanh phức tạp và phân tích chúng để đưa ra lời khuyên rõ ràng, đơn giản."],["","But first, I'd like to discuss the results of my recent survey where you all shared your approaches to product placement.","Nhưng trước tiên, tôi muốn bàn về kết quả cuộc khảo sát gần đây của tôi, trong đó tất cả các bạn đã chia sẻ cách tiếp cận của mình đối với quảng cáo lồng ghép sản phẩm."]],"qs":[{"n":74,"q":"What is the podcast episode about?","qvi":"Tập podcast nói về chủ đề gì?","opts":["Marketing strategies","Commercial real estate","Customer loyalty","Staff management"],"vi":["Chiến lược tiếp thị","Bất động sản thương mại","Lòng trung thành của khách hàng","Quản lý nhân viên"],"ans":"A","xp":"Người nói: \"Today's episode of the Financial Parade Podcast is about the possibilities and limitations of marketing on social media.\" → chủ đề về tiếp thị → chọn (A)."},{"n":75,"q":"What does the speaker say Ms. Bertrand is good at?","qvi":"Người nói cho biết bà Bertrand giỏi việc gì?","opts":["Designing billboard ads","Solving budget problems","Explaining complicated ideas","Creating training programs"],"vi":["Thiết kế quảng cáo trên biển lớn ngoài trời","Giải quyết vấn đề ngân sách","Giải thích những ý tưởng phức tạp","Xây dựng chương trình đào tạo"],"ans":"C","xp":"Người nói: \"she is good at taking complex business principles and breaking them down to offer clear, simple advice.\" → biến điều phức tạp thành lời khuyên đơn giản.\ncomplex business principles = complicated ideas → chọn (C)."},{"n":76,"q":"What will the speaker discuss next?","qvi":"Người nói sẽ bàn về điều gì tiếp theo?","opts":["Breaking news","Survey results","Upcoming contests","Future episode topics"],"vi":["Tin nóng","Kết quả khảo sát","Các cuộc thi sắp tới","Chủ đề các tập sau"],"ans":"B","xp":"Cuối bài: \"But first, I'd like to discuss the results of my recent survey...\" → tiếp theo sẽ nói về kết quả khảo sát → chọn (B)."}],"a":"E24-T03-74-76.mp3"},{"ns":[77,79],"script":[["","Next Wednesday, Arlington Landscaping will deliver the potted plants we ordered to brighten up the common areas in our office. Studies have shown that plants are great stress relievers and can increase workplace productivity.","Thứ Tư tới, công ty Arlington Landscaping sẽ giao những chậu cây chúng ta đã đặt để làm không gian chung trong văn phòng thêm tươi sáng. Các nghiên cứu cho thấy cây xanh giúp giảm căng thẳng rất tốt và có thể tăng năng suất làm việc."],["","We think you'll find that this is a great improvement to our work environment. If you'd like a small plant for your desk, the company will cover the cost. To choose your plant, please check the catalog in the staff room. It has photos and care instructions.","Chúng tôi nghĩ các bạn sẽ thấy đây là một cải thiện lớn cho môi trường làm việc của chúng ta. Nếu bạn muốn một chậu cây nhỏ để bàn, công ty sẽ chi trả. Để chọn cây, vui lòng xem cuốn danh mục trong phòng nhân viên. Trong đó có hình ảnh và hướng dẫn chăm sóc."]],"qs":[{"n":77,"q":"What will be delivered next Wednesday?","qvi":"Thứ gì sẽ được giao vào thứ Tư tới?","opts":["Office furniture","Color printers","Potted plants","Framed artwork"],"vi":["Đồ nội thất văn phòng","Máy in màu","Cây trồng trong chậu","Tranh đóng khung"],"ans":"C","xp":"Người nói: \"Next Wednesday, Arlington Landscaping will deliver the potted plants we ordered...\" → chọn (C)."},{"n":78,"q":"What does the speaker say about productivity?","qvi":"Người nói nói gì về năng suất?","opts":["It has been improving recently.","It is higher in other departments.","It can be improved by office surroundings.","It can be increased by working in groups."],"vi":["Gần đây nó đang được cải thiện.","Nó cao hơn ở các phòng ban khác.","Nó có thể được cải thiện nhờ môi trường văn phòng.","Nó có thể tăng lên nhờ làm việc nhóm."],"ans":"C","xp":"Người nói: \"Studies have shown that plants... can increase workplace productivity. We think you'll find that this is a great improvement to our work environment.\" → cây xanh (môi trường xung quanh) giúp tăng năng suất.\nwork environment = office surroundings → chọn (C)."},{"n":79,"q":"According to the speaker, what is available in the staff room?","qvi":"Theo người nói, trong phòng nhân viên có sẵn thứ gì?","opts":["A catalog","A vending machine","Staff uniforms","Exercise equipment"],"vi":["Một cuốn danh mục","Một máy bán hàng tự động","Đồng phục nhân viên","Dụng cụ tập thể dục"],"ans":"A","xp":"Người nói: \"To choose your plant, please check the catalog in the staff room.\" → chọn (A)."}],"a":"E24-T03-77-79.mp3"},{"ns":[80,82],"script":[["","In local news, the abandoned shoe factory in the central business district is finally getting a makeover. The building has been empty for three years since the factory moved to its new, larger space south of town.","Tin địa phương: nhà máy giày bỏ hoang ở khu thương mại trung tâm cuối cùng cũng được cải tạo. Tòa nhà đã bỏ trống ba năm kể từ khi nhà máy chuyển đến địa điểm mới, rộng hơn ở phía nam thị trấn."],["","After hearing many proposals, the town council voted last night to sell the building to developer Matthew Hughes, who will convert it into family housing: ten modern, comfortable units with a parking garage underground.","Sau khi nghe nhiều đề xuất, tối qua hội đồng thị trấn đã bỏ phiếu bán tòa nhà cho nhà phát triển Matthew Hughes, người sẽ chuyển đổi nó thành nhà ở cho gia đình: mười căn hộ hiện đại, tiện nghi cùng bãi đỗ xe ngầm."],["","Up next, it looks like the rain is on the way out, giving way to blue skies this weekend. Samantha is here to tell us all about it.","Tiếp theo, có vẻ như mưa sắp tạnh, nhường chỗ cho bầu trời trong xanh vào cuối tuần này. Samantha sẽ cho chúng ta biết chi tiết."]],"qs":[{"n":80,"q":"According to the speaker, what happened three years ago?","qvi":"Theo người nói, chuyện gì đã xảy ra ba năm trước?","opts":["A council member was elected.","A local tax law changed.","A train station opened.","A business relocated."],"vi":["Một thành viên hội đồng được bầu.","Một luật thuế địa phương thay đổi.","Một nhà ga xe lửa khai trương.","Một doanh nghiệp đã chuyển địa điểm."],"ans":"D","xp":"Người nói: \"The building has been empty for three years since the factory moved to its new, larger space south of town.\" → ba năm trước nhà máy chuyển đi.\nthe factory moved = a business relocated → chọn (D)."},{"n":81,"q":"Who is Matthew Hughes?","qvi":"Matthew Hughes là ai?","opts":["A banker","A real estate developer","A government official","A store owner"],"vi":["Một chủ ngân hàng","Một nhà phát triển bất động sản","Một quan chức chính quyền","Một chủ cửa hàng"],"ans":"B","xp":"Người nói: \"sell the building to developer Matthew Hughes, who will convert it into family housing\" → ông ấy mua tòa nhà để làm nhà ở → nhà phát triển bất động sản → chọn (B)."},{"n":82,"q":"What will the listeners hear about next?","qvi":"Người nghe sẽ nghe về điều gì tiếp theo?","opts":["A sporting event","Street closures","The weather","Parking fines"],"vi":["Một sự kiện thể thao","Việc phong tỏa đường","Thời tiết","Tiền phạt đỗ xe"],"ans":"C","xp":"Người nói: \"Up next, it looks like the rain is on the way out, giving way to blue skies this weekend. Samantha is here to tell us all about it.\" → rain, blue skies = thời tiết → chọn (C)."}],"a":"E24-T03-80-82.mp3"},{"ns":[83,85],"script":[["","Before we end this transportation agency meeting, I want to give you an update on the Springdale bridge replacement project. The project is moving forward. However, we are more than six months past the scheduled completion date.","Trước khi kết thúc cuộc họp của cơ quan giao thông hôm nay, tôi muốn cập nhật cho các bạn về dự án thay thế cầu Springdale. Dự án đang tiến triển. Tuy nhiên, chúng ta đã trễ hơn sáu tháng so với ngày hoàn thành dự kiến."],["","But this is just one of our many projects. Now, this delay is frustrating to residents who are dealing with traffic congestion. Therefore, I strongly recommend that we hold a press conference to address specific concerns.","Nhưng đây chỉ là một trong rất nhiều dự án của chúng ta. Hiện giờ, sự chậm trễ này đang khiến người dân phải đối mặt với tình trạng ùn tắc giao thông rất bực bội. Vì vậy, tôi đặc biệt đề nghị chúng ta tổ chức một buổi họp báo để giải đáp những mối lo ngại cụ thể."]],"qs":[{"n":83,"q":"What is the speaker discussing?","qvi":"Người nói đang thảo luận về điều gì?","opts":["The renovation of a train station","The construction of a tunnel","The replacement of a bridge","The repaving of a bicycle trail"],"vi":["Việc cải tạo nhà ga xe lửa","Việc xây dựng đường hầm","Việc thay thế một cây cầu","Việc trải nhựa lại đường dành cho xe đạp"],"ans":"C","xp":"Người nói: \"I want to give you an update on the Springdale bridge replacement project.\"\nbridge replacement project = the replacement of a bridge → chọn (C)."},{"n":84,"q":"Why does the speaker say, \"this is just one of our many projects\"?","qvi":"Tại sao người nói nói \"đây chỉ là một trong rất nhiều dự án của chúng ta\"?","opts":["To propose a change of topic","To explain a delay","To praise some employees","To ask for help"],"vi":["Để đề nghị đổi chủ đề","Để giải thích lý do chậm trễ","Để khen ngợi một số nhân viên","Để nhờ giúp đỡ"],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó người nói thừa nhận: \"we are more than six months past the scheduled completion date.\" Sau đó nói \"But this is just one of our many projects\" → ý là cơ quan phải làm rất nhiều dự án cùng lúc nên dự án này bị trễ → giải thích lý do chậm trễ → chọn (B)."},{"n":85,"q":"What does the speaker suggest doing?","qvi":"Người nói đề xuất làm gì?","opts":["Organizing an opening ceremony","Scheduling a television interview","Revising a design","Meeting with the press"],"vi":["Tổ chức lễ khai trương","Lên lịch phỏng vấn truyền hình","Sửa đổi bản thiết kế","Gặp gỡ báo chí"],"ans":"D","xp":"Người nói: \"I strongly recommend that we hold a press conference to address specific concerns.\"\nhold a press conference (họp báo) = meeting with the press → chọn (D)."}],"a":"E24-T03-83-85.mp3"},{"ns":[86,88],"script":[["","Attention, everyone. I hope you're enjoying the second day of our weekend workshop on leadership skills for entrepreneurs. During yesterday's session, we conducted a discussion about goal setting, and we did that together as a group.","Xin mọi người chú ý. Tôi hy vọng các bạn đang tận hưởng ngày thứ hai của hội thảo cuối tuần về kỹ năng lãnh đạo dành cho doanh nhân. Trong buổi hôm qua, chúng ta đã thảo luận về việc đặt mục tiêu, và chúng ta làm việc đó cùng nhau theo cả nhóm."],["","However, today I'll be matching you with a partner for a one-on-one discussion. So, start thinking about any improvements you'd like to make to your communication skills, because that's what you'll be sharing with each other.","Tuy nhiên, hôm nay tôi sẽ ghép mỗi bạn với một người cùng cặp để thảo luận một kèm một. Vì vậy, hãy bắt đầu nghĩ về những điều bạn muốn cải thiện trong kỹ năng giao tiếp của mình, vì đó là điều các bạn sẽ chia sẻ với nhau."],["","And later this afternoon, we'll enjoy a prepared lunch, which has been generously donated to us by Blue Star Catering Company. We're grateful to them for their support.","Và chiều nay, chúng ta sẽ thưởng thức bữa trưa đã được chuẩn bị sẵn, do Công ty Cung cấp Đồ ăn Blue Star hào phóng tài trợ. Chúng tôi rất biết ơn sự hỗ trợ của họ."]],"qs":[{"n":86,"q":"According to the speaker, what will be different about today's session?","qvi":"Theo người nói, buổi hôm nay sẽ khác ở điểm nào?","opts":["It will take place outside.","It will be recorded.","Participants will work in pairs.","Participants will deliver presentations."],"vi":["Nó sẽ diễn ra ngoài trời.","Nó sẽ được ghi hình.","Người tham gia sẽ làm việc theo cặp.","Người tham gia sẽ thuyết trình."],"ans":"C","xp":"Hôm qua thảo luận cả nhóm, \"However, today I'll be matching you with a partner for a one-on-one discussion.\" → hôm nay làm việc theo cặp.\na partner for a one-on-one discussion = work in pairs → chọn (C)."},{"n":87,"q":"What is the topic of today's session?","qvi":"Chủ đề của buổi hôm nay là gì?","opts":["Improving communication skills","Updating accounting practices","Managing company finances","Recruiting qualified job candidates"],"vi":["Cải thiện kỹ năng giao tiếp","Cập nhật phương pháp kế toán","Quản lý tài chính công ty","Tuyển dụng ứng viên đủ năng lực"],"ans":"A","xp":"Người nói: \"start thinking about any improvements you'd like to make to your communication skills, because that's what you'll be sharing with each other.\" → chủ đề là cải thiện kỹ năng giao tiếp → chọn (A)."},{"n":88,"q":"What does the speaker say about the lunch?","qvi":"Người nói nói gì về bữa trưa?","opts":["It has been donated.","It is vegetarian.","It will arrive late.","It will include a dessert."],"vi":["Nó được tài trợ (tặng).","Nó là đồ chay.","Nó sẽ đến muộn.","Nó sẽ có món tráng miệng."],"ans":"A","xp":"Người nói: \"a prepared lunch, which has been generously donated to us by Blue Star Catering Company.\" → bữa trưa được tặng → chọn (A)."}],"a":"E24-T03-86-88.mp3"},{"ns":[89,91],"script":[["","This is Adisa from Car Pro returning your call. In your message, you said your sedan seems sluggish and isn't accelerating well. There are a number of things that could be causing that, and prices vary with the repair.","Tôi là Adisa từ Car Pro, gọi lại cho anh/chị. Trong tin nhắn, anh/chị nói chiếc xe sedan có vẻ ì và tăng tốc không tốt. Có nhiều nguyên nhân có thể gây ra điều đó, và giá cả thay đổi tùy theo việc sửa chữa."],["","It could be as simple as a clogged oil filter, which is inexpensive to fix. But we'll have to take a look. Oh, by the way, we're closing early tomorrow, but we can get you in the day after. We'll open at eight A.M.","Có thể chỉ đơn giản là lọc dầu bị tắc, sửa không tốn mấy. Nhưng chúng tôi phải xem qua đã. À, nhân tiện, ngày mai chúng tôi đóng cửa sớm, nhưng ngày kia chúng tôi có thể nhận xe của anh/chị. Chúng tôi mở cửa lúc 8 giờ sáng."]],"qs":[{"n":89,"q":"Where does the speaker most likely work?","qvi":"Người nói nhiều khả năng làm việc ở đâu?","opts":["At a car-rental company","At an appliance-repair shop","At a car wash","At an auto-mechanic shop"],"vi":["Ở công ty cho thuê xe","Ở tiệm sửa đồ gia dụng","Ở tiệm rửa xe","Ở xưởng sửa chữa ô tô"],"ans":"D","xp":"Người nói tự giới thiệu \"This is Adisa from Car Pro returning your call\", nói về chiếc sedan tăng tốc kém và \"prices vary with the repair\", lọc dầu bị tắc → anh ấy làm ở xưởng sửa ô tô → chọn (D)."},{"n":90,"q":"What does the speaker imply when he says, \"we'll have to take a look\"?","qvi":"Người nói ngụ ý gì khi nói \"chúng tôi phải xem qua đã\"?","opts":["A schedule may be changed.","A supervisor should be consulted.","A cost cannot be determined yet.","A new policy must be followed."],"vi":["Lịch trình có thể bị thay đổi.","Cần hỏi ý kiến người quản lý.","Chưa thể xác định chi phí.","Phải tuân theo một chính sách mới."],"ans":"C","xp":"Câu hỏi hàm ý. Người nói vừa nói \"prices vary with the repair. It could be as simple as a clogged oil filter, which is inexpensive to fix.\" rồi nói \"But we'll have to take a look.\" → phải kiểm tra xe mới biết lỗi gì, nên chưa thể báo giá → chọn (C)."},{"n":91,"q":"What does the speaker say about tomorrow?","qvi":"Người nói nói gì về ngày mai?","opts":["Some machinery will be serviced.","The business will close early.","Some new employees will start work.","An appointment will probably become available."],"vi":["Một số máy móc sẽ được bảo dưỡng.","Cửa hàng sẽ đóng cửa sớm.","Một số nhân viên mới sẽ bắt đầu làm việc.","Có lẽ sẽ có lịch hẹn trống."],"ans":"B","xp":"Người nói: \"we're closing early tomorrow\" → ngày mai cửa hàng đóng cửa sớm → chọn (B)."}],"a":"E24-T03-89-91.mp3"},{"ns":[92,94],"script":[["","Thanks, everyone, for helping set up the showroom floor with the displays of the new bedroom and living room sets. They look great.","Cảm ơn mọi người đã giúp bày biện phòng trưng bày với các bộ nội thất phòng ngủ và phòng khách mới. Trông chúng rất đẹp."],["","Many of you have asked for time off next Wednesday to attend the town parade. I wasn't sure I could grant those requests, but after thinking about it, I realized that that day will probably not be a profitable day for us anyway. I'll post a new employee schedule!","Nhiều bạn đã xin nghỉ vào thứ Tư tới để đi xem cuộc diễu hành của thị trấn. Tôi đã không chắc mình có thể chấp thuận những yêu cầu đó, nhưng sau khi suy nghĩ, tôi nhận ra dù sao hôm đó có lẽ cũng không phải là ngày bán được nhiều hàng. Tôi sẽ đăng lịch làm việc mới cho nhân viên!"],["","Oh, and one more quick announcement—I need all of you to put in an order for a new uniform. It's time we replaced them.","À, còn một thông báo nhanh nữa – tôi cần tất cả các bạn đặt đồng phục mới. Đã đến lúc chúng ta thay đồng phục rồi."]],"qs":[{"n":92,"q":"What type of business does the speaker most likely work at?","qvi":"Người nói nhiều khả năng làm việc ở loại hình kinh doanh nào?","opts":["A car dealership","An electronics store","A clothing boutique","A furniture store"],"vi":["Đại lý ô tô","Cửa hàng đồ điện tử","Cửa hàng quần áo","Cửa hàng nội thất"],"ans":"D","xp":"Người nói: \"Thanks, everyone, for helping set up the showroom floor with the displays of the new bedroom and living room sets.\" → bộ nội thất phòng ngủ, phòng khách → cửa hàng nội thất → chọn (D)."},{"n":93,"q":"What does the speaker imply when he says, \"that day will probably not be a profitable day for us anyway\"?","qvi":"Người nói ngụ ý gì khi nói \"dù sao hôm đó có lẽ cũng không phải là ngày bán được nhiều hàng\"?","opts":["Reduced profits have prevented salary increases.","A new sales strategy will have to be developed.","The listeners will be able to attend an event.","The listeners have been keeping accurate records."],"vi":["Lợi nhuận giảm đã khiến không thể tăng lương.","Cần xây dựng một chiến lược bán hàng mới.","Người nghe sẽ có thể tham dự một sự kiện.","Người nghe đã ghi chép số liệu chính xác."],"ans":"C","xp":"Câu hỏi hàm ý. Nhân viên xin nghỉ để đi xem diễu hành; người nói \"wasn't sure I could grant those requests\", nhưng rồi nói hôm đó dù sao cũng vắng khách, và \"I'll post a new employee schedule!\" → đồng ý cho nghỉ, nhân viên có thể đi xem diễu hành → chọn (C)."},{"n":94,"q":"What does the speaker expect the listeners to do?","qvi":"Người nói mong người nghe làm gì?","opts":["Submit an order form","Provide some feedback","Sign a contract","Check a display area"],"vi":["Nộp mẫu đơn đặt hàng","Đưa ra ý kiến phản hồi","Ký hợp đồng","Kiểm tra khu trưng bày"],"ans":"A","xp":"Người nói: \"I need all of you to put in an order for a new uniform.\"\nput in an order = submit an order form → chọn (A)."}],"a":"E24-T03-92-94.mp3"},{"ns":[95,97],"script":[["","Hi. This is Emily calling from Speedy Services. I'm picking you up from the central train station today. I see you selected a pickup location near the ticket windows, but there's heavy traffic on that street.","Xin chào. Tôi là Emily gọi từ Speedy Services. Hôm nay tôi sẽ đón anh/chị ở ga tàu trung tâm. Tôi thấy anh/chị đã chọn điểm đón gần quầy bán vé, nhưng con đường đó đang rất đông xe."],["","Would it be possible to change your pickup location to right outside the station's grand concourse? It's the designated area for rideshare services. Please let me know if you agree with this change by responding to the prompt within the app. Thanks!","Liệu có thể đổi điểm đón sang ngay bên ngoài sảnh chính của nhà ga được không? Đó là khu vực dành riêng cho dịch vụ xe đi chung. Vui lòng cho tôi biết anh/chị có đồng ý thay đổi này không bằng cách trả lời thông báo trong ứng dụng. Cảm ơn!"]],"qs":[{"n":95,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["A rideshare driver","A tour guide","A ticket agent","A baggage handler"],"vi":["Tài xế xe công nghệ (xe đi chung)","Hướng dẫn viên du lịch","Nhân viên bán vé","Nhân viên bốc xếp hành lý"],"ans":"A","xp":"Người nói: \"This is Emily calling from Speedy Services. I'm picking you up from the central train station today.\" và nói điểm đón mới \"is the designated area for rideshare services\" → cô ấy là tài xế xe công nghệ → chọn (A)."},{"n":96,"q":"Look at the graphic. Where does the speaker want to meet?","qvi":"Hãy nhìn hình. Người nói muốn gặp ở đâu?","opts":["On Market Street","On Twelfth Street","On Central Avenue","On Tenth Street"],"vi":["Trên phố Market","Trên phố Twelfth","Trên đại lộ Central","Trên phố Tenth"],"ans":"A","xp":"Người nói: \"Would it be possible to change your pickup location to right outside the station's grand concourse?\" Trên bản đồ, lối ra phía Grand Concourse dẫn ra Market Street → chọn (A).\n(D) Tenth Street gần Ticket Windows là điểm đón cũ đang bị kẹt xe."},{"n":97,"q":"How can a change be confirmed?","qvi":"Có thể xác nhận thay đổi bằng cách nào?","opts":["By sending an e-mail","By providing an e-signature","By using an app","By returning a call"],"vi":["Bằng cách gửi e-mail","Bằng cách cung cấp chữ ký điện tử","Bằng cách sử dụng ứng dụng","Bằng cách gọi lại"],"ans":"C","xp":"Người nói: \"Please let me know if you agree with this change by responding to the prompt within the app.\" → trả lời trong ứng dụng → chọn (C)."}],"a":"E24-T03-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Good morning. My presentation will look closely at the nutritional benefits of eating fruit. Patients often wonder whether the amount of sugar in fruit makes fruit unhealthy, and some even consider limiting it in their diet. But it's more nuanced than that.","Chào buổi sáng. Bài trình bày của tôi sẽ xem xét kỹ những lợi ích dinh dưỡng của việc ăn trái cây. Bệnh nhân thường thắc mắc liệu lượng đường trong trái cây có khiến trái cây không tốt cho sức khỏe không, và một số người thậm chí còn tính hạn chế trái cây trong chế độ ăn. Nhưng vấn đề phức tạp hơn thế."],["","Last year, I published a paper reporting on my research on eating the current recommended serving of fruit each day versus eating less of it for weight-loss purposes. I'll spend the next 45 minutes going through the results, and then it'll be time for the coffee break.","Năm ngoái, tôi đã công bố một bài báo về nghiên cứu của mình, so sánh việc ăn đúng khẩu phần trái cây được khuyến nghị mỗi ngày với việc ăn ít hơn nhằm giảm cân. Tôi sẽ dành 45 phút tới để trình bày các kết quả, sau đó sẽ đến giờ giải lao uống cà phê."],["","During the coffee break, feel free to wander to the dining room, where our sponsor has set up a booth to sample a new nutritional beverage.","Trong giờ giải lao, mời các bạn thoải mái ghé qua phòng ăn, nơi nhà tài trợ của chúng ta đã dựng một gian hàng để mời dùng thử một loại thức uống dinh dưỡng mới."]],"qs":[{"n":98,"q":"Look at the graphic. Who is the speaker?","qvi":"Hãy nhìn hình. Người nói là ai?","opts":["Dr. Bajaj","Dr. Novikova","Dr. Ivanda","Dr. Shimizu"],"vi":["Tiến sĩ Bajaj","Tiến sĩ Novikova","Tiến sĩ Ivanda","Tiến sĩ Shimizu"],"ans":"B","xp":"Người nói: \"My presentation will look closely at the nutritional benefits of eating fruit.\" và sau bài nói là \"the coffee break\". Trong lịch, bài về trái cây là \"The Truth About Fruit\" (8:15, ngay trước Coffee break) do Dr. Novikova trình bày → chọn (B)."},{"n":99,"q":"What did the speaker do last year?","qvi":"Năm ngoái người nói đã làm gì?","opts":["She started her own medical practice.","She received an award.","She published a study.","She developed a fitness application."],"vi":["Bà ấy mở phòng khám riêng.","Bà ấy nhận được giải thưởng.","Bà ấy công bố một nghiên cứu.","Bà ấy phát triển một ứng dụng thể dục."],"ans":"C","xp":"Người nói: \"Last year, I published a paper reporting on my research...\"\na paper reporting on my research = a study → chọn (C)."},{"n":100,"q":"According to the speaker, where can the listeners test a product?","qvi":"Theo người nói, người nghe có thể dùng thử sản phẩm ở đâu?","opts":["In a lobby","In an auditorium","In a gift shop","In a dining area"],"vi":["Ở sảnh","Ở hội trường","Ở cửa hàng quà tặng","Ở khu vực ăn uống"],"ans":"D","xp":"Người nói: \"feel free to wander to the dining room, where our sponsor has set up a booth to sample a new nutritional beverage.\"\nthe dining room = a dining area; sample = test → chọn (D)."}],"a":"E24-T03-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"------- your order is being processed, please call customer service with any questions.","opts":["Still","Either","While","Also"],"ans":"C","xp":"Liên từ. Chỗ trống đứng đầu một mệnh đề đầy đủ (your order is being processed) nối với mệnh đề chính (please call...) → cần liên từ phụ thuộc. (C) While 'trong khi' là liên từ → chọn (C). (A) Still 'vẫn' và (D) Also 'cũng' là trạng từ, không nối được hai mệnh đề; (B) Either đi với cấu trúc either ... or.\nDịch: Trong khi đơn hàng của bạn đang được xử lý, vui lòng gọi bộ phận chăm sóc khách hàng nếu có bất kỳ câu hỏi nào."},{"n":102,"q":"ABC Truck Supplies has the ------- selection of mufflers in the state.","opts":["natural","widest","overall","positive"],"ans":"B","xp":"Từ vựng + so sánh nhất. Có 'the' và cụm 'in the state' (trong cả bang) → dấu hiệu so sánh nhất. (B) widest 'rộng nhất' → 'the widest selection' = lựa chọn phong phú nhất → chọn (B). (A) natural 'tự nhiên', (C) overall 'tổng thể', (D) positive 'tích cực' đều không hợp nghĩa và không phải so sánh nhất.\nDịch: ABC Truck Supplies có nhiều lựa chọn ống giảm thanh nhất trong bang."},{"n":103,"q":"Sharswood Landscaping has received dozens of five-star ------- for its work.","opts":["reviews","reviewer","reviewed","reviewing"],"ans":"A","xp":"Từ loại. Sau 'dozens of five-star' (hàng chục ... năm sao) cần danh từ số nhiều. (A) reviews 'bài đánh giá' → chọn (A). (B) reviewer là danh từ chỉ người, số ít, không hợp nghĩa; (C) reviewed và (D) reviewing là dạng động từ.\nDịch: Công ty cảnh quan Sharswood đã nhận được hàng chục đánh giá năm sao cho công việc của mình."},{"n":104,"q":"Dr. Cho will visit the Teledarr Lab during the annual open house, since ------- may not have another chance to see it.","opts":["hers","she","her","herself"],"ans":"B","xp":"Đại từ. Sau liên từ 'since' là mệnh đề, chỗ trống đứng trước động từ 'may not have' → cần đại từ làm chủ ngữ. (B) she → chọn (B). (A) hers là đại từ sở hữu, (C) her là tân ngữ/tính từ sở hữu, (D) herself là đại từ phản thân — không làm chủ ngữ được.\nDịch: Tiến sĩ Cho sẽ đến thăm Phòng thí nghiệm Teledarr trong ngày hội mở cửa thường niên, vì bà ấy có thể sẽ không có cơ hội khác để xem nó."},{"n":105,"q":"Dorn Department Store decided to ------- its already large selection of housewares.","opts":["create","enforce","apply","expand"],"ans":"D","xp":"Từ vựng. Tân ngữ là 'its already large selection' (bộ sưu tập vốn đã lớn) → hợp nghĩa nhất là 'mở rộng'. (D) expand 'mở rộng' → chọn (D). (A) create 'tạo ra' (đã có sẵn rồi nên không hợp), (B) enforce 'thi hành, bắt buộc', (C) apply 'áp dụng, nộp đơn'.\nDịch: Cửa hàng bách hóa Dorn đã quyết định mở rộng danh mục đồ gia dụng vốn đã rất phong phú của mình."},{"n":106,"q":"We ------- that you bring a portfolio of work samples to the interview.","opts":["was asking","having asked","ask","asks"],"ans":"C","xp":"Hòa hợp chủ ngữ – động từ. Chủ ngữ 'We' (số nhiều) cần động từ chia phù hợp. (C) ask → chọn (C). (A) was asking dùng cho chủ ngữ số ít (we phải đi với were); (B) having asked không phải động từ chính; (D) asks dùng cho ngôi thứ ba số ít.\nDịch: Chúng tôi đề nghị bạn mang theo hồ sơ các mẫu công việc đến buổi phỏng vấn."},{"n":107,"q":"Members of the Bold Stone Farm Store receive ------- discounts on all purchases.","opts":["depth","deepen","deep","deeply"],"ans":"C","xp":"Từ loại. Trước danh từ 'discounts' cần tính từ. (C) deep 'sâu' → 'deep discounts' = giảm giá sâu, giảm giá mạnh → chọn (C). (A) depth là danh từ, (B) deepen là động từ, (D) deeply là trạng từ.\nDịch: Thành viên của Cửa hàng Nông trại Bold Stone được giảm giá mạnh cho mọi đơn hàng."},{"n":108,"q":"If your plans change, please contact us at least 24 hours before the time of your -------.","opts":["reserved","reservation","reservable","reserve"],"ans":"B","xp":"Từ loại. Sau tính từ sở hữu 'your' cần danh từ. (B) reservation 'sự đặt chỗ' → chọn (B). (A) reserved là quá khứ phân từ/tính từ, (C) reservable là tính từ, (D) reserve chủ yếu là động từ (danh từ 'reserve' nghĩa là 'khoản dự trữ', không hợp nghĩa).\nDịch: Nếu kế hoạch của bạn thay đổi, vui lòng liên hệ với chúng tôi ít nhất 24 giờ trước thời gian đặt chỗ của bạn."},{"n":109,"q":"Hold the tomato seedling gently by the stem in order to avoid harming ------- roots.","opts":["its","at","that","in"],"ans":"A","xp":"Đại từ/tính từ sở hữu. Trước danh từ 'roots' cần một từ hạn định; 'roots' là rễ của cây giống (the tomato seedling) → dùng tính từ sở hữu 'its'. (A) its → chọn (A). (B) at, (D) in là giới từ; (C) that đi với danh từ số ít, không hợp với 'roots'.\nDịch: Hãy cầm nhẹ cây giống cà chua ở phần thân để tránh làm tổn thương rễ của nó."},{"n":110,"q":"At the registration table, be sure to collect your name tag ------- entering the conference.","opts":["very","often","always","before"],"ans":"D","xp":"Giới từ/liên từ. Sau chỗ trống là V-ing 'entering' → cần giới từ (hoặc liên từ rút gọn). (D) before 'trước khi' → 'before entering' = trước khi vào → chọn (D). (A) very, (B) often, (C) always là trạng từ, không đứng trước V-ing để nối như vậy.\nDịch: Tại bàn đăng ký, hãy nhớ nhận bảng tên của bạn trước khi vào hội nghị."},{"n":111,"q":"Maihama vehicles include an extended ------- to cover engine repairs.","opts":["record","operation","budget","warranty"],"ans":"D","xp":"Từ vựng. 'an extended ... to cover engine repairs' (... mở rộng để chi trả việc sửa động cơ) → 'extended warranty' = bảo hành mở rộng. (D) warranty 'bảo hành' → chọn (D). (A) record 'hồ sơ, kỷ lục', (B) operation 'hoạt động, vận hành', (C) budget 'ngân sách'.\nDịch: Xe Maihama đi kèm gói bảo hành mở rộng để chi trả cho việc sửa chữa động cơ."},{"n":112,"q":"The hotel's new Web site features an ------- collection of high-quality images.","opts":["absolute","efficient","impressive","undefeated"],"ans":"C","xp":"Từ vựng. Bổ nghĩa cho 'collection of high-quality images' (bộ sưu tập hình ảnh chất lượng cao) → (C) impressive 'ấn tượng' → chọn (C). (A) absolute 'tuyệt đối', (B) efficient 'hiệu quả (tiết kiệm)', (D) undefeated 'bất bại' đều không hợp nghĩa.\nDịch: Trang web mới của khách sạn có một bộ sưu tập hình ảnh chất lượng cao rất ấn tượng."},{"n":113,"q":"On behalf of everyone at Uniontown Bank, we ------- thank you for your continued patronage.","opts":["deservedly","commonly","sincerely","perfectly"],"ans":"C","xp":"Từ vựng (trạng từ). Cụm cố định 'sincerely thank you' = chân thành cảm ơn. (C) sincerely 'chân thành' → chọn (C). (A) deservedly 'xứng đáng', (B) commonly 'thông thường', (D) perfectly 'hoàn hảo' không đi với 'thank'.\nDịch: Thay mặt toàn thể Ngân hàng Uniontown, chúng tôi chân thành cảm ơn quý khách đã tiếp tục ủng hộ."},{"n":114,"q":"Fragile equipment must be stored in a secure location so that nothing is ------- damaged.","opts":["accident","accidents","accidental","accidentally"],"ans":"D","xp":"Từ loại. 'is ... damaged' là bị động (be + V3); chỗ trống chen giữa 'is' và 'damaged' → cần trạng từ bổ nghĩa cho động từ. (D) accidentally 'vô tình' → chọn (D). (A)(B) là danh từ, (C) là tính từ.\nDịch: Thiết bị dễ vỡ phải được cất ở nơi an toàn để không có thứ gì vô tình bị hư hỏng."},{"n":115,"q":"Ms. Sampson will not arrive at the convention ------- after our team's presentation.","opts":["until","lately","from","when"],"ans":"A","xp":"Giới từ – cấu trúc. 'not ... until' = mãi đến ... mới. 'will not arrive ... until after our team's presentation' = mãi đến sau bài thuyết trình mới đến. (A) until → chọn (A). (B) lately 'gần đây' là trạng từ, (C) from 'từ', (D) when 'khi' (cần mệnh đề phía sau) đều không hợp.\nDịch: Mãi đến sau bài thuyết trình của nhóm chúng ta thì cô Sampson mới đến hội nghị."},{"n":116,"q":"The community picnic will be held ------- the park behind the Seltzer Public Library.","opts":["in","all","for","here"],"ans":"A","xp":"Giới từ chỉ nơi chốn. 'be held in the park' = được tổ chức trong công viên. (A) in → chọn (A). (B) all 'tất cả', (C) for 'cho/dành cho', (D) here 'ở đây' (trạng từ, không đứng trước danh từ).\nDịch: Buổi dã ngoại cộng đồng sẽ được tổ chức tại công viên phía sau Thư viện Công cộng Seltzer."},{"n":117,"q":"The new hires ------- for an orientation on May 10 at 9:00 A.M.","opts":["to be gathering","will gather","gathering","to gather"],"ans":"B","xp":"Động từ chính / thì. Câu chưa có động từ chính, mốc thời gian 'on May 10 at 9:00 A.M.' chỉ sự kiện sắp tới → thì tương lai. (B) will gather → chọn (B). (A)(D) là to-V, (C) là V-ing — không làm động từ chính được.\nDịch: Các nhân viên mới sẽ tập trung để tham gia buổi định hướng vào lúc 9 giờ sáng ngày 10 tháng 5."},{"n":118,"q":"When Mr. Young approached the desk, the receptionist ------- offered him a seat in the waiting room.","opts":["politely","polite","politeness","politest"],"ans":"A","xp":"Từ loại. Chỗ trống nằm giữa chủ ngữ 'the receptionist' và động từ 'offered' → cần trạng từ. (A) politely 'một cách lịch sự' → chọn (A). (B) polite, (D) politest là tính từ; (C) politeness là danh từ.\nDịch: Khi ông Young đến gần quầy, nhân viên lễ tân đã lịch sự mời ông ngồi ở phòng chờ."},{"n":119,"q":"Members of the Marvale marketing team claimed that ------- was the best design for the new corporate logo.","opts":["they","them","theirs","their"],"ans":"C","xp":"Đại từ. Chỗ trống làm chủ ngữ của 'was' (số ít) trong mệnh đề 'that ...'. 'theirs' = 'their design' (thiết kế của họ), đi với 'was' → (C) theirs → chọn (C). (A) they đi với 'were' và nghĩa không hợp; (B) them là tân ngữ; (D) their phải có danh từ theo sau.\nDịch: Các thành viên nhóm tiếp thị Marvale khẳng định rằng thiết kế của họ là thiết kế tốt nhất cho logo mới của công ty."},{"n":120,"q":"The new Kitsuna video camera is currently on sale for $375, not ------- tax.","opts":["excepting","alongside","within","including"],"ans":"D","xp":"Giới từ/từ vựng. 'not including tax' = chưa bao gồm thuế (cụm rất hay gặp khi nói giá). (D) including 'bao gồm' → chọn (D). (A) excepting 'ngoại trừ', (B) alongside 'bên cạnh', (C) within 'trong vòng' không hợp nghĩa.\nDịch: Máy quay Kitsuna mới hiện đang được bán với giá 375 đô la, chưa bao gồm thuế."},{"n":121,"q":"All associates are ------- to follow the standard operating procedures outlined in the handbook.","opts":["concerned","tended","maintained","expected"],"ans":"D","xp":"Từ vựng – cấu trúc. 'be expected to V' = được yêu cầu/kỳ vọng phải làm gì. (D) expected → chọn (D). (A) be concerned about/with 'lo lắng/liên quan', (B) tend to V dùng chủ động 'có xu hướng', không dùng bị động 'are tended to'; (C) maintained 'được duy trì' không hợp nghĩa.\nDịch: Tất cả nhân viên đều phải tuân theo các quy trình vận hành tiêu chuẩn được nêu trong sổ tay."},{"n":122,"q":"This month Framley Publishing House is embarking on its ------- expansion so far.","opts":["ambitiously","most ambitiously","ambition","most ambitious"],"ans":"D","xp":"Từ loại + so sánh nhất. Sau 'its' và trước danh từ 'expansion' cần tính từ; 'so far' (tính đến nay) là dấu hiệu so sánh nhất. (D) most ambitious 'tham vọng nhất' → chọn (D). (A)(B) là trạng từ, (C) ambition là danh từ.\nDịch: Tháng này, Nhà xuất bản Framley đang bắt tay vào đợt mở rộng tham vọng nhất từ trước đến nay của mình."},{"n":123,"q":"After months of collaboration, Matricks Technology's software developers ------- released a top-quality product.","opts":["profoundly","overly","finally","intensely"],"ans":"C","xp":"Từ vựng (trạng từ). 'After months of collaboration' (sau nhiều tháng hợp tác) → cuối cùng cũng ra mắt sản phẩm. (C) finally 'cuối cùng' → chọn (C). (A) profoundly 'sâu sắc', (B) overly 'quá mức', (D) intensely 'mãnh liệt' không hợp với 'released'.\nDịch: Sau nhiều tháng hợp tác, các nhà phát triển phần mềm của Matricks Technology cuối cùng đã cho ra mắt một sản phẩm chất lượng hàng đầu."},{"n":124,"q":"Tickets are valid for one-time access and do not allow for ------- into the venue.","opts":["duplication","reentry","permission","turnover"],"ans":"B","xp":"Từ vựng. Vé chỉ dùng cho 'one-time access' (vào một lần) → không cho phép 'vào lại'. (B) reentry 'sự vào lại' → chọn (B); 'into the venue' cũng đi với ý 'vào'. (A) duplication 'sự sao chép', (C) permission 'sự cho phép', (D) turnover 'doanh thu, tỷ lệ nghỉ việc'.\nDịch: Vé có giá trị cho một lần vào cửa và không cho phép vào lại địa điểm."},{"n":125,"q":"We hired Okafor Construction to do the renovation ------- it was not the lowest bidder on the project.","opts":["if only","alternatively","whereas","even though"],"ans":"D","xp":"Liên từ. Hai vế trái ngược: thuê Okafor dù họ không phải bên bỏ thầu thấp nhất → cần liên từ nhượng bộ. (D) even though 'mặc dù' → chọn (D). (A) if only 'giá mà', (C) whereas 'trong khi (đối lập hai đối tượng)' không hợp; (B) alternatively 'hoặc là, thay vào đó' là trạng từ.\nDịch: Chúng tôi đã thuê Công ty Xây dựng Okafor thực hiện việc cải tạo mặc dù họ không phải là bên bỏ thầu thấp nhất cho dự án."},{"n":126,"q":"The first ------- of the training will introduce staff to certain workplace responsibilities.","opts":["part","parted","parting","partial"],"ans":"A","xp":"Từ loại. Sau 'The first' cần danh từ làm chủ ngữ. (A) part 'phần' → chọn (A). (B) parted là V-ed, (C) parting là V-ing ('sự chia tay' không hợp nghĩa), (D) partial là tính từ.\nDịch: Phần đầu tiên của khóa đào tạo sẽ giới thiệu cho nhân viên một số trách nhiệm tại nơi làm việc."},{"n":127,"q":"According to industry -------, Ghira Company plans to relocate its headquarters to Australia.","opts":["reported","reportedly","reporter","reports"],"ans":"D","xp":"Từ loại. Sau 'According to' cần danh từ; 'industry' đóng vai trò bổ nghĩa → 'industry reports' = các báo cáo trong ngành. (D) reports → chọn (D). (C) reporter là danh từ đếm được số ít, phải có mạo từ và nghĩa 'phóng viên' không hợp; (A) reported là động từ, (B) reportedly là trạng từ.\nDịch: Theo các báo cáo trong ngành, Công ty Ghira dự định chuyển trụ sở chính sang Úc."},{"n":128,"q":"Next month, the Kneath House will host an exhibition of ------- furniture and clothing from the eighteenth century.","opts":["authentic","authentically","authenticate","authenticity"],"ans":"A","xp":"Từ loại. Trước danh từ 'furniture and clothing' cần tính từ. (A) authentic 'đích thực, nguyên bản' → chọn (A). (B) là trạng từ, (C) là động từ, (D) là danh từ.\nDịch: Tháng tới, Kneath House sẽ tổ chức một cuộc triển lãm đồ nội thất và quần áo nguyên bản từ thế kỷ mười tám."},{"n":129,"q":"PKTM's regional managers serve ------- the direction of the vice president.","opts":["among","under","behind","opposite"],"ans":"B","xp":"Giới từ. 'under the direction of' = dưới sự chỉ đạo của. (B) under → chọn (B). (A) among 'giữa (nhiều người)', (C) behind 'phía sau', (D) opposite 'đối diện' không hợp.\nDịch: Các quản lý khu vực của PKTM làm việc dưới sự chỉ đạo của phó chủ tịch."},{"n":130,"q":"------- a recent surge in demand, Vanita's Catering is hiring four additional servers.","opts":["Everywhere","Possibly","In total","Owing to"],"ans":"D","xp":"Giới từ chỉ nguyên nhân. Sau chỗ trống là cụm danh từ 'a recent surge in demand' (nhu cầu tăng vọt gần đây), là lý do cho việc tuyển thêm người → cần giới từ 'do, vì'. (D) Owing to → chọn (D). (A) Everywhere 'khắp nơi', (B) Possibly 'có lẽ', (C) In total 'tổng cộng' không chỉ nguyên nhân.\nDịch: Do nhu cầu tăng mạnh gần đây, Dịch vụ ăn uống Vanita's đang tuyển thêm bốn nhân viên phục vụ."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> All Staff</p><p><b>From:</b> Yoreli Costa</p><p><b>Date:</b> February 15</p><p><b>Subject:</b> Florence Shawn</p></div><p>Hi Everyone,</p><p>I have news to share about a <span class=\"blank\" data-n=\"131\">-------</span> in the human resources department. After nearly twenty years with Cometti Creative, Florence Shawn has decided to retire from the position of director of human resources.</p><p>Our current senior manager of human resources, Makoto Ichise, will replace Ms. Shawn when she retires. Ms. Shawn <span class=\"blank\" data-n=\"132\">-------</span> Mr. Ichise since he joined the company five years ago.</p><p>Ms. Shawn's <span class=\"blank\" data-n=\"133\">-------</span> day will be February 22. A retirement party will be held for her on that day at 4:00 P.M. in the Terey Lobby. <span class=\"blank\" data-n=\"134\">-------</span>.</p><p>Best,</p><p>Yoreli Costa<br>Director of Operations, Cometti Creative</p>","vi":"Người nhận: Toàn thể nhân viên\nNgười gửi: Yoreli Costa\nNgày: 15 tháng 2\nTiêu đề: Florence Shawn\n\nChào mọi người,\n\nTôi có tin muốn chia sẻ về một sự thay đổi ở phòng nhân sự. Sau gần hai mươi năm gắn bó với Cometti Creative, bà Florence Shawn đã quyết định nghỉ hưu khỏi vị trí giám đốc nhân sự.\n\nTrưởng phòng nhân sự cấp cao hiện tại của chúng ta, ông Makoto Ichise, sẽ thay thế bà Shawn khi bà nghỉ hưu. Bà Shawn đã hướng dẫn, kèm cặp ông Ichise kể từ khi ông gia nhập công ty năm năm trước.\n\nNgày làm việc cuối cùng của bà Shawn sẽ là ngày 22 tháng 2. Một bữa tiệc chia tay nghỉ hưu sẽ được tổ chức cho bà vào lúc 4 giờ chiều ngày hôm đó tại Sảnh Terey. Chúng tôi hy vọng tất cả mọi người có thể đến tham dự để chúc bà mọi điều tốt đẹp.\n\nTrân trọng,\n\nYoreli Costa\nGiám đốc Vận hành, Cometti Creative","qs":[{"n":131,"opts":["difference","strategy","change","practice"],"ans":"C","xp":"Từ vựng. Câu sau cho biết giám đốc nhân sự nghỉ hưu và có người thay thế → đây là một 'sự thay đổi' về nhân sự. (C) change 'sự thay đổi' → chọn (C). (A) difference 'sự khác biệt', (B) strategy 'chiến lược', (D) practice 'thông lệ, sự luyện tập' không hợp.\nDịch: Tôi có tin muốn chia sẻ về một sự thay đổi ở phòng nhân sự."},{"n":132,"opts":["mentors","is mentoring","will mentor","has been mentoring"],"ans":"D","xp":"Thì động từ. Có 'since he joined the company five years ago' (kể từ khi ông ấy vào công ty 5 năm trước) → hành động bắt đầu trong quá khứ và kéo dài đến hiện tại → thì hiện tại hoàn thành (tiếp diễn). (D) has been mentoring → chọn (D). (A) hiện tại đơn, (B) hiện tại tiếp diễn, (C) tương lai đơn không đi với 'since'.\nDịch: Bà Shawn đã kèm cặp ông Ichise kể từ khi ông gia nhập công ty năm năm trước."},{"n":133,"opts":["last","original","flexible","alternate"],"ans":"A","xp":"Từ vựng. Bà Shawn sắp nghỉ hưu, và tiệc chia tay được tổ chức 'on that day' → ngày đó là 'ngày làm việc cuối cùng'. (A) last 'cuối cùng' → chọn (A). (B) original 'ban đầu', (C) flexible 'linh hoạt', (D) alternate 'thay thế, xen kẽ' không hợp.\nDịch: Ngày làm việc cuối cùng của bà Shawn sẽ là ngày 22 tháng 2."},{"n":134,"opts":["Cometti Creative will hire a replacement soon.","We hope that you can all attend to wish her well.","Ms. Shawn was the first director of human resources at Cometti Creative.","The first project will be the creation of a talent development program."],"ans":"B","xp":"Điền câu. Câu trước nói về bữa tiệc nghỉ hưu (thời gian, địa điểm) → câu tiếp theo hợp lý là lời mời mọi người đến dự để chúc bà Shawn. (B) → chọn (B). (A) sai vì đã có người thay thế (Makoto Ichise); (C) thông tin 'giám đốc nhân sự đầu tiên' không có căn cứ và lạc ý; (D) 'dự án đầu tiên' không liên quan đến bữa tiệc.\n(A) Cometti Creative sẽ sớm tuyển người thay thế.\n(B) Chúng tôi hy vọng tất cả mọi người có thể tham dự để chúc bà mọi điều tốt đẹp.\n(C) Bà Shawn là giám đốc nhân sự đầu tiên của Cometti Creative.\n(D) Dự án đầu tiên sẽ là xây dựng một chương trình phát triển nhân tài."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following advertisement.","passage":"<h3>Lovitt Real Estate</h3><h4>Helping Manitoba Families Find their Dream Homes</h4><p>Manuel Lovitt, <span class=\"blank\" data-n=\"135\">-------</span> of Lovitt Real Estate, has been selling real estate for over 17 years. Mr. Lovitt and his award-winning team <span class=\"blank\" data-n=\"136\">-------</span> in homes for families in the Winnipeg, Brandon, and Dauphin areas. They know about the schools, parks, services, transportation, and activities that enhance family life in the area where you want to reside. <span class=\"blank\" data-n=\"137\">-------</span>.</p><p>Contact Lovitt Real Estate today and let the team guide you <span class=\"blank\" data-n=\"138\">-------</span> the home of your dreams. They will listen to your needs, negotiate on your behalf, and get you the best home for your hard-earned money.</p><p>Call 431-555-0168 to speak to an agent or visit www.lovittrealestate.ca for more information.</p>","vi":"Lovitt Real Estate\n\nGiúp các gia đình ở Manitoba tìm được ngôi nhà mơ ước\n\nÔng Manuel Lovitt, chủ sở hữu của Lovitt Real Estate, đã bán bất động sản hơn 17 năm. Ông Lovitt và đội ngũ từng đoạt giải thưởng của mình chuyên về nhà ở cho các gia đình tại khu vực Winnipeg, Brandon và Dauphin. Họ am hiểu về trường học, công viên, dịch vụ, giao thông và các hoạt động giúp nâng cao chất lượng cuộc sống gia đình ở khu vực mà bạn muốn sinh sống. Đó là vì họ sống ngay tại những cộng đồng mà họ phục vụ.\n\nHãy liên hệ Lovitt Real Estate ngay hôm nay và để đội ngũ dẫn dắt bạn đến với ngôi nhà mơ ước. Họ sẽ lắng nghe nhu cầu của bạn, thay mặt bạn đàm phán và mang đến cho bạn ngôi nhà tốt nhất xứng đáng với số tiền bạn vất vả kiếm được.\n\nGọi 431-555-0168 để nói chuyện với nhân viên môi giới hoặc truy cập www.lovittrealestate.ca để biết thêm thông tin.","qs":[{"n":135,"opts":["own","owned","owner","owning"],"ans":"C","xp":"Từ loại. Cụm 'Manuel Lovitt, ------- of Lovitt Real Estate,' là cụm đồng vị giải thích ông Lovitt là ai → cần danh từ chỉ người. (C) owner 'chủ sở hữu' → chọn (C). (A) own là động từ/tính từ, (B) owned là V-ed, (D) owning là V-ing.\nDịch: Ông Manuel Lovitt, chủ sở hữu của Lovitt Real Estate, đã bán bất động sản hơn 17 năm."},{"n":136,"opts":["practice","specialize","report","purchase"],"ans":"B","xp":"Từ vựng – cụm động từ. Sau chỗ trống là giới từ 'in' → 'specialize in' = chuyên về. (B) specialize → chọn (B). (A) practice 'thực hành' thường không đi với 'in homes'; (C) report 'báo cáo' (đi với on/to); (D) purchase 'mua' là ngoại động từ, không cần 'in', và công ty môi giới thì bán chứ không mua nhà.\nDịch: Ông Lovitt và đội ngũ từng đoạt giải của mình chuyên về nhà ở cho các gia đình tại khu vực Winnipeg, Brandon và Dauphin."},{"n":137,"opts":["They can arrange transportation for your local elementary school.","That is because they live in the communities they serve.","They will be closed for the summer but will be back soon.","Therefore, they can help you with all your banking needs."],"ans":"B","xp":"Điền câu. Câu trước: 'They know about the schools, parks, services, transportation, and activities ... in the area' (họ am hiểu trường học, công viên... trong khu vực) → câu sau giải thích lý do: vì họ sống ngay trong cộng đồng đó. 'That is because' nối trực tiếp với ý 'họ biết rõ'. (B) → chọn (B). (A) sắp xếp đưa đón học sinh không phải việc của công ty bất động sản; (C) đóng cửa mùa hè mâu thuẫn với 'Contact ... today'; (D) dịch vụ ngân hàng không liên quan.\n(A) Họ có thể sắp xếp phương tiện đưa đón cho trường tiểu học địa phương của bạn.\n(B) Đó là vì họ sống ngay tại những cộng đồng mà họ phục vụ.\n(C) Họ sẽ đóng cửa vào mùa hè nhưng sẽ sớm trở lại.\n(D) Vì vậy, họ có thể giúp bạn mọi nhu cầu về ngân hàng."},{"n":138,"opts":["toward","fixing","because","along"],"ans":"A","xp":"Giới từ. 'guide you toward the home of your dreams' = dẫn dắt bạn hướng tới ngôi nhà mơ ước. (A) toward 'về phía, hướng tới' → chọn (A). (B) fixing 'sửa chữa' không hợp nghĩa; (C) because là liên từ, cần mệnh đề phía sau; (D) along 'dọc theo' không hợp nghĩa (guide you along + con đường).\nDịch: Hãy liên hệ Lovitt Real Estate ngay hôm nay và để đội ngũ dẫn dắt bạn đến với ngôi nhà mơ ước."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following introduction.","passage":"<p>Welcome to \"Distributing Your Savings.\" This slide <span class=\"blank\" data-n=\"139\">-------</span> is the third of a twelve-segment educational series called \"Preparing for Retirement.\" <span class=\"blank\" data-n=\"140\">-------</span>.</p><p>This series provides only <span class=\"blank\" data-n=\"141\">-------</span> advice. It should not replace the guidance of your investment planner. The series has been developed as background material to help you ask key questions when <span class=\"blank\" data-n=\"142\">-------</span> with your investment planner. We hope you find this information helpful.</p><p>Swainson-Gray Investments</p>","vi":"Chào mừng bạn đến với \"Phân bổ khoản tiết kiệm của bạn\". Bài thuyết trình trình chiếu này là phần thứ ba trong loạt bài giáo dục gồm mười hai phần mang tên \"Chuẩn bị cho việc nghỉ hưu\". Loạt bài được thiết kế để giúp bạn đưa ra các quyết định tài chính sáng suốt.\n\nLoạt bài này chỉ cung cấp lời khuyên mang tính bổ sung. Nó không nên thay thế sự hướng dẫn của chuyên viên hoạch định đầu tư của bạn. Loạt bài được xây dựng như tài liệu nền tảng để giúp bạn đặt ra những câu hỏi quan trọng khi tham khảo ý kiến chuyên viên hoạch định đầu tư. Chúng tôi hy vọng bạn thấy những thông tin này hữu ích.\n\nSwainson-Gray Investments","qs":[{"n":139,"opts":["presenting","presents","presentation","presented"],"ans":"C","xp":"Từ loại – danh từ ghép. 'This slide ------- is the third...': động từ chính là 'is', nên chỗ trống phải hoàn thành chủ ngữ → danh từ ghép 'slide presentation' (bài thuyết trình bằng slide). (C) presentation → chọn (C). (B) presents là động từ, sẽ thành hai động từ chính; (A) presenting và (D) presented không tạo chủ ngữ hợp nghĩa.\nDịch: Bài thuyết trình slide này là phần thứ ba trong loạt bài giáo dục gồm mười hai phần mang tên 'Chuẩn bị cho việc nghỉ hưu'."},{"n":140,"opts":["You are encouraged to visit our office for a free portfolio review.","The series is designed to help you make informed financial decisions.","Please fill out the paperwork before your appointment.","Your responses will help us serve you better in the future."],"ans":"B","xp":"Điền câu. Câu trước giới thiệu loạt bài giáo dục 'Preparing for Retirement' → câu tiếp theo nói về mục đích của loạt bài là hợp lý. (B) 'The series is designed to help you...' nhắc lại 'series' → chọn (B). (A) mời đến văn phòng không liên quan đến phần giới thiệu; (C) 'giấy tờ trước cuộc hẹn' không có cuộc hẹn nào được nhắc; (D) 'câu trả lời của bạn' — đây không phải bảng khảo sát.\n(A) Chúng tôi khuyến khích bạn đến văn phòng để được đánh giá danh mục đầu tư miễn phí.\n(B) Loạt bài được thiết kế để giúp bạn đưa ra các quyết định tài chính sáng suốt.\n(C) Vui lòng điền giấy tờ trước cuộc hẹn của bạn.\n(D) Câu trả lời của bạn sẽ giúp chúng tôi phục vụ bạn tốt hơn trong tương lai."},{"n":141,"opts":["regional","expensive","supplemental","playful"],"ans":"C","xp":"Từ vựng. Câu sau: 'It should not replace the guidance of your investment planner' (không nên thay thế hướng dẫn của chuyên viên) → lời khuyên này chỉ mang tính 'bổ sung'. (C) supplemental 'bổ sung' → chọn (C). (A) regional 'thuộc khu vực', (B) expensive 'đắt', (D) playful 'vui đùa' không hợp.\nDịch: Loạt bài này chỉ cung cấp lời khuyên mang tính bổ sung."},{"n":142,"opts":["consulting","prescribing","listing","following"],"ans":"A","xp":"Từ vựng. 'consult with somebody' = tham khảo ý kiến, hỏi ý kiến ai. 'when consulting with your investment planner' = khi hỏi ý kiến chuyên viên hoạch định đầu tư. (A) consulting → chọn (A). (B) prescribing 'kê đơn', (C) listing 'liệt kê', (D) following 'theo sau' không đi với 'with' theo nghĩa này.\nDịch: Loạt bài được xây dựng như tài liệu nền tảng để giúp bạn đặt ra những câu hỏi quan trọng khi tham khảo ý kiến chuyên viên hoạch định đầu tư."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Dana Paulwell</p><p><b>From:</b> Silas Laveau</p><p><b>Date:</b> August 22</p><p><b>Subject:</b> My input</p><p><b>Attachment:</b> Article</p></div><p>Dear Dr. Paulwell,</p><p>This message is in response to yesterday's staff meeting, particularly the discussion on how certain aspects of the clinic may affect our work and mission. <span class=\"blank\" data-n=\"143\">-------</span>.</p><p>Currently, the vending machines in the hall outside our waiting room are stocked with sugary and salty products such as soft drinks and chips. As a health care provider, we <span class=\"blank\" data-n=\"144\">-------</span> beverages and snacks that show our commitment to wellness. <span class=\"blank\" data-n=\"145\">-------</span>, our mission is focused on good health.</p><p>I have attached an article about actions that medical centers like ours are taking to improve their hospitality stations. I hope you find it <span class=\"blank\" data-n=\"146\">-------</span>. It details some easy and cost-effective changes we could consider.</p><p>Kind regards,</p><p>Silas Laveau</p>","vi":"Người nhận: Dana Paulwell\nNgười gửi: Silas Laveau\nNgày: 22 tháng 8\nTiêu đề: Ý kiến của tôi\nĐính kèm: Bài báo\n\nKính gửi Bác sĩ Paulwell,\n\nThư này là để phản hồi cuộc họp nhân viên hôm qua, đặc biệt là phần thảo luận về việc một số khía cạnh của phòng khám có thể ảnh hưởng đến công việc và sứ mệnh của chúng ta như thế nào. Tôi muốn đưa ra một đề xuất về chủ đề này.\n\nHiện tại, các máy bán hàng tự động ở hành lang bên ngoài phòng chờ của chúng ta chứa đầy các sản phẩm nhiều đường và nhiều muối như nước ngọt có ga và khoai tây chiên. Là một đơn vị chăm sóc sức khỏe, chúng ta nên cung cấp đồ uống và đồ ăn vặt thể hiện cam kết của mình đối với sức khỏe. Xét cho cùng, sứ mệnh của chúng ta tập trung vào sức khỏe tốt.\n\nTôi đã đính kèm một bài báo về những hành động mà các trung tâm y tế như chúng ta đang thực hiện để cải thiện các khu vực phục vụ khách. Tôi hy vọng bác sĩ thấy nó hữu ích. Bài báo trình bày chi tiết một số thay đổi dễ thực hiện và tiết kiệm chi phí mà chúng ta có thể cân nhắc.\n\nTrân trọng,\n\nSilas Laveau","qs":[{"n":143,"opts":["I thought it went on longer than was necessary.","I wish we had been informed about it sooner.","I would like to make a suggestion on this topic.","I would be honored to lead a follow-up session."],"ans":"C","xp":"Điền câu. Câu trước nhắc đến cuộc thảo luận về các khía cạnh của phòng khám; đoạn sau người viết nêu vấn đề máy bán hàng tự động và đề xuất thay đổi (kèm tiêu đề 'My input' = ý kiến của tôi) → câu cần điền giới thiệu một đề xuất. (C) → chọn (C). (A) phàn nàn cuộc họp quá dài, (B) ước được thông báo sớm hơn, (D) xin dẫn dắt buổi họp tiếp theo — đều không dẫn vào nội dung đề xuất phía sau.\n(A) Tôi nghĩ cuộc họp kéo dài hơn mức cần thiết.\n(B) Tôi ước chúng ta được thông báo về việc đó sớm hơn.\n(C) Tôi muốn đưa ra một đề xuất về chủ đề này.\n(D) Tôi sẽ rất vinh dự được dẫn dắt một buổi họp tiếp theo."},{"n":144,"opts":["will offer","have offered","were offering","should be offering"],"ans":"D","xp":"Thì/động từ khuyết thiếu. Câu trước cho biết hiện tại máy chỉ bán đồ nhiều đường, muối → người viết đang khuyên điều 'nên làm' nhưng chưa làm. (D) should be offering 'nên cung cấp' → chọn (D). (B) have offered và (C) were offering nói là đã cung cấp — mâu thuẫn với thực tế hiện tại; (A) will offer khẳng định chắc chắn sẽ làm, không phù hợp với một đề xuất.\nDịch: Là một đơn vị chăm sóc sức khỏe, chúng ta nên cung cấp đồ uống và đồ ăn vặt thể hiện cam kết của mình đối với sức khỏe."},{"n":145,"opts":["After all","By the way","In the meantime","On the other hand"],"ans":"A","xp":"Từ nối. Câu sau 'our mission is focused on good health' là lý do củng cố cho ý trước (nên bán đồ ăn lành mạnh) → (A) After all 'xét cho cùng, dù sao thì' → chọn (A). (B) By the way 'nhân tiện' dùng để chuyển chủ đề; (C) In the meantime 'trong lúc đó'; (D) On the other hand 'mặt khác' chỉ sự đối lập.\nDịch: Xét cho cùng, sứ mệnh của chúng ta tập trung vào sức khỏe tốt."},{"n":146,"opts":["useful","eventful","profitable","comfortable"],"ans":"A","xp":"Từ vựng. 'find it + tính từ' = thấy nó thế nào. Bài báo 'details some easy and cost-effective changes' (trình bày các thay đổi dễ và tiết kiệm) → hy vọng người nhận thấy nó 'hữu ích'. (A) useful → chọn (A). (B) eventful 'nhiều sự kiện', (C) profitable 'có lợi nhuận', (D) comfortable 'thoải mái' không hợp để nói về một bài báo.\nDịch: Tôi hy vọng bác sĩ thấy nó hữu ích."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following advertisement.","passages":["<h3>Medillo Shoes Celebrates Twenty Years in Cape Town!</h3>\n<p>246 Breda Place, Wynberg, Cape Town 7800<br>021 555 0149 | www.medilloshoes.co.za</p>\n<p>Does your job require you to stand all day long? Get the support you need! At Medillo Shoes, we specialise in comfortable, supportive footwear that is stylish and suitable for any business or medical setting.</p>\n<p>Visit us on 10 May to receive 20 percent off your purchase of one or more pairs of shoes during this anniversary event. Should you need assistance finding the best shoes for your professional needs, our footwear specialists will be on hand to help. Schedule a free consultation at www.medilloshoes.co.za to avoid a long wait.</p>"],"vi":"Medillo Shoes kỷ niệm 20 năm tại Cape Town!\n246 Breda Place, Wynberg, Cape Town 7800 | 021 555 0149 | www.medilloshoes.co.za\n\nCông việc của bạn có đòi hỏi phải đứng cả ngày không? Hãy có được sự nâng đỡ mà bạn cần! Tại Medillo Shoes, chúng tôi chuyên về giày dép thoải mái, nâng đỡ tốt, vừa thời trang vừa phù hợp với mọi môi trường công sở hoặc y tế.\n\nHãy ghé thăm chúng tôi vào ngày 10 tháng 5 để được giảm 20% khi mua một hoặc nhiều đôi giày trong sự kiện kỷ niệm này. Nếu bạn cần hỗ trợ tìm đôi giày tốt nhất cho nhu cầu công việc, các chuyên viên giày dép của chúng tôi sẽ có mặt để giúp đỡ. Hãy đặt lịch tư vấn miễn phí tại www.medilloshoes.co.za để tránh phải chờ lâu.","qs":[{"n":147,"q":"What will happen at Medillo Shoes on May 10?","qvi":"Điều gì sẽ diễn ra tại Medillo Shoes vào ngày 10 tháng 5?","opts":["All shoes will be discounted.","Shop assistants will be hired.","A shoe style will be discontinued.","Operational hours will be extended."],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"Visit us on 10 May to receive 20 percent off your purchase of one or more pairs of shoes\" (ghé vào ngày 10/5 để được giảm 20% khi mua một hoặc nhiều đôi giày) → mọi đôi giày đều được giảm giá. \"20 percent off\" được diễn đạt lại thành \"discounted\" → chọn (A). Bài không nhắc đến tuyển nhân viên, ngừng bán mẫu giày hay kéo dài giờ mở cửa.\n(A) Tất cả giày sẽ được giảm giá.\n(B) Nhân viên bán hàng sẽ được tuyển.\n(C) Một mẫu giày sẽ bị ngừng bán.\n(D) Giờ hoạt động sẽ được kéo dài."},{"n":148,"q":"What is indicated about Medillo Shoes?","qvi":"Điều gì được nêu về Medillo Shoes?","opts":["It has been in business for ten years.","It specializes in athletic footwear.","It is located next to a medical center.","It allows customers to make appointments."],"ans":"D","xp":"Câu hỏi chi tiết (thông tin được nêu). Bằng chứng: \"Schedule a free consultation at www.medilloshoes.co.za\" (đặt lịch tư vấn miễn phí trên website) → khách hàng có thể đặt lịch hẹn → chọn (D). (A) sai vì cửa hàng đã hoạt động 20 năm (\"Twenty Years\"), không phải 10. (B) sai vì cửa hàng chuyên giày cho công sở và y tế (\"business or medical setting\"), không phải giày thể thao. (C) không được nhắc đến.\n(A) Cửa hàng đã kinh doanh được mười năm.\n(B) Cửa hàng chuyên về giày thể thao.\n(C) Cửa hàng nằm cạnh một trung tâm y tế.\n(D) Cửa hàng cho phép khách hàng đặt lịch hẹn."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Sales Team</p><p><b>From:</b> Neil Cullen</p><p><b>Date:</b> 10 April</p><p><b>Subject:</b> My schedule next week</p></div>\n<p>Dear Team,</p>\n<p>I will be out of the office next week, from 15 to 19 April, attending the conference of the National Technology Alliance in Glasgow. While away, I will check e-mail and voice mail infrequently. For any urgent matters, please contact my assistant, Christina Choo. If you have a specific question about the Ezenx Industries account, please e-mail Mya Soroka.<br>I will be back in the office on 22 April and will see all of you then.</p>\n<p>Best,</p>\n<p>Neil Cullen, Director of Sales and Marketing<br>Shallok Technology</p>"],"vi":"Đến: Nhóm Kinh doanh\nTừ: Neil Cullen\nNgày: 10 tháng 4\nTiêu đề: Lịch làm việc của tôi tuần tới\n\nGửi cả nhóm,\n\nTôi sẽ vắng mặt ở văn phòng vào tuần tới, từ ngày 15 đến 19 tháng 4, để tham dự hội nghị của Liên minh Công nghệ Quốc gia tại Glasgow. Trong thời gian đi vắng, tôi sẽ không thường xuyên kiểm tra e-mail và hộp thư thoại. Đối với mọi vấn đề khẩn cấp, vui lòng liên hệ trợ lý của tôi, Christina Choo. Nếu các bạn có câu hỏi cụ thể về tài khoản khách hàng Ezenx Industries, vui lòng gửi e-mail cho Mya Soroka. Tôi sẽ trở lại văn phòng vào ngày 22 tháng 4 và sẽ gặp mọi người khi đó.\n\nTrân trọng,\n\nNeil Cullen, Giám đốc Kinh doanh và Tiếp thị\nShallok Technology","qs":[{"n":149,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To register for a conference","To announce a new account","To schedule a meeting","To inform colleagues of an absence"],"ans":"D","xp":"Câu hỏi mục đích. Bằng chứng: \"I will be out of the office next week, from 15 to 19 April\" (tôi sẽ vắng mặt ở văn phòng tuần tới) và tiêu đề \"My schedule next week\" → ông Cullen báo cho đồng nghiệp biết mình sẽ vắng mặt → chọn (D). (A) sai: ông có đi hội nghị nhưng e-mail không nhằm đăng ký. (B) Ezenx Industries chỉ được nhắc đến, không phải tài khoản mới. (C) không có lịch họp nào được sắp xếp.\n(A) Để đăng ký tham dự một hội nghị\n(B) Để thông báo một tài khoản khách hàng mới\n(C) Để lên lịch một cuộc họp\n(D) Để thông báo cho đồng nghiệp về việc vắng mặt"},{"n":150,"q":"What is most likely true about Ms. Soroka?","qvi":"Điều gì nhiều khả năng đúng về cô Soroka?","opts":["She will be traveling with Mr. Cullen.","She works on the Ezenx Industries account.","She is Ms. Choo's supervisor.","She will be out of the office until April 22."],"ans":"B","xp":"Câu hỏi suy luận. Bằng chứng: \"If you have a specific question about the Ezenx Industries account, please e-mail Mya Soroka.\" (có câu hỏi cụ thể về tài khoản Ezenx Industries thì gửi e-mail cho Mya Soroka) → cô Soroka phụ trách / làm việc với tài khoản Ezenx Industries → chọn (B). (A), (C) không có thông tin. (D) sai: người vắng mặt đến 22/4 là ông Cullen.\n(A) Cô ấy sẽ đi công tác cùng ông Cullen.\n(B) Cô ấy làm việc với tài khoản Ezenx Industries.\n(C) Cô ấy là cấp trên của cô Choo.\n(D) Cô ấy sẽ vắng mặt ở văn phòng đến ngày 22 tháng 4."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following notice.","passages":["<h3>CITY OF BRYANTON<br>Building Permit Office</h3>\n<h4>Notice for residents and contractors working in Bryanton</h4>\n<p>Beginning on Monday, July 1, the City of Bryanton's Building Permit Office, located at 912 Fir Avenue, will be open from Monday to Thursday, 9:00 A.M. to 5:00 P.M. Applications for permits will no longer be accepted on Fridays or Saturdays. The average processing time for permit applications will remain three business days. With this change, the city will lower its operating costs while maintaining its high standards of service for residents.</p>"],"vi":"THÀNH PHỐ BRYANTON\nVăn phòng Cấp phép Xây dựng\n\nThông báo dành cho cư dân và nhà thầu làm việc tại Bryanton\n\nBắt đầu từ thứ Hai, ngày 1 tháng 7, Văn phòng Cấp phép Xây dựng của Thành phố Bryanton, tọa lạc tại số 912 đại lộ Fir, sẽ mở cửa từ thứ Hai đến thứ Năm, 9 giờ sáng đến 5 giờ chiều. Hồ sơ xin giấy phép sẽ không còn được tiếp nhận vào thứ Sáu hoặc thứ Bảy. Thời gian xử lý hồ sơ trung bình vẫn giữ nguyên là ba ngày làm việc. Với thay đổi này, thành phố sẽ giảm chi phí vận hành trong khi vẫn duy trì tiêu chuẩn phục vụ cao cho cư dân.","qs":[{"n":151,"q":"What change is the Building Permit Office making?","qvi":"Văn phòng Cấp phép Xây dựng đang thực hiện thay đổi gì?","opts":["It is moving to a new location.","It is simplifying the permit application process.","It is reducing the number of days it will accept permit applications.","It is increasing the processing time for permit applications."],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"will be open from Monday to Thursday\" và \"Applications for permits will no longer be accepted on Fridays or Saturdays.\" (không còn nhận hồ sơ vào thứ Sáu, thứ Bảy) → số ngày nhận hồ sơ giảm đi → chọn (C). (A) sai: văn phòng vẫn ở 912 Fir Avenue. (B) không được nhắc. (D) sai: thời gian xử lý \"will remain three business days\" (giữ nguyên).\n(A) Văn phòng sẽ chuyển đến địa điểm mới.\n(B) Văn phòng đang đơn giản hóa quy trình xin giấy phép.\n(C) Văn phòng đang giảm số ngày tiếp nhận hồ sơ xin giấy phép.\n(D) Văn phòng đang tăng thời gian xử lý hồ sơ."},{"n":152,"q":"According to the notice, why is the change being made?","qvi":"Theo thông báo, tại sao lại có thay đổi này?","opts":["To save the city money","To attract more residents","To improve the quality of service","To decrease the number of new permit applications"],"ans":"A","xp":"Câu hỏi chi tiết (lý do). Bằng chứng: \"With this change, the city will lower its operating costs\" (thành phố sẽ giảm chi phí vận hành) → \"lower operating costs\" = \"save the city money\" → chọn (A). (C) sai: thành phố chỉ \"maintaining\" (duy trì) chất lượng phục vụ, không phải cải thiện. (B), (D) không được nhắc.\n(A) Để tiết kiệm tiền cho thành phố\n(B) Để thu hút thêm cư dân\n(C) Để nâng cao chất lượng phục vụ\n(D) Để giảm số lượng hồ sơ xin giấy phép mới"}]},{"ns":[153,155],"head":"Questions 153-155 refer to the following receipt.","passages":["<p>https://www.riverthamestours.uk/order/confirmation</p>\n<h4>River Thames Tours</h4>\n<p>Thank you for reserving a River Thames tour with us. We are eager to welcome you aboard. Each tour lasts 3 hours. Your tour includes a luncheon served at 1:00 p.m. Please consult our Web site for a menu. Should you have any dietary restrictions and like to request a special meal, please contact our customer experience manager, Martin Torma, at least 48 hours prior to your tour.</p>\n<p>This reservation also entitles you to a 10 percent discount on a walking tour by Edgerton Walking Tours—just provide your confirmation code when booking.</p>\n<table><tr><th>Name:</th><td>Lewis Califf</td></tr><tr><th>Purchase Date:</th><td>18 April</td></tr><tr><th>Confirmation Code:</th><td>H102057</td></tr><tr><th>Tour Start:</th><td>1 May, 11:30 a.m.</td></tr><tr><th>Quantity:</th><td>4</td></tr><tr><th>Total:</th><td>£180.00</td></tr><tr><th>Payment:</th><td>Credit card ending in 1037</td></tr></table>\n<p>Please note: Boarding ends 10 minutes before departure time.<br>Tours cannot be rescheduled.</p>"],"vi":"https://www.riverthamestours.uk/order/confirmation\n\nRiver Thames Tours\n\nCảm ơn quý khách đã đặt một chuyến tham quan sông Thames với chúng tôi. Chúng tôi rất mong được chào đón quý khách lên tàu. Mỗi chuyến tham quan kéo dài 3 giờ. Chuyến đi của quý khách bao gồm một bữa trưa được phục vụ lúc 1 giờ chiều. Vui lòng xem thực đơn trên trang web của chúng tôi. Nếu quý khách có bất kỳ hạn chế nào về ăn uống và muốn yêu cầu một bữa ăn đặc biệt, vui lòng liên hệ quản lý trải nghiệm khách hàng của chúng tôi, Martin Torma, ít nhất 48 giờ trước chuyến đi.\n\nViệc đặt chỗ này cũng giúp quý khách được giảm giá 10% cho một chuyến tham quan đi bộ của Edgerton Walking Tours — chỉ cần cung cấp mã xác nhận khi đặt chỗ.\n\nTên: Lewis Califf\nNgày mua: 18 tháng 4\nMã xác nhận: H102057\nThời gian bắt đầu chuyến đi: 1 tháng 5, 11:30 sáng\nSố lượng: 4\nTổng cộng: £180.00\nThanh toán: Thẻ tín dụng có số cuối 1037\n\nXin lưu ý: Việc lên tàu kết thúc 10 phút trước giờ khởi hành. Không thể đổi lịch chuyến tham quan.","qs":[{"n":153,"q":"What is indicated about the river tour?","qvi":"Điều gì được nêu về chuyến tham quan trên sông?","opts":["It is one hour long.","It comes with a meal.","It can be rescheduled.","It sells out quickly."],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"Your tour includes a luncheon served at 1:00 p.m.\" (chuyến đi bao gồm một bữa trưa) → \"luncheon\" = \"a meal\" → chọn (B). (A) sai: \"Each tour lasts 3 hours\". (C) sai: \"Tours cannot be rescheduled.\" (D) không được nhắc.\n(A) Chuyến đi dài một giờ.\n(B) Chuyến đi có kèm một bữa ăn.\n(C) Chuyến đi có thể đổi lịch.\n(D) Chuyến đi bán hết vé rất nhanh."},{"n":154,"q":"How many tickets did Mr. Califf purchase?","qvi":"Ông Califf đã mua bao nhiêu vé?","opts":["1","3","4","7"],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: trong phần thông tin đặt chỗ ghi \"Quantity: 4\" (số lượng: 4) → ông Califf mua 4 vé → chọn (C). Các con số khác là bẫy: 3 là số giờ của chuyến đi, 1037 là số cuối thẻ tín dụng.\n(A) 1\n(B) 3\n(C) 4\n(D) 7"},{"n":155,"q":"How can customers receive a discount on a walking tour?","qvi":"Khách hàng có thể được giảm giá cho chuyến tham quan đi bộ bằng cách nào?","opts":["By making a reservation online","By paying with a credit card","By requesting a coupon from the captain","By mentioning a confirmation code"],"ans":"D","xp":"Câu hỏi chi tiết. Bằng chứng: \"a 10 percent discount on a walking tour by Edgerton Walking Tours—just provide your confirmation code when booking\" (chỉ cần cung cấp mã xác nhận khi đặt chỗ) → \"provide your confirmation code\" = \"mentioning a confirmation code\" → chọn (D). Các cách khác không được nhắc đến.\n(A) Bằng cách đặt chỗ trực tuyến\n(B) Bằng cách thanh toán bằng thẻ tín dụng\n(C) Bằng cách xin phiếu giảm giá từ thuyền trưởng\n(D) Bằng cách cung cấp mã xác nhận"}]},{"ns":[156,157],"head":"Questions 156-157 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Michiko Saunders [8:06 A.M.]</b></p><p>Hi, Jacob. Are you on your way to the office?</p></div>\n<div class=\"msg\"><p><b>Jacob Kwon [8:08 A.M.]</b></p><p>Yes. I should be there in about 25 minutes.</p></div>\n<div class=\"msg\"><p><b>Michiko Saunders [8:10 A.M.]</b></p><p>OK. I was just starting to print out the design proposal for the Dansby Group, but we've run out of paper. And we don't have another delivery of it coming until Wednesday.</p></div>\n<div class=\"msg\"><p><b>Jacob Kwon [8:12 A.M.]</b></p><p>I see an office supply store across the street. It just opened for the day.</p></div>\n<div class=\"msg\"><p><b>Michiko Saunders [8:13 A.M.]</b></p><p>Fantastic. Three packs of paper should be enough.</p></div>\n<div class=\"msg\"><p><b>Jacob Kwon [8:15 A.M.]</b></p><p>OK. By the way, when will the representatives from the Dansby Group be coming to our office? I could also pick up some coffee and snacks for that meeting.</p></div>"],"vi":"Michiko Saunders [8:06 sáng]: Chào Jacob. Anh đang trên đường đến văn phòng à?\n\nJacob Kwon [8:08 sáng]: Đúng vậy. Khoảng 25 phút nữa tôi sẽ đến nơi.\n\nMichiko Saunders [8:10 sáng]: Được rồi. Tôi vừa mới bắt đầu in bản đề xuất thiết kế cho Tập đoàn Dansby thì chúng ta hết giấy. Và phải đến thứ Tư mới có đợt giao giấy tiếp theo.\n\nJacob Kwon [8:12 sáng]: Tôi thấy có một cửa hàng văn phòng phẩm ở bên kia đường. Nó vừa mới mở cửa.\n\nMichiko Saunders [8:13 sáng]: Tuyệt quá. Ba gói giấy chắc là đủ.\n\nJacob Kwon [8:15 sáng]: OK. Nhân tiện, khi nào thì đại diện của Tập đoàn Dansby sẽ đến văn phòng chúng ta? Tôi cũng có thể mua thêm ít cà phê và đồ ăn nhẹ cho cuộc họp đó.","qs":[{"n":156,"q":"At 8:12 A.M., what does Mr. Kwon most likely mean when he writes, \"I see an office supply store across the street\"?","qvi":"Lúc 8:12 sáng, khi ông Kwon viết \"Tôi thấy có một cửa hàng văn phòng phẩm ở bên kia đường\", nhiều khả năng ông ấy có ý gì?","opts":["He needs help finding a building.","He can purchase some paper.","He will look for a new printer.","He is going to negotiate a delivery schedule."],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó cô Saunders viết \"we've run out of paper. And we don't have another delivery of it coming until Wednesday.\" (hết giấy, thứ Tư mới có hàng). Ông Kwon trả lời rằng thấy cửa hàng văn phòng phẩm bên kia đường và \"It just opened for the day\" → ý là ông có thể ghé mua giấy. Cô Saunders đáp \"Three packs of paper should be enough.\" xác nhận điều đó → chọn (B).\n(A) Ông ấy cần giúp đỡ để tìm một tòa nhà.\n(B) Ông ấy có thể mua một ít giấy.\n(C) Ông ấy sẽ tìm một máy in mới.\n(D) Ông ấy sẽ thương lượng lịch giao hàng."},{"n":157,"q":"What will Ms. Saunders most likely do next?","qvi":"Cô Saunders nhiều khả năng sẽ làm gì tiếp theo?","opts":["Reschedule a meeting","Prepare some refreshments","Check on an arrival time","Revise a design proposal"],"ans":"C","xp":"Câu hỏi suy luận (việc làm tiếp theo). Tin nhắn cuối của ông Kwon hỏi: \"when will the representatives from the Dansby Group be coming to our office?\" (khi nào đại diện Dansby đến văn phòng?) → cô Saunders sẽ kiểm tra/trả lời về thời gian họ đến → chọn (C). (B) sai: chính ông Kwon đề nghị mua cà phê và đồ ăn nhẹ. (A), (D) không được nhắc đến.\n(A) Dời lịch một cuộc họp\n(B) Chuẩn bị đồ ăn uống nhẹ\n(C) Kiểm tra thời gian khách đến\n(D) Chỉnh sửa bản đề xuất thiết kế"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following letter.","passages":["<p>Kipbank Business Services<br>548 Sycamore Lake Road<br>Green Bay, WI 54301</p>\n<p>April 2</p>\n<p>Madeline Omar<br>Passionflower Interior Design<br>1556 Deer Run Road<br>Green Bay, WI 54301</p>\n<p>Dear Ms. Omar,</p>\n<p>A business owner's days are filled with juggling the wants, needs, and demands of customers, staff, and suppliers. <span class=\"pos\">[1]</span></p>\n<p>Let Kipbank find the right solutions for your small business so that you can focus on your products and people. Kipbank offers checking accounts, corporate credit cards, business loans, and payroll and bookkeeping services. <span class=\"pos\">[2]</span> This fall, we will also add financial planners to our team to help you and your employees plan for your futures.</p>\n<p>With our corporate credit cards, Kipbank customers can take advantage of money-saving offers from selected hotel, office supply, and air travel partners. <span class=\"pos\">[3]</span> These deals are automatically applied to qualified purchases. And the business owner can place spending limits on each card. <span class=\"pos\">[4]</span></p>\n<p>Please call us at 920-555-0122 to set up an appointment or just stop by when it is convenient. We look forward to meeting you and providing your enterprise with superior service.</p>\n<p>Sincerely,</p>\n<p><i>Thomas Piskorksi</i><br>Thomas Piskorksi, Kipbank Customer Concierge</p>"],"vi":"Kipbank Business Services\n548 Sycamore Lake Road\nGreen Bay, WI 54301\n\nNgày 2 tháng 4\n\nMadeline Omar\nPassionflower Interior Design\n1556 Deer Run Road\nGreen Bay, WI 54301\n\nKính gửi bà Omar,\n\nMỗi ngày của một chủ doanh nghiệp đều kín đặc với việc xoay xở giữa những mong muốn, nhu cầu và yêu cầu của khách hàng, nhân viên và nhà cung cấp. [1]\n\nHãy để Kipbank tìm ra những giải pháp phù hợp cho doanh nghiệp nhỏ của bà, để bà có thể tập trung vào sản phẩm và con người của mình. Kipbank cung cấp tài khoản thanh toán, thẻ tín dụng doanh nghiệp, khoản vay kinh doanh, cùng dịch vụ tính lương và kế toán sổ sách. [2] Mùa thu này, chúng tôi cũng sẽ bổ sung các chuyên viên hoạch định tài chính vào đội ngũ để giúp bà và nhân viên lên kế hoạch cho tương lai.\n\nVới thẻ tín dụng doanh nghiệp của chúng tôi, khách hàng Kipbank có thể tận dụng các ưu đãi tiết kiệm tiền từ những đối tác khách sạn, văn phòng phẩm và hàng không được chọn lọc. [3] Các ưu đãi này được tự động áp dụng cho những giao dịch mua đủ điều kiện. Ngoài ra, chủ doanh nghiệp có thể đặt hạn mức chi tiêu cho từng thẻ. [4]\n\nVui lòng gọi cho chúng tôi theo số 920-555-0122 để đặt lịch hẹn, hoặc cứ ghé qua khi nào thuận tiện. Chúng tôi rất mong được gặp bà và mang đến cho doanh nghiệp của bà dịch vụ tuyệt vời.\n\nTrân trọng,\n\nThomas Piskorksi, Nhân viên Hỗ trợ Khách hàng của Kipbank","qs":[{"n":158,"q":"What is suggested about Ms. Omar?","qvi":"Điều gì được ngụ ý về bà Omar?","opts":["She is an accountant.","She works for Mr. Piskorksi.","She operates a small company.","She is a Kipbank customer."],"ans":"C","xp":"Câu hỏi suy luận. Thư gửi bà Omar ở công ty \"Passionflower Interior Design\" và nói \"Let Kipbank find the right solutions for your small business\" (giải pháp cho doanh nghiệp nhỏ của bà), cùng với \"A business owner's days...\" → bà Omar là chủ/điều hành một công ty nhỏ → chọn (C). (D) sai: đây là thư chào mời, mời bà gọi điện đặt lịch hẹn, tức bà chưa phải khách hàng. (A), (B) không có thông tin.\n(A) Bà ấy là kế toán viên.\n(B) Bà ấy làm việc cho ông Piskorksi.\n(C) Bà ấy điều hành một công ty nhỏ.\n(D) Bà ấy là khách hàng của Kipbank."},{"n":159,"q":"What is stated about the credit cards?","qvi":"Điều gì được nêu về các thẻ tín dụng?","opts":["They come in a variety of colors.","They require an annual fee.","They include discounts on certain purchases.","They can be used to buy personal items."],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"Kipbank customers can take advantage of money-saving offers from selected hotel, office supply, and air travel partners... These deals are automatically applied to qualified purchases.\" → \"money-saving offers\" + \"qualified purchases\" = \"discounts on certain purchases\" → chọn (C). Màu sắc, phí thường niên hay mua đồ cá nhân không được nhắc đến.\n(A) Thẻ có nhiều màu sắc khác nhau.\n(B) Thẻ yêu cầu phí thường niên.\n(C) Thẻ có kèm giảm giá cho một số giao dịch mua nhất định.\n(D) Thẻ có thể dùng để mua đồ dùng cá nhân."},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Everyday financial details only add more distractions.\"","qvi":"Câu sau đây phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Những chi tiết tài chính hằng ngày chỉ làm tăng thêm sự xao nhãng.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"A","xp":"Câu hỏi điền câu. Câu trước vị trí [1] nói chủ doanh nghiệp phải \"juggling the wants, needs, and demands of customers, staff, and suppliers\" (xoay xở với nhiều yêu cầu). Câu cần điền nói thêm \"chi tiết tài chính hằng ngày chỉ làm tăng thêm sự xao nhãng\" – \"more distractions\" nối tiếp ý những việc bận rộn đó. Đoạn sau mở đầu bằng \"Let Kipbank find the right solutions... so that you can focus on your products and people\" – giải pháp để bớt xao nhãng, tập trung hơn → mạch logic: vấn đề → xao nhãng thêm → giải pháp. Chọn (A) [1].\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following article.","passages":["<p>OTTAWA (22 May)—<i>Waldenstone Business Review</i> has added a new category to its esteemed international business awards this year. The Waldenstone Corporate Prize is awarded to a business with the foresight to develop strategies that help ensure the company's long-term viability.</p>\n<p>This year's award was presented to Carila Corporation, a major player in the electronics sector. Under the direction of CEO Atsak Kakar, Carila Corporation went from near bankruptcy to a high level of profitability in just three years.</p>\n<p>\"Winning this award was very gratifying, not just for me but for the entire company,\" Mr. Kakar said upon receiving the award. \"Everyone has worked extremely hard to get this company back on solid financial ground. The long-term solution has brought exceptional value to our shareholders.\"</p>"],"vi":"OTTAWA (22 tháng 5) — Tạp chí Waldenstone Business Review năm nay đã bổ sung một hạng mục mới vào giải thưởng kinh doanh quốc tế danh giá của mình. Giải thưởng Doanh nghiệp Waldenstone được trao cho một doanh nghiệp có tầm nhìn xa trong việc xây dựng các chiến lược giúp đảm bảo khả năng phát triển bền vững lâu dài của công ty.\n\nGiải thưởng năm nay được trao cho Tập đoàn Carila, một doanh nghiệp lớn trong lĩnh vực điện tử. Dưới sự lãnh đạo của Giám đốc điều hành Atsak Kakar, Tập đoàn Carila đã đi từ bờ vực phá sản đến mức lợi nhuận cao chỉ trong vòng ba năm.\n\n\"Giành được giải thưởng này thật sự rất mãn nguyện, không chỉ với tôi mà với toàn thể công ty,\" ông Kakar phát biểu khi nhận giải. \"Mọi người đã làm việc cực kỳ chăm chỉ để đưa công ty trở lại nền tảng tài chính vững chắc. Giải pháp dài hạn đã mang lại giá trị đặc biệt cho các cổ đông của chúng tôi.\"","qs":[{"n":161,"q":"What is the purpose of the article?","qvi":"Mục đích của bài báo là gì?","opts":["To profile a newly opened business","To analyze a trend in the electronics industry","To highlight a company's achievement","To discuss changes to an employment contract"],"ans":"C","xp":"Câu hỏi mục đích. Bài báo cho biết \"This year's award was presented to Carila Corporation\" và công ty này \"went from near bankruptcy to a high level of profitability in just three years\" → bài viết nêu bật thành tích của một công ty (nhận giải thưởng) → chọn (C). (A) sai: Carila không phải công ty mới mở. (B) không phân tích xu hướng ngành. (D) không nhắc đến hợp đồng lao động.\n(A) Để giới thiệu một doanh nghiệp mới khai trương\n(B) Để phân tích một xu hướng trong ngành điện tử\n(C) Để nêu bật thành tích của một công ty\n(D) Để bàn về những thay đổi trong hợp đồng lao động"},{"n":162,"q":"What is suggested about Carila Corporation?","qvi":"Điều gì được ngụ ý về Tập đoàn Carila?","opts":["It no longer develops electronics.","It was once a struggling business.","It has been unable to attract more clients.","It is seeking to replace its CEO."],"ans":"B","xp":"Câu hỏi suy luận. Bằng chứng: \"Carila Corporation went from near bankruptcy to a high level of profitability\" (từ bờ vực phá sản) và \"to get this company back on solid financial ground\" → công ty từng gặp khó khăn → \"near bankruptcy\" = \"a struggling business\" → chọn (B). (A) sai: Carila vẫn là \"a major player in the electronics sector\". (C), (D) không có thông tin.\n(A) Công ty không còn phát triển đồ điện tử.\n(B) Công ty từng là một doanh nghiệp gặp khó khăn.\n(C) Công ty không thể thu hút thêm khách hàng.\n(D) Công ty đang tìm người thay thế CEO."},{"n":163,"q":"The word \"solution\" in paragraph 3, line 6, is closest in meaning to","qvi":"Từ \"solution\" ở đoạn 3, dòng 6, gần nghĩa nhất với","opts":["mixture","proof","statement","answer"],"ans":"D","xp":"Câu hỏi đồng nghĩa. Câu gốc: \"The long-term solution has brought exceptional value to our shareholders.\" Ở đây \"solution\" là \"giải pháp\" cho vấn đề tài chính của công ty → gần nghĩa nhất là \"answer\" (lời giải, cách giải quyết) → chọn (D). Lưu ý: \"solution\" còn có nghĩa \"dung dịch\" (gần với mixture – hỗn hợp), nhưng không hợp ngữ cảnh.\n(A) hỗn hợp\n(B) bằng chứng\n(C) lời tuyên bố\n(D) lời giải, cách giải quyết"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following advertisement.","passages":["<h3>Commbolt is for Everyone!</h3>\n<p>As a Commbolt customer, you've come to expect the best in reliable high-speed Internet, straightforward pricing options, and top-notch customer service from friendly professionals who are responsive to your every need. <span class=\"pos\">[1]</span> Unlike the competition, we promise to never lock you into inflexible contracts or suddenly raise your monthly bill without notice.</p>\n<p>At Commbolt, we know you have options when it comes to choosing an Internet service provider. <span class=\"pos\">[2]</span> To show our gratitude for your loyalty, we are offering a special limited-time referral bonus.</p>\n<p>The way it works is simple. <span class=\"pos\">[3]</span> You can use e-mail, social media, or even text messages to tell everyone about Commbolt. When a new user signs up using your code, each of you will receive a monetary credit. Receive $10 when new referrals sign up for a monthly plan at $45, and receive $20 for a plan costing $60 per month. The best news? <span class=\"pos\">[4]</span> There is no limit to the credits; the more people you sign up, the more money you get.</p>\n<p>Your unique code is <b>XA4R177</b>.</p>"],"vi":"Commbolt dành cho tất cả mọi người!\n\nLà khách hàng của Commbolt, bạn đã quen mong đợi những điều tốt nhất: Internet tốc độ cao ổn định, các gói giá rõ ràng dễ hiểu, và dịch vụ khách hàng hàng đầu từ những chuyên viên thân thiện, luôn đáp ứng mọi nhu cầu của bạn. [1] Không giống như các đối thủ, chúng tôi cam kết không bao giờ ràng buộc bạn vào những hợp đồng cứng nhắc hay đột ngột tăng hóa đơn hằng tháng mà không báo trước.\n\nTại Commbolt, chúng tôi biết bạn có nhiều lựa chọn khi chọn nhà cung cấp dịch vụ Internet. [2] Để bày tỏ lòng biết ơn vì sự gắn bó của bạn, chúng tôi đang có chương trình thưởng giới thiệu đặc biệt trong thời gian có hạn.\n\nCách thức rất đơn giản. [3] Bạn có thể dùng e-mail, mạng xã hội hoặc thậm chí tin nhắn để giới thiệu Commbolt với mọi người. Khi một người dùng mới đăng ký bằng mã của bạn, cả hai sẽ nhận được một khoản tín dụng bằng tiền. Nhận 10 đô la khi người được giới thiệu đăng ký gói hằng tháng 45 đô la, và nhận 20 đô la cho gói 60 đô la mỗi tháng. Tin tốt nhất là gì? [4] Không có giới hạn tín dụng; bạn giới thiệu được càng nhiều người đăng ký, bạn càng nhận được nhiều tiền.\n\nMã riêng của bạn là XA4R177.","qs":[{"n":164,"q":"What Commbolt benefit does the advertisement mention?","qvi":"Quảng cáo nhắc đến lợi ích nào của Commbolt?","opts":["Its low prices","Its excellent customer service","Its lifetime contracts","Its convenient installation schedule"],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"top-notch customer service from friendly professionals who are responsive to your every need\" → \"top-notch\" (hàng đầu) = \"excellent\" → chọn (B). (A) sai: bài nói \"straightforward pricing options\" (giá rõ ràng), không nói giá rẻ. (C) sai: Commbolt hứa không ràng buộc khách bằng hợp đồng cứng nhắc. (D) không được nhắc đến.\n(A) Giá thấp\n(B) Dịch vụ khách hàng xuất sắc\n(C) Hợp đồng trọn đời\n(D) Lịch lắp đặt thuận tiện"},{"n":165,"q":"What is the maximum amount a customer can earn when one referred person signs up for service?","qvi":"Số tiền tối đa một khách hàng có thể nhận được khi một người được giới thiệu đăng ký dịch vụ là bao nhiêu?","opts":["$10.00","$20.00","$45.00","$60.00"],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"Receive $10 when new referrals sign up for a monthly plan at $45, and receive $20 for a plan costing $60 per month.\" → với mỗi người được giới thiệu, mức thưởng cao nhất là $20 (khi họ đăng ký gói $60) → chọn (B). $45 và $60 là giá các gói cước, không phải tiền thưởng.\n(A) 10 đô la\n(B) 20 đô la\n(C) 45 đô la\n(D) 60 đô la"},{"n":166,"q":"What is true about the Commbolt promotion?","qvi":"Điều gì đúng về chương trình khuyến mãi của Commbolt?","opts":["It may not be posted on social media.","It does not provide credit for more than three referrals.","It is expected to run for a full year.","It rewards both new and existing customers."],"ans":"D","xp":"Câu hỏi chi tiết (điều gì đúng). Bằng chứng: \"When a new user signs up using your code, each of you will receive a monetary credit.\" (cả bạn – khách hàng hiện tại – và người dùng mới đều nhận tín dụng) → chọn (D). (A) sai: \"You can use e-mail, social media...\". (B) sai: \"There is no limit to the credits\". (C) sai: đây là chương trình \"limited-time\" (có thời hạn), không nói kéo dài cả năm.\n(A) Không được đăng chương trình lên mạng xã hội.\n(B) Không tặng tín dụng cho quá ba lượt giới thiệu.\n(C) Chương trình dự kiến kéo dài cả năm.\n(D) Chương trình thưởng cho cả khách hàng mới lẫn khách hàng hiện tại."},{"n":167,"q":"In which of the positions marked [1], [2], [3], or [4] does the following sentence best belong?\n\"Just share your unique referral code with friends and family.\"","qvi":"Câu sau đây phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Chỉ cần chia sẻ mã giới thiệu riêng của bạn với bạn bè và gia đình.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Câu hỏi điền câu. Trước [3] là \"The way it works is simple.\" (cách thức rất đơn giản) → câu tiếp theo hợp lý là hướng dẫn bước đầu tiên: \"Just share your unique referral code...\". Sau [3] là \"You can use e-mail, social media, or even text messages to tell everyone about Commbolt\" – giải thích cách chia sẻ mã, và \"When a new user signs up using your code\" nhắc lại \"your code\" → chọn (C) [3].\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following Web page.","passages":["<p>https://www.sarahscatering.com</p>\n<h3>Sarah's Catering—What You Serve Matters</h3>\n<p>Sarah's Catering is a family-owned-and-operated company. The company was founded ten years ago with a mission to provide the highest quality catering services in our community. We work closely with local growers and use only the freshest ingredients. Our menu items can be adapted to the client's taste or dietary needs. For example, we can prepare vegetarian, vegan, and gluten-free options.</p>\n<p>We provide catering for birthday parties, wedding receptions, corporate meetings, business holiday parties, and many other types of events. From planning the menu and preparing your food to engaging servers and cleanup staff for the event, Sarah's Catering has it covered.</p>\n<p>Sarah's Catering can cater lunches in your office for a minimum of twenty people. We offer delicious options to make your group's meal a satisfying experience.</p>\n<p>We're here to serve you! Ordering is fast and simple. Visit www.sarahscatering.com/quote to request a cost estimate for your next event.</p>\n<h4>What people are saying</h4>\n<p>\"Sarah's Catering was very easy to work with, and the food was delicious! Everyone in the office commented on how good the food was.\" — Glen Liu, Perkins Real Estate</p>\n<p>\"All the food was perfect, and the staff was the best.\" — Annie Pierce, Kania Marketing, Inc.</p>"],"vi":"https://www.sarahscatering.com\n\nSarah's Catering — Món bạn phục vụ rất quan trọng\n\nSarah's Catering là một công ty do gia đình sở hữu và điều hành. Công ty được thành lập cách đây mười năm với sứ mệnh cung cấp dịch vụ ăn uống chất lượng cao nhất cho cộng đồng của chúng tôi. Chúng tôi hợp tác chặt chẽ với các nhà nông địa phương và chỉ sử dụng những nguyên liệu tươi ngon nhất. Các món trong thực đơn có thể được điều chỉnh theo khẩu vị hoặc nhu cầu ăn uống của khách hàng. Ví dụ, chúng tôi có thể chuẩn bị các lựa chọn chay, thuần chay và không chứa gluten.\n\nChúng tôi cung cấp dịch vụ ăn uống cho tiệc sinh nhật, tiệc cưới, cuộc họp doanh nghiệp, tiệc mừng lễ của công ty và nhiều loại sự kiện khác. Từ lên thực đơn, chế biến món ăn đến thuê nhân viên phục vụ và dọn dẹp cho sự kiện, Sarah's Catering lo trọn gói.\n\nSarah's Catering có thể cung cấp bữa trưa tại văn phòng của bạn cho tối thiểu hai mươi người. Chúng tôi mang đến những lựa chọn ngon miệng để bữa ăn của tập thể bạn trở thành một trải nghiệm hài lòng.\n\nChúng tôi luôn sẵn sàng phục vụ bạn! Đặt hàng nhanh chóng và đơn giản. Hãy truy cập www.sarahscatering.com/quote để yêu cầu báo giá cho sự kiện tiếp theo của bạn.\n\nKhách hàng nói gì\n\"Làm việc với Sarah's Catering rất dễ dàng, và đồ ăn rất ngon! Mọi người trong văn phòng đều khen đồ ăn ngon.\" — Glen Liu, Perkins Real Estate\n\n\"Tất cả đồ ăn đều hoàn hảo, và nhân viên thì tuyệt vời nhất.\" — Annie Pierce, Kania Marketing, Inc.","qs":[{"n":168,"q":"What is indicated about Sarah's Catering?","qvi":"Điều gì được nêu về Sarah's Catering?","opts":["It uses locally sourced products.","It is twenty years old.","It specializes mainly in weddings.","It has an on-site dining room."],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"We work closely with local growers and use only the freshest ingredients.\" (hợp tác với nhà nông địa phương) → sử dụng sản phẩm có nguồn gốc địa phương → chọn (A). (B) sai: công ty thành lập \"ten years ago\"; con số 20 là số người tối thiểu cho bữa trưa văn phòng. (C) sai: công ty phục vụ nhiều loại sự kiện, không chỉ đám cưới. (D) không được nhắc.\n(A) Công ty sử dụng sản phẩm có nguồn gốc địa phương.\n(B) Công ty đã hai mươi năm tuổi.\n(C) Công ty chủ yếu chuyên về tiệc cưới.\n(D) Công ty có phòng ăn tại chỗ."},{"n":169,"q":"The word \"taste\" in paragraph 1, line 4, is closest in meaning to","qvi":"Từ \"taste\" ở đoạn 1, dòng 4, gần nghĩa nhất với","opts":["preference","sample","experience","flavor"],"ans":"A","xp":"Câu hỏi đồng nghĩa. Câu gốc: \"Our menu items can be adapted to the client's taste or dietary needs.\" Ở đây \"taste\" là \"khẩu vị, sở thích\" của khách hàng → gần nghĩa nhất là \"preference\" (sự ưa thích) → chọn (A). (D) flavor là \"hương vị\" của món ăn, không phải sở thích của người ăn – đây là bẫy.\n(A) sự ưa thích, sở thích\n(B) mẫu thử\n(C) trải nghiệm\n(D) hương vị"},{"n":170,"q":"What is mentioned as a service provided by Sarah's Catering?","qvi":"Dịch vụ nào được nhắc đến là do Sarah's Catering cung cấp?","opts":["Entertainment planning","Cooking demonstrations","Cleanup after meals","Rentals of tables and chairs"],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"From planning the menu and preparing your food to engaging servers and cleanup staff for the event, Sarah's Catering has it covered.\" → công ty lo cả nhân viên dọn dẹp → \"cleanup staff\" = \"Cleanup after meals\" → chọn (C). Lên kế hoạch giải trí, biểu diễn nấu ăn, cho thuê bàn ghế không được nhắc đến.\n(A) Lên kế hoạch chương trình giải trí\n(B) Biểu diễn nấu ăn\n(C) Dọn dẹp sau bữa ăn\n(D) Cho thuê bàn ghế"},{"n":171,"q":"Who most likely is Mr. Liu?","qvi":"Ông Liu nhiều khả năng là ai?","opts":["An employee of Sarah's Catering","A professional event manager","A customer of Sarah's Catering","An assistant at a marketing firm"],"ans":"C","xp":"Câu hỏi suy luận. Ông Glen Liu xuất hiện trong mục \"What people are saying\" (khách hàng nói gì) với nhận xét \"Sarah's Catering was very easy to work with, and the food was delicious! Everyone in the office commented on how good the food was.\" → ông là khách hàng đã dùng dịch vụ → chọn (C). (D) sai: ông làm ở Perkins Real Estate (bất động sản); người làm ở công ty marketing là Annie Pierce.\n(A) Một nhân viên của Sarah's Catering\n(B) Một người quản lý sự kiện chuyên nghiệp\n(C) Một khách hàng của Sarah's Catering\n(D) Một trợ lý tại một công ty tiếp thị"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Marcus Steuber [10:41 A.M.]</b></p><p>Are we still planning to have the author video conference today? I haven't yet received a meeting invitation.</p></div>\n<div class=\"msg\"><p><b>Brinda Rajan [10:42 A.M.]</b></p><p>I do have the meeting on my calendar. Let me forward it to you; it appears our editorial assistant didn't include you.</p></div>\n<div class=\"msg\"><p><b>Marcus Steuber [10:43 A.M.]</b></p><p>Thanks, I just received it. The timing doesn't work for me, though. I have an appointment with Hazel Luong to discuss the printing issues at our Singapore plant.</p></div>\n<div class=\"msg\"><p><b>Brinda Rajan [10:44 A.M.]</b></p><p>Could you postpone that? The new author we're working with really needs your guidance on the final book design and formatting. You're our most knowledgeable production editor.</p></div>\n<div class=\"msg\"><p><b>Marcus Steuber [10:45 A.M.]</b></p><p>Let me check with my supervisor. I'll add Mr. Borg to our chat.</p></div>\n<div class=\"msg\"><p><b>Joshua Borg [10:47 A.M.]</b></p><p>Hi, team. Marcus, you should prioritize your appointment with Hazel. I'll be visiting the plant next week, and we need to have some viable solutions before then.</p></div>\n<div class=\"msg\"><p><b>Brinda Rajan [10:48 A.M.]</b></p><p>OK, I'll contact Ms. Benoit to find out if she can meet later in the day, then.</p></div>\n<div class=\"msg\"><p><b>Marcus Steuber [10:48 A.M.]</b></p><p>That would work. I'm free between 4 and 6 P.M.</p></div>"],"vi":"Marcus Steuber [10:41 sáng]: Chúng ta vẫn định tổ chức buổi họp trực tuyến với tác giả hôm nay chứ? Tôi vẫn chưa nhận được lời mời họp.\n\nBrinda Rajan [10:42 sáng]: Tôi có cuộc họp đó trong lịch của mình. Để tôi chuyển tiếp cho anh; có vẻ như trợ lý biên tập của chúng ta đã không thêm anh vào.\n\nMarcus Steuber [10:43 sáng]: Cảm ơn, tôi vừa nhận được rồi. Nhưng thời gian đó không phù hợp với tôi. Tôi có cuộc hẹn với Hazel Luong để bàn về các vấn đề in ấn ở nhà máy Singapore của chúng ta.\n\nBrinda Rajan [10:44 sáng]: Anh có thể dời cuộc hẹn đó không? Tác giả mới mà chúng ta đang hợp tác thực sự cần anh hướng dẫn về thiết kế và định dạng cuối cùng của cuốn sách. Anh là biên tập viên sản xuất am hiểu nhất của chúng ta.\n\nMarcus Steuber [10:45 sáng]: Để tôi hỏi ý kiến cấp trên. Tôi sẽ thêm ông Borg vào cuộc trò chuyện.\n\nJoshua Borg [10:47 sáng]: Chào cả nhóm. Marcus, anh nên ưu tiên cuộc hẹn với Hazel. Tuần sau tôi sẽ đến thăm nhà máy, và chúng ta cần có vài giải pháp khả thi trước lúc đó.\n\nBrinda Rajan [10:48 sáng]: Được, vậy tôi sẽ liên hệ với cô Benoit để xem cô ấy có thể họp vào cuối ngày không.\n\nMarcus Steuber [10:48 sáng]: Vậy thì được. Tôi rảnh từ 4 đến 6 giờ chiều.","qs":[{"n":172,"q":"Why does Mr. Steuber write to Ms. Rajan?","qvi":"Tại sao ông Steuber nhắn tin cho cô Rajan?","opts":["To invite her to a professional event","To check on the status of a meeting","To make travel plans for a business trip","To ask about an assistant's performance"],"ans":"B","xp":"Câu hỏi mục đích. Bằng chứng: tin nhắn đầu tiên \"Are we still planning to have the author video conference today? I haven't yet received a meeting invitation.\" (cuộc họp trực tuyến với tác giả hôm nay vẫn diễn ra chứ?) → ông hỏi tình trạng của cuộc họp → chọn (B). (D) sai: cô Rajan có nhắc trợ lý biên tập nhưng ông Steuber không hỏi về năng lực của trợ lý.\n(A) Để mời cô ấy tham dự một sự kiện chuyên môn\n(B) Để kiểm tra tình trạng của một cuộc họp\n(C) Để lên kế hoạch cho một chuyến công tác\n(D) Để hỏi về năng lực làm việc của một trợ lý"},{"n":173,"q":"At 10:45 a.m., what does Mr. Steuber most likely mean when he writes, \"Let me check with my supervisor\"?","qvi":"Lúc 10:45 sáng, khi ông Steuber viết \"Để tôi hỏi ý kiến cấp trên\", nhiều khả năng ông ấy có ý gì?","opts":["He needs final approval on a book design.","He would like advice on changing an appointment.","He requires access to the corporate calendar.","He is uncertain how to add team members to the chat."],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó cô Rajan hỏi \"Could you postpone that?\" (anh có thể dời cuộc hẹn với Hazel Luong không?). Ông Steuber trả lời \"Let me check with my supervisor\" → ông muốn hỏi ý kiến cấp trên xem có nên dời cuộc hẹn hay không. Sau đó ông Borg khuyên \"you should prioritize your appointment with Hazel\" → chọn (B).\n(A) Ông ấy cần sự phê duyệt cuối cùng cho thiết kế cuốn sách.\n(B) Ông ấy muốn xin lời khuyên về việc thay đổi một cuộc hẹn.\n(C) Ông ấy cần quyền truy cập lịch của công ty.\n(D) Ông ấy không chắc cách thêm thành viên vào cuộc trò chuyện."},{"n":174,"q":"Who most likely is Ms. Benoit?","qvi":"Cô Benoit nhiều khả năng là ai?","opts":["A writer","A designer","A production editor","A printing plant supervisor"],"ans":"A","xp":"Câu hỏi suy luận. Cuộc họp bị trùng lịch là \"the author video conference\" (họp trực tuyến với tác giả), và \"The new author we're working with really needs your guidance\". Khi ông Steuber phải ưu tiên cuộc hẹn với Hazel, cô Rajan viết \"I'll contact Ms. Benoit to find out if she can meet later in the day\" → người cần dời giờ họp chính là tác giả mới → cô Benoit là tác giả (writer) → chọn (A). (C) sai: biên tập viên sản xuất là ông Steuber. (D) không có cơ sở; người liên quan đến nhà máy in là Hazel Luong.\n(A) Một nhà văn / tác giả\n(B) Một nhà thiết kế\n(C) Một biên tập viên sản xuất\n(D) Một giám sát viên nhà máy in"},{"n":175,"q":"What will Ms. Rajan probably do next?","qvi":"Cô Rajan có lẽ sẽ làm gì tiếp theo?","opts":["Suggest solutions to a printing issue","Arrange to visit the Singapore plant","Attend a meeting with Ms. Luong","Reschedule a video conference"],"ans":"D","xp":"Câu hỏi suy luận (việc làm tiếp theo). Bằng chứng: \"I'll contact Ms. Benoit to find out if she can meet later in the day\" và ông Steuber đáp \"That would work. I'm free between 4 and 6 P.M.\" → cô Rajan sẽ sắp xếp lại giờ cho buổi họp trực tuyến với tác giả → chọn (D). (A), (C) là việc của ông Steuber; (B) là việc của ông Borg (\"I'll be visiting the plant next week\").\n(A) Đề xuất giải pháp cho một vấn đề in ấn\n(B) Sắp xếp chuyến thăm nhà máy ở Singapore\n(C) Tham dự cuộc họp với cô Luong\n(D) Dời lịch một buổi họp trực tuyến"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following schedule and text message.","passages":["<h3>Rambling River Festival</h3><h4>Schedule of Musical Events</h4><p><b><u>Friday, September 8</u></b></p><table><tr><td>• 3:30 P.M.</td><td>Johanna Greenblatt</td></tr><tr><td>• 8:00 P.M.</td><td>Bethesda Radio Show featuring the Blass Brothers Band<br>(to be recorded at the Bramley Theater)</td></tr></table><p><b><u>Saturday, September 9</u></b></p><table><tr><td>• 6:30 P.M.</td><td>The Rolling Dozen</td></tr><tr><td>• 7:45 P.M.</td><td>Jefferson Cage</td></tr></table><p>All events take place at the Bethesda Park Open-Air Stage unless otherwise noted. Feel free to bring picnic blankets.</p>","<div class=\"msg\"><p><b>From Rambling River Festival, Sep 8, 9:14 A.M.</b></p><p>This afternoon’s performance will take place in Cole Hall in anticipation of inclement weather. Bulky items are not allowed, but coat-check service will be available.</p><p>This evening’s performance is being pushed to 2:30 P.M. tomorrow; local band Kirschau will perform during the original time slot instead.</p><p>We expect our full Saturday program to take place at the Bethesda Park Open-Air Stage.</p></div>"],"vi":"Lễ hội Rambling River\nLịch các sự kiện âm nhạc\n\nThứ Sáu, ngày 8 tháng 9\n• 3:30 chiều: Johanna Greenblatt\n• 8:00 tối: Chương trình Bethesda Radio Show với sự góp mặt của ban nhạc Blass Brothers (sẽ được thu âm tại Nhà hát Bramley)\n\nThứ Bảy, ngày 9 tháng 9\n• 6:30 chiều: The Rolling Dozen\n• 7:45 tối: Jefferson Cage\n\nTất cả sự kiện diễn ra tại Sân khấu ngoài trời Công viên Bethesda trừ khi có ghi chú khác. Bạn cứ thoải mái mang theo thảm dã ngoại.\n\n---\n\nTin nhắn từ Lễ hội Rambling River, 8/9, 9:14 sáng\n\nBuổi biểu diễn chiều nay sẽ diễn ra tại Hội trường Cole do dự báo thời tiết xấu. Không được mang đồ cồng kềnh vào, nhưng sẽ có dịch vụ gửi áo khoác.\n\nBuổi biểu diễn tối nay được dời sang 2:30 chiều mai; thay vào đó, ban nhạc địa phương Kirschau sẽ biểu diễn vào khung giờ ban đầu.\n\nChúng tôi dự kiến toàn bộ chương trình thứ Bảy sẽ diễn ra tại Sân khấu ngoài trời Công viên Bethesda.","qs":[{"n":176,"q":"Who was originally scheduled to perform at the Bramley Theater?","qvi":"Ban đầu ai được lên lịch biểu diễn tại Nhà hát Bramley?","opts":["Johanna Greenblatt","The Blass Brothers Band","The Rolling Dozen","Jefferson Cage"],"ans":"B","xp":"Câu hỏi chi tiết. Lịch trình ghi: \"8:00 P.M. Bethesda Radio Show featuring the Blass Brothers Band (to be recorded at the Bramley Theater)\" → chương trình có ban nhạc Blass Brothers được thu âm tại Nhà hát Bramley → chọn (B). Các nghệ sĩ còn lại biểu diễn ở Sân khấu ngoài trời (địa điểm mặc định).\n(A) Johanna Greenblatt\n(B) Ban nhạc Blass Brothers\n(C) The Rolling Dozen\n(D) Jefferson Cage"},{"n":177,"q":"What does the schedule suggest about the Rambling River Festival?","qvi":"Lịch trình gợi ý điều gì về Lễ hội Rambling River?","opts":["It takes place annually.","It requires a ticket for entry.","It features local food vendors.","It is mainly an outdoor event."],"ans":"D","xp":"Câu hỏi suy luận. Lịch ghi: \"All events take place at the Bethesda Park Open-Air Stage unless otherwise noted. Feel free to bring picnic blankets.\" → hầu hết sự kiện diễn ra ở sân khấu ngoài trời (open-air), lại được mang thảm dã ngoại → lễ hội chủ yếu là sự kiện ngoài trời → chọn (D). Lịch không nhắc đến việc tổ chức hằng năm, vé vào cửa hay quầy đồ ăn.\n(A) Nó được tổ chức hằng năm.\n(B) Nó yêu cầu vé để vào cửa.\n(C) Nó có các quầy bán đồ ăn địa phương.\n(D) Nó chủ yếu là sự kiện ngoài trời."},{"n":178,"q":"According to the text message, what can audience members do at Cole Hall?","qvi":"Theo tin nhắn, khán giả có thể làm gì tại Hội trường Cole?","opts":["Check coats","Store bulky items","Buy concert tickets","Pick up a schedule of events"],"ans":"A","xp":"Câu hỏi chi tiết. Tin nhắn: \"This afternoon's performance will take place in Cole Hall ... Bulky items are not allowed, but coat-check service will be available.\" → có dịch vụ gửi áo khoác (coat-check) → \"Check coats\" → chọn (A). (B) sai vì đồ cồng kềnh không được phép mang vào.\n(A) Gửi áo khoác\n(B) Cất giữ đồ cồng kềnh\n(C) Mua vé buổi hòa nhạc\n(D) Lấy lịch các sự kiện"},{"n":179,"q":"In the text message, the word “pushed” in paragraph 2, line 1, is closest in meaning to","qvi":"Trong tin nhắn, từ “pushed” ở đoạn 2, dòng 1 gần nghĩa nhất với","opts":["moved","extended","managed","pressured"],"ans":"A","xp":"Câu hỏi đồng nghĩa. \"This evening's performance is being pushed to 2:30 P.M. tomorrow\" → buổi diễn tối nay bị dời sang 2:30 chiều mai. \"push to + thời gian\" = dời lịch, chuyển sang → \"moved\" → chọn (A). \"pressured\" là nghĩa \"gây áp lực\" của push, không hợp ngữ cảnh.\n(A) được dời/chuyển\n(B) được kéo dài\n(C) được quản lý\n(D) bị gây áp lực"},{"n":180,"q":"When will Kirschau perform?","qvi":"Khi nào Kirschau sẽ biểu diễn?","opts":["At 3:30 P.M. on Friday","At 8:00 P.M. on Friday","At 2:30 P.M. on Saturday","At 6:30 P.M. on Saturday"],"ans":"B","xp":"Câu hỏi kết hợp 2 văn bản. Tin nhắn (gửi thứ Sáu 8/9): \"This evening's performance is being pushed to 2:30 P.M. tomorrow; local band Kirschau will perform during the original time slot instead.\" → Kirschau diễn vào khung giờ ban đầu của buổi diễn tối thứ Sáu. Theo lịch, buổi tối thứ Sáu là \"8:00 P.M.\" → Kirschau diễn lúc 8 giờ tối thứ Sáu → chọn (B). (C) 2:30 chiều thứ Bảy là giờ mới của chương trình Bethesda Radio Show, không phải của Kirschau.\n(A) Lúc 3:30 chiều thứ Sáu\n(B) Lúc 8:00 tối thứ Sáu\n(C) Lúc 2:30 chiều thứ Bảy\n(D) Lúc 6:30 chiều thứ Bảy"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following e-mail and article.","passages":["<div class=\"hdr\"><p><b>To:</b> All Branch Managers</p><p><b>From:</b> Fran Corliss</p><p><b>Subject:</b> Survey results on mobile banking</p><p><b>Date:</b> April 7</p></div><p>Hello all,</p><p>Ogden Bank recently conducted a survey of its customers concerning mobile banking. Here are some key takeaways.</p><p>Over 95 percent of our customers own a mobile device. However, although interest in mobile banking is high, only 39 percent of our customers use our application. Some customers cite security concerns (23 percent), but a majority (78 percent) say that they simply do not think the app works well.</p><p>A mandatory meeting for all branch managers will be held at our headquarters on April 12 at 4:00 P.M. to brainstorm strategies for responding to this challenge.</p><p>Best,</p><p>Fran Corliss<br>Director of Mobile Banking, Ogden Bank</p>","<h3>Boost for Mobile Banking</h3><p>By Edward Panzius</p><p>FLEMINGTON (May 25)—Ogden Bank has rolled out major improvements to its mobile banking application. It has expanded the variety of tasks that can be accomplished through the app and made it much easier to use.</p><p>“Many of our account holders have been frustrated in the past by a clunky, limited app,” said Alys DeFreese, manager of the Flemington branch of Ogden Bank. “They can now do just about any task with the app that they could over the phone or by visiting a branch in person. This is just another example of how we support our customers in any way we can.”</p><p>According to Ms. DeFreese, in the few weeks since the upgrade, 20 percent of account holders have switched to depositing checks and paying bills online. She anticipates that number will rise as more customers learn about the easy-to-use app.</p><p>“The convenience made a big difference for me,” said account holder Yair Baum. Another customer, Maria Reed, added, “I appreciate the flexibility of being able to do my banking whenever and wherever I want.”</p>"],"vi":"Gửi: Tất cả quản lý chi nhánh\nTừ: Fran Corliss\nTiêu đề: Kết quả khảo sát về ngân hàng di động\nNgày: 7 tháng 4\n\nXin chào mọi người,\n\nNgân hàng Ogden gần đây đã tiến hành một cuộc khảo sát khách hàng về dịch vụ ngân hàng di động. Dưới đây là một số điểm chính.\n\nHơn 95% khách hàng của chúng ta sở hữu thiết bị di động. Tuy nhiên, mặc dù mức độ quan tâm đến ngân hàng di động cao, chỉ 39% khách hàng sử dụng ứng dụng của chúng ta. Một số khách hàng nêu lo ngại về bảo mật (23%), nhưng phần lớn (78%) nói rằng họ đơn giản là thấy ứng dụng hoạt động không tốt.\n\nMột cuộc họp bắt buộc dành cho tất cả quản lý chi nhánh sẽ được tổ chức tại trụ sở chính vào ngày 12 tháng 4 lúc 4:00 chiều để cùng đưa ra các chiến lược ứng phó với thách thức này.\n\nTrân trọng,\nFran Corliss\nGiám đốc Ngân hàng Di động, Ngân hàng Ogden\n\n---\n\nCú hích cho ngân hàng di động\nTác giả: Edward Panzius\n\nFLEMINGTON (25/5) — Ngân hàng Ogden vừa tung ra những cải tiến lớn cho ứng dụng ngân hàng di động của mình. Ngân hàng đã mở rộng các loại giao dịch có thể thực hiện qua ứng dụng và làm cho nó dễ dùng hơn nhiều.\n\n“Trước đây, nhiều chủ tài khoản của chúng tôi đã bực bội vì một ứng dụng cồng kềnh, hạn chế,” bà Alys DeFreese, quản lý chi nhánh Flemington của Ngân hàng Ogden, cho biết. “Giờ đây họ có thể làm gần như mọi việc bằng ứng dụng mà trước đây họ làm qua điện thoại hoặc đến trực tiếp chi nhánh. Đây chỉ là một ví dụ nữa cho thấy chúng tôi hỗ trợ khách hàng bằng mọi cách có thể.”\n\nTheo bà DeFreese, trong vài tuần kể từ khi nâng cấp, 20% chủ tài khoản đã chuyển sang gửi séc và thanh toán hóa đơn trực tuyến. Bà dự đoán con số đó sẽ tăng khi ngày càng nhiều khách hàng biết đến ứng dụng dễ sử dụng này.\n\n“Sự tiện lợi đã tạo ra khác biệt lớn đối với tôi,” chủ tài khoản Yair Baum nói. Một khách hàng khác, Maria Reed, nói thêm: “Tôi đánh giá cao sự linh hoạt khi có thể giao dịch ngân hàng bất cứ lúc nào và ở bất cứ đâu tôi muốn.”","qs":[{"n":181,"q":"What is one purpose of the e-mail?","qvi":"Một mục đích của e-mail là gì?","opts":["To provide details on a new privacy policy","To propose a survey of banking habits","To ask bank staff to test a mobile app","To inform managers of a company problem"],"ans":"D","xp":"Câu hỏi mục đích. E-mail gửi \"All Branch Managers\", báo kết quả khảo sát: \"only 39 percent of our customers use our application ... a majority (78 percent) say that they simply do not think the app works well\", rồi mời họp \"to brainstorm strategies for responding to this challenge\" → thông báo cho các quản lý về một vấn đề của công ty (ứng dụng ít người dùng, bị chê) → chọn (D). (B) sai: khảo sát đã được thực hiện rồi, không phải đề xuất.\n(A) Cung cấp chi tiết về chính sách bảo mật mới\n(B) Đề xuất một cuộc khảo sát về thói quen giao dịch ngân hàng\n(C) Yêu cầu nhân viên ngân hàng thử nghiệm ứng dụng di động\n(D) Thông báo cho các quản lý về một vấn đề của công ty"},{"n":182,"q":"According to the e-mail, what percentage of the bank's customers use the mobile app?","qvi":"Theo e-mail, bao nhiêu phần trăm khách hàng của ngân hàng sử dụng ứng dụng di động?","opts":["23 percent","39 percent","78 percent","95 percent"],"ans":"B","xp":"Câu hỏi chi tiết. \"only 39 percent of our customers use our application\" → chọn (B). 23% là số khách lo ngại bảo mật, 78% là số khách cho rằng ứng dụng không tốt, 95% là số khách có thiết bị di động.\n(A) 23%\n(B) 39%\n(C) 78%\n(D) 95%"},{"n":183,"q":"In the article, the word “anticipates” in paragraph 3, line 5, is closest in meaning to","qvi":"Trong bài báo, từ “anticipates” ở đoạn 3, dòng 5 gần nghĩa nhất với","opts":["considers","waits for","prepares for","expects"],"ans":"D","xp":"Câu hỏi đồng nghĩa. \"She anticipates that number will rise as more customers learn about the easy-to-use app.\" → bà ấy dự đoán/kỳ vọng con số đó sẽ tăng. \"anticipate that + mệnh đề\" = dự đoán, mong đợi → \"expects\" → chọn (D). \"prepares for\" (chuẩn bị cho) là nghĩa khác của anticipate nhưng không đi với mệnh đề \"that...\".\n(A) cân nhắc\n(B) chờ đợi\n(C) chuẩn bị cho\n(D) dự đoán, mong đợi"},{"n":184,"q":"Who most likely attended a meeting at Ogden Bank headquarters on April 12?","qvi":"Ai có khả năng cao nhất đã tham dự cuộc họp tại trụ sở Ngân hàng Ogden vào ngày 12 tháng 4?","opts":["Mr. Panzius","Ms. DeFreese","Mr. Baum","Ms. Reed"],"ans":"B","xp":"Câu hỏi kết hợp 2 văn bản (suy luận). E-mail: \"A mandatory meeting for all branch managers will be held at our headquarters on April 12\" → cuộc họp bắt buộc cho tất cả quản lý chi nhánh. Bài báo: \"Alys DeFreese, manager of the Flemington branch of Ogden Bank\" → bà DeFreese là quản lý chi nhánh → bà đã tham dự → chọn (B). Ông Panzius là tác giả bài báo, ông Baum và bà Reed là khách hàng.\n(A) Ông Panzius\n(B) Bà DeFreese\n(C) Ông Baum\n(D) Bà Reed"},{"n":185,"q":"What is suggested about Ogden Bank's management?","qvi":"Điều gì được gợi ý về ban quản lý của Ngân hàng Ogden?","opts":["It prefers that account holders do their banking in person.","It is considering offering free checking to new account holders.","It is in the process of hiring more staff.","It prioritizes improvements in customer experience."],"ans":"D","xp":"Câu hỏi suy luận. Sau khi khảo sát cho thấy khách chê ứng dụng, ngân hàng tổ chức họp tìm giải pháp và đã \"rolled out major improvements to its mobile banking application ... made it much easier to use\"; bà DeFreese nói: \"This is just another example of how we support our customers in any way we can.\" → ban quản lý ưu tiên cải thiện trải nghiệm khách hàng → chọn (D). (A) sai vì ngân hàng khuyến khích dùng ứng dụng; (B), (C) không được nhắc đến.\n(A) Họ muốn chủ tài khoản giao dịch trực tiếp tại quầy.\n(B) Họ đang cân nhắc cung cấp tài khoản séc miễn phí cho chủ tài khoản mới.\n(C) Họ đang trong quá trình tuyển thêm nhân viên.\n(D) Họ ưu tiên cải thiện trải nghiệm khách hàng."}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following notice, Web page, and e-mail.","passages":["<h3>Attention, Library Members</h3><p>The Westwood Library is excited to announce the start of a book club, which is open to all library members. The club will meet on the last Thursday of each month, from 7:00 to 9:00 P.M. in the Harrison Meeting Room, to discuss a book chosen by one of our professional staff. From January to June, we will read recently published nonfiction works, and from July to December, we will focus on contemporary fiction titles. For more information, visit www.westwoodlibrary.org or speak with the staff at the circulation desk.</p>","<p><b>https://www.westwoodlibrary.org/bookclub</b></p><p>We hope you will join us for the book club on the last Thursday of each month at 7:00 P.M.! Below are the titles selected for the first half of the year.</p><table><tr><td>January:</td><td><i>Wild Open Range</i> by Jaxon McDonald</td></tr><tr><td>February:</td><td><i>The Journey of a Song</i> by Lucy Xi</td></tr><tr><td>March:</td><td><i>Due North: Adventures in Alaska’s Northern Territory</i> by Isabel Beck</td></tr><tr><td>April:</td><td><i>The Art of Mindful Carpentry</i> by Peter Landers</td></tr><tr><td>May:</td><td><i>Mary Swan: A Legend Before Her Time</i> by Kai Noble</td></tr><tr><td>June:</td><td>To Be Announced</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> Lisa Calle &lt;lcalle@worldmail.com&gt;</p><p><b>From:</b> Gail Frey &lt;gfrey@mymail.com&gt;</p><p><b>Date:</b> March 27</p><p><b>Subject:</b> Book club</p></div><p>Dear Ms. Calle,</p><p>It was delightful to see you leading the book club yesterday evening. Ms. Beck’s <i>Due North</i> is lengthy, and it was a challenge to finish it before the meeting. However, I have to thank you for choosing that book because it revived my childhood interest in traveling to Alaska. In fact, I’ve already looked up some tours!</p><p>The club meeting was packed, and I hardly got to talk to you. We should catch up sometime soon. Perhaps we might try the new French restaurant on Looper Street. I hear it is amazing and reasonably priced.</p><p>Sincerely,</p><p>Gail Frey</p>"],"vi":"Thông báo đến các thành viên thư viện\n\nThư viện Westwood vui mừng thông báo khai mạc một câu lạc bộ sách, mở cửa cho tất cả thành viên thư viện. Câu lạc bộ sẽ họp vào thứ Năm cuối cùng của mỗi tháng, từ 7:00 đến 9:00 tối tại Phòng họp Harrison, để thảo luận về một cuốn sách do một trong các nhân viên chuyên môn của chúng tôi lựa chọn. Từ tháng 1 đến tháng 6, chúng ta sẽ đọc các tác phẩm phi hư cấu mới xuất bản, và từ tháng 7 đến tháng 12, chúng ta sẽ tập trung vào các tác phẩm hư cấu đương đại. Để biết thêm thông tin, hãy truy cập www.westwoodlibrary.org hoặc trao đổi với nhân viên tại quầy mượn trả sách.\n\n---\n\nhttps://www.westwoodlibrary.org/bookclub\n\nChúng tôi mong bạn sẽ tham gia câu lạc bộ sách vào thứ Năm cuối cùng của mỗi tháng lúc 7:00 tối! Dưới đây là các đầu sách được chọn cho nửa đầu năm.\n\nTháng 1: Wild Open Range (Vùng đồng cỏ hoang dã) của Jaxon McDonald\nTháng 2: The Journey of a Song (Hành trình của một bài hát) của Lucy Xi\nTháng 3: Due North: Adventures in Alaska's Northern Territory (Thẳng hướng Bắc: Phiêu lưu ở vùng lãnh thổ phía Bắc Alaska) của Isabel Beck\nTháng 4: The Art of Mindful Carpentry (Nghệ thuật làm mộc chánh niệm) của Peter Landers\nTháng 5: Mary Swan: A Legend Before Her Time (Mary Swan: Huyền thoại đi trước thời đại) của Kai Noble\nTháng 6: Sẽ thông báo sau\n\n---\n\nGửi: Lisa Calle <lcalle@worldmail.com>\nTừ: Gail Frey <gfrey@mymail.com>\nNgày: 27 tháng 3\nTiêu đề: Câu lạc bộ sách\n\nChị Calle thân mến,\n\nThật vui khi thấy chị dẫn dắt buổi câu lạc bộ sách tối hôm qua. Cuốn Due North của bà Beck khá dài, và thật là một thử thách để đọc xong trước buổi họp. Tuy nhiên, tôi phải cảm ơn chị đã chọn cuốn sách đó vì nó đã khơi lại niềm yêu thích du lịch Alaska từ thời thơ ấu của tôi. Thật ra, tôi đã tìm hiểu một vài tour rồi!\n\nBuổi họp câu lạc bộ rất đông, và tôi gần như không có dịp nói chuyện với chị. Chúng ta nên gặp nhau trò chuyện sớm. Có lẽ chúng ta có thể thử nhà hàng Pháp mới trên phố Looper. Tôi nghe nói nó rất tuyệt và giá cả hợp lý.\n\nTrân trọng,\nGail Frey","qs":[{"n":186,"q":"What is the purpose of the notice?","qvi":"Mục đích của thông báo là gì?","opts":["To highlight some books in the library","To announce a change in library hours","To promote an activity at the library","To introduce a new librarian"],"ans":"C","xp":"Câu hỏi mục đích. Thông báo: \"The Westwood Library is excited to announce the start of a book club, which is open to all library members.\" → giới thiệu, quảng bá câu lạc bộ sách (một hoạt động) tại thư viện → chọn (C). book club → paraphrase thành \"an activity\".\n(A) Giới thiệu nổi bật một số cuốn sách trong thư viện\n(B) Thông báo thay đổi giờ mở cửa thư viện\n(C) Quảng bá một hoạt động tại thư viện\n(D) Giới thiệu một thủ thư mới"},{"n":187,"q":"What is suggested about the book Wild Open Range?","qvi":"Điều gì được gợi ý về cuốn sách Wild Open Range?","opts":["It is a best-selling title.","It is a work of nonfiction.","It was published ten years ago.","It is available at a discount for library members."],"ans":"B","xp":"Câu hỏi kết hợp 2 văn bản. Thông báo: \"From January to June, we will read recently published nonfiction works\" → tháng 1–6 đọc sách phi hư cấu mới xuất bản. Trang web: \"January: Wild Open Range by Jaxon McDonald\" → sách của tháng 1 → là tác phẩm phi hư cấu → chọn (B). (C) sai vì sách là \"recently published\" (mới xuất bản).\n(A) Đó là một đầu sách bán chạy.\n(B) Đó là một tác phẩm phi hư cấu.\n(C) Nó được xuất bản cách đây mười năm.\n(D) Thành viên thư viện được mua giảm giá."},{"n":188,"q":"What author most likely wrote about a famous person?","qvi":"Tác giả nào có khả năng cao nhất đã viết về một người nổi tiếng?","opts":["Jaxon McDonald","Lucy Xi","Peter Landers","Kai Noble"],"ans":"D","xp":"Câu hỏi suy luận. Trang web: \"May: Mary Swan: A Legend Before Her Time by Kai Noble\" → tiêu đề nói về một người tên Mary Swan, được gọi là \"a legend\" (huyền thoại) → sách viết về một nhân vật nổi tiếng → tác giả Kai Noble → chọn (D). Các sách khác nói về đồng cỏ, bài hát, nghề mộc.\n(A) Jaxon McDonald\n(B) Lucy Xi\n(C) Peter Landers\n(D) Kai Noble"},{"n":189,"q":"What can be concluded about Ms. Calle?","qvi":"Có thể kết luận gì về bà Calle?","opts":["She is a library staff member.","She has written book reviews.","She is Ms. Frey's supervisor.","She favors historical fiction."],"ans":"A","xp":"Câu hỏi kết hợp 2 văn bản (suy luận). E-mail của bà Frey: \"It was delightful to see you leading the book club ... I have to thank you for choosing that book\" → bà Calle dẫn dắt câu lạc bộ và đã chọn sách. Thông báo: \"to discuss a book chosen by one of our professional staff\" → sách do nhân viên chuyên môn của thư viện chọn → bà Calle là nhân viên thư viện → chọn (A).\n(A) Bà ấy là nhân viên thư viện.\n(B) Bà ấy đã viết các bài điểm sách.\n(C) Bà ấy là cấp trên của bà Frey.\n(D) Bà ấy thích tiểu thuyết lịch sử."},{"n":190,"q":"What does Ms. Frey indicate about the book she read?","qvi":"Bà Frey cho biết điều gì về cuốn sách bà đã đọc?","opts":["It discussed a topic that was unfamiliar to her.","It had parts that she thought were inaccurate.","It was easy to read in the time available.","It inspired her to explore an old interest."],"ans":"D","xp":"Câu hỏi chi tiết. \"it revived my childhood interest in traveling to Alaska. In fact, I've already looked up some tours!\" → cuốn sách khơi lại niềm yêu thích từ thời thơ ấu (old interest) và bà đã đi tìm hiểu tour (explore) → chọn (D). (C) sai vì bà nói \"it was a challenge to finish it before the meeting\" (khó đọc xong kịp).\n(A) Nó bàn về một chủ đề xa lạ với bà.\n(B) Nó có những phần bà cho là không chính xác.\n(C) Nó dễ đọc xong trong khoảng thời gian có được.\n(D) Nó truyền cảm hứng để bà khám phá lại một sở thích cũ."}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following e-mails and receipt.","passages":["<div class=\"hdr\"><p><b>From:</b> Tatiana Schwartz &lt;orders@georgestreetsweets.co.uk&gt;</p><p><b>To:</b> Alejandro Ordaz &lt;aordaz@brooksidestationery.co.uk&gt;</p><p><b>Date:</b> 28 April</p><p><b>Subject:</b> Confirmation of order number 47892</p><p><b>Attachment:</b> Order receipt</p></div><p>Dear Mr. Ordaz,</p><p>Thank you for placing an order with George Street Sweets. This e-mail is to confirm that we have received your request. Your receipt has been attached to this e-mail.</p><p>If you have any questions or need to make any changes to your order, please reply to this message or phone us at (091) 498 0172. Note that we are unable to accommodate order changes that are submitted less than 48 hours before your scheduled pickup time.</p><p>If picking up your order, we are located at 29 George Street. Parking is available next door, directly behind Spike’s Cycle Shop. We offer delivery to customers within 10 kilometres of our shop for a fee of £2.50. Please note that cancellations within 24 hours of your pickup or delivery time will not be refunded.</p><p>Sincerely,</p><p>Tatiana Schwartz</p>","<h3>George Street Sweets</h3><p><b>Order:</b> 47892<br><b>Date of Order:</b> 28 April<br><b>Pickup Date and Time:</b> N/A<br><b>Delivery Date and Time:</b> 2 May, 11:30 A.M.<br><b>Delivery Location:</b> 2 Spen Lane, Business Suite 202<br><b>Payment Method:</b> Credit Card—Alejandro Ordaz</p><p><b>Customisation Instructions:</b> None</p><table><tr><th>Item</th><th>Cost</th></tr><tr><td>18-inch round cake (chocolate with vanilla icing)</td><td>£32.00</td></tr><tr><td>1 set of candles</td><td>£5.00</td></tr><tr><td>Delivery</td><td>£2.50</td></tr><tr><td><b>Total</b></td><td><b>£39.50</b></td></tr></table>","<div class=\"hdr\"><p><b>From:</b> Alejandro Ordaz &lt;aordaz@brooksidestationery.co.uk&gt;</p><p><b>To:</b> Tatiana Schwartz &lt;orders@georgestreetsweets.co.uk&gt;</p><p><b>Date:</b> 29 April</p><p><b>Subject:</b> RE: Confirmation of order number 47892</p></div><p>Dear Ms. Schwartz,</p><p>I received my order confirmation e-mail and receipt, and I noticed an error. It seems that the person to whom I spoke on the phone while placing my order did not copy down the message I requested. The customisation I specified was that “Happy Retirement” be written on top.</p><p>I hope it will still be possible to include this message despite the timing. Please respond to this e-mail to confirm. Also, there will be more guests than I originally expected, so I might contact your business again to place an additional order.</p><p>Best,</p><p>Alejandro Ordaz</p>"],"vi":"Từ: Tatiana Schwartz <orders@georgestreetsweets.co.uk>\nGửi: Alejandro Ordaz <aordaz@brooksidestationery.co.uk>\nNgày: 28 tháng 4\nTiêu đề: Xác nhận đơn hàng số 47892\nTệp đính kèm: Biên lai đơn hàng\n\nKính gửi ông Ordaz,\n\nCảm ơn ông đã đặt hàng tại George Street Sweets. E-mail này để xác nhận rằng chúng tôi đã nhận được yêu cầu của ông. Biên lai của ông được đính kèm trong e-mail này.\n\nNếu ông có bất kỳ câu hỏi nào hoặc cần thay đổi đơn hàng, vui lòng trả lời thư này hoặc gọi cho chúng tôi theo số (091) 498 0172. Xin lưu ý rằng chúng tôi không thể đáp ứng các yêu cầu thay đổi đơn hàng được gửi trước giờ nhận hàng đã hẹn chưa đầy 48 tiếng.\n\nNếu tự đến lấy hàng, cửa hàng chúng tôi ở số 29 phố George. Có chỗ đậu xe ngay bên cạnh, phía sau Cửa hàng xe đạp Spike's. Chúng tôi giao hàng cho khách trong phạm vi 10 km tính từ cửa hàng với phí 2,50 bảng. Xin lưu ý rằng các trường hợp hủy đơn trong vòng 24 tiếng trước giờ nhận hoặc giao hàng sẽ không được hoàn tiền.\n\nTrân trọng,\nTatiana Schwartz\n\n---\n\nGeorge Street Sweets\n\nĐơn hàng: 47892\nNgày đặt: 28 tháng 4\nNgày và giờ nhận tại cửa hàng: Không áp dụng\nNgày và giờ giao: 2 tháng 5, 11:30 sáng\nĐịa điểm giao: 2 Spen Lane, Phòng 202 tòa văn phòng\nPhương thức thanh toán: Thẻ tín dụng — Alejandro Ordaz\n\nYêu cầu tùy chỉnh: Không có\n\nMặt hàng — Giá\nBánh tròn 18 inch (sô-cô-la phủ kem vani) — 32,00 bảng\n1 bộ nến — 5,00 bảng\nPhí giao hàng — 2,50 bảng\nTổng cộng — 39,50 bảng\n\n---\n\nTừ: Alejandro Ordaz <aordaz@brooksidestationery.co.uk>\nGửi: Tatiana Schwartz <orders@georgestreetsweets.co.uk>\nNgày: 29 tháng 4\nTiêu đề: RE: Xác nhận đơn hàng số 47892\n\nKính gửi bà Schwartz,\n\nTôi đã nhận được e-mail xác nhận đơn hàng và biên lai, và tôi phát hiện một lỗi. Có vẻ như người mà tôi nói chuyện qua điện thoại khi đặt hàng đã không ghi lại dòng chữ tôi yêu cầu. Yêu cầu tùy chỉnh của tôi là viết dòng chữ “Happy Retirement” (Chúc mừng nghỉ hưu) lên mặt bánh.\n\nTôi hy vọng vẫn có thể thêm dòng chữ này dù thời gian đã gấp. Vui lòng trả lời e-mail này để xác nhận. Ngoài ra, sẽ có nhiều khách hơn tôi dự kiến ban đầu, nên có thể tôi sẽ liên hệ lại với cửa hàng để đặt thêm hàng.\n\nTrân trọng,\nAlejandro Ordaz","qs":[{"n":191,"q":"What is a policy of George Street Sweets?","qvi":"Một chính sách của George Street Sweets là gì?","opts":["Orders cannot be changed.","Orders placed less than 48 hours before pickup incur an extra fee.","Orders must be paid for when they are placed.","Orders cannot be refunded within 24 hours of pickup."],"ans":"D","xp":"Câu hỏi chi tiết. E-mail 1: \"Please note that cancellations within 24 hours of your pickup or delivery time will not be refunded.\" → hủy trong vòng 24 tiếng trước giờ nhận hàng sẽ không được hoàn tiền → chọn (D). (A) sai: đơn vẫn đổi được nếu báo trước hơn 48 tiếng. (B) sai: quy định 48 tiếng nói về việc thay đổi đơn, không phải phụ phí. (C) không được nhắc đến.\n(A) Đơn hàng không thể thay đổi.\n(B) Đơn đặt trước giờ nhận chưa đầy 48 tiếng sẽ bị tính thêm phí.\n(C) Đơn hàng phải được thanh toán ngay khi đặt.\n(D) Đơn hàng không được hoàn tiền trong vòng 24 tiếng trước giờ nhận."},{"n":192,"q":"What is suggested about the building at 2 Spen Lane?","qvi":"Điều gì được gợi ý về tòa nhà ở số 2 Spen Lane?","opts":["It has parking spaces behind a bicycle shop.","It is located within 10 kilometers of George Street Sweets.","It is a residential apartment building.","It is owned by Ms. Schwartz."],"ans":"B","xp":"Câu hỏi kết hợp 2 văn bản (suy luận). E-mail 1: \"We offer delivery to customers within 10 kilometres of our shop\" → chỉ giao hàng trong phạm vi 10 km. Biên lai: \"Delivery Location: 2 Spen Lane, Business Suite 202\" và có phí \"Delivery £2.50\" → đơn được giao tới 2 Spen Lane → địa chỉ này nằm trong phạm vi 10 km tính từ cửa hàng → chọn (B). (A) sai: bãi đậu xe sau cửa hàng xe đạp là của George Street Sweets. (C) sai: \"Business Suite\" cho thấy đây là tòa văn phòng.\n(A) Nó có chỗ đậu xe phía sau một cửa hàng xe đạp.\n(B) Nó nằm trong phạm vi 10 km tính từ George Street Sweets.\n(C) Đó là một tòa chung cư để ở.\n(D) Nó thuộc sở hữu của bà Schwartz."},{"n":193,"q":"What can be concluded about the cake?","qvi":"Có thể kết luận gì về chiếc bánh?","opts":["It has not been paid for yet.","It will have only chocolate icing.","It was ordered over the phone.","It contains ice cream."],"ans":"C","xp":"Câu hỏi suy luận. E-mail 2: \"the person to whom I spoke on the phone while placing my order did not copy down the message I requested\" → ông Ordaz đặt bánh qua điện thoại → chọn (C). (A) sai: biên lai ghi \"Payment Method: Credit Card\". (B) sai: bánh phủ kem vani (\"vanilla icing\"). (D) không được nhắc đến.\n(A) Nó chưa được thanh toán.\n(B) Nó sẽ chỉ có lớp phủ sô-cô-la.\n(C) Nó được đặt qua điện thoại.\n(D) Nó có chứa kem lạnh."},{"n":194,"q":"In the second e-mail, what does Mr. Ordaz request?","qvi":"Trong e-mail thứ hai, ông Ordaz yêu cầu điều gì?","opts":["A full refund","A different flavor","A response to an e-mail","An additional candle"],"ans":"C","xp":"Câu hỏi chi tiết. \"Please respond to this e-mail to confirm.\" → ông yêu cầu cửa hàng trả lời e-mail để xác nhận → chọn (C). Ông muốn thêm dòng chữ trên bánh, không đòi hoàn tiền, không đổi vị, không xin thêm nến.\n(A) Hoàn tiền toàn bộ\n(B) Một hương vị khác\n(C) Phản hồi một e-mail\n(D) Thêm một cây nến"},{"n":195,"q":"What does Mr. Ordaz mention about the event in his e-mail?","qvi":"Ông Ordaz đề cập điều gì về sự kiện trong e-mail của mình?","opts":["It will take place on April 29.","It is an anniversary party.","Its start time has changed.","It will be larger than expected."],"ans":"D","xp":"Câu hỏi chi tiết. \"Also, there will be more guests than I originally expected\" → sẽ có nhiều khách hơn dự kiến → sự kiện lớn hơn dự kiến → chọn (D). (A) sai: 29/4 là ngày gửi e-mail; bánh giao ngày 2/5. (B) sai: đây là tiệc nghỉ hưu (\"Happy Retirement\"), không phải tiệc kỷ niệm. (C) không được nhắc đến.\n(A) Nó sẽ diễn ra vào ngày 29 tháng 4.\n(B) Đó là một bữa tiệc kỷ niệm.\n(C) Giờ bắt đầu của nó đã thay đổi.\n(D) Nó sẽ lớn hơn dự kiến."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mail, survey, and report.","passages":["<div class=\"hdr\"><p><b>To:</b> Undisclosed Recipients</p><p><b>From:</b> iqbal_grewal@woolfflooring.com.au</p><p><b>Date:</b> 12 June</p><p><b>Subject:</b> Cost-savings survey</p></div><p>Dear Colleagues,</p><p>At Woolf Flooring we are looking for ways to reduce day-to-day costs without sacrificing product quality, customer service, or staff morale. To this end, we are seeking input from select staff members in a variety of departments via an online survey that can be found at www.surveyquest.com.au/109820. Everyone who has been chosen to take part in the survey has been with the company for at least ten years and, therefore, is very familiar with our processes.</p><p>The deadline for completing the survey is 19 June. Note that this survey is for recipients of this e-mail only. Please do not forward this e-mail to others or post the link to the survey elsewhere.</p><p>We also plan to hire outside consultants to review our operations and write a report of their findings. We understand that some colleagues disagree with this approach to cutting costs; however, we have determined that getting an outside perspective is a worthwhile investment that will be likely to save us money in the long run.</p><p>Best,</p><p>Iqbal Grewal, Director of Business Transformation<br>Woolf Flooring</p>","<p><b>https://www.surveyquest.com.au/109820</b></p><h4>Woolf Flooring Cost-Savings Survey</h4><p>Based on your experience as an employee of Woolf Flooring, please provide one idea for a change that could be implemented to improve productivity and cut costs. Thank you.</p><p><b>Date:</b> 18 June</p><p><b>Name and role:</b> Beth Mair, sales manager</p><p>I have noticed that some employees grab a new pair of disposable gloves every time they return from a break. They could be using the same ones throughout the whole day. By limiting the use of gloves to one pair per day, Woolf Flooring would save thousands of dollars per year. Doing so would also reduce waste. A new policy regarding the use of personal protective items would be easy to implement immediately and would simply require sending a company-wide e-mail to explain it.</p>","<h3>Miyoko Consulting<br>Woolf Flooring Report Summary</h3><p>Thank you for allowing us to spend the last few weeks reviewing your operations. You will find a detailed expense-reduction report with projected savings in the pages that follow. Here is a list of our main recommendations.</p><p>1. Employees do not always use wood stains and other materials as efficiently as possible. More training time could be dedicated to this.</p><p>2. Employees could be more mindful of electricity costs—for instance, turning off all lights and machines when not in use.</p><p>3. Several Internet service providers are offering special pricing right now. Switching to one of these providers could save a considerable amount of money in the long run.</p><p>4. More effort could be made to reuse supplies—for example, some basic personal protective equipment could be used more than once.</p>"],"vi":"Gửi: Người nhận không công khai\nTừ: iqbal_grewal@woolfflooring.com.au\nNgày: 12 tháng 6\nTiêu đề: Khảo sát tiết kiệm chi phí\n\nCác đồng nghiệp thân mến,\n\nTại Woolf Flooring, chúng ta đang tìm cách giảm chi phí hằng ngày mà không hy sinh chất lượng sản phẩm, dịch vụ khách hàng hay tinh thần nhân viên. Vì mục đích này, chúng tôi đang thu thập ý kiến từ một số nhân viên được chọn ở nhiều phòng ban thông qua một khảo sát trực tuyến tại www.surveyquest.com.au/109820. Tất cả những người được chọn tham gia khảo sát đều đã làm việc cho công ty ít nhất mười năm và do đó rất am hiểu các quy trình của chúng ta.\n\nHạn chót hoàn thành khảo sát là ngày 19 tháng 6. Xin lưu ý rằng khảo sát này chỉ dành cho những người nhận e-mail này. Vui lòng không chuyển tiếp e-mail này cho người khác hoặc đăng đường link khảo sát ở nơi khác.\n\nChúng tôi cũng dự định thuê chuyên gia tư vấn bên ngoài để đánh giá hoạt động của công ty và viết báo cáo về những phát hiện của họ. Chúng tôi hiểu rằng một số đồng nghiệp không đồng ý với cách cắt giảm chi phí này; tuy nhiên, chúng tôi đã xác định rằng có được góc nhìn từ bên ngoài là một khoản đầu tư xứng đáng và nhiều khả năng sẽ giúp chúng ta tiết kiệm tiền về lâu dài.\n\nTrân trọng,\nIqbal Grewal, Giám đốc Chuyển đổi Kinh doanh\nWoolf Flooring\n\n---\n\nhttps://www.surveyquest.com.au/109820\n\nKhảo sát tiết kiệm chi phí của Woolf Flooring\n\nDựa trên kinh nghiệm làm việc tại Woolf Flooring, vui lòng đưa ra một ý tưởng thay đổi có thể áp dụng để nâng cao năng suất và cắt giảm chi phí. Xin cảm ơn.\n\nNgày: 18 tháng 6\nHọ tên và vai trò: Beth Mair, quản lý bán hàng\n\nTôi nhận thấy một số nhân viên lấy một đôi găng tay dùng một lần mới mỗi khi họ quay lại sau giờ nghỉ. Họ hoàn toàn có thể dùng cùng một đôi suốt cả ngày. Bằng cách giới hạn mỗi người một đôi găng tay mỗi ngày, Woolf Flooring sẽ tiết kiệm được hàng nghìn đô-la mỗi năm. Làm vậy cũng sẽ giảm rác thải. Một chính sách mới về việc sử dụng đồ bảo hộ cá nhân sẽ dễ dàng áp dụng ngay lập tức và chỉ cần gửi một e-mail toàn công ty để giải thích.\n\n---\n\nCông ty Tư vấn Miyoko\nTóm tắt báo cáo cho Woolf Flooring\n\nCảm ơn quý công ty đã cho phép chúng tôi dành vài tuần qua để đánh giá hoạt động của quý công ty. Quý vị sẽ thấy một báo cáo chi tiết về cắt giảm chi phí kèm mức tiết kiệm dự kiến ở các trang tiếp theo. Dưới đây là danh sách các đề xuất chính của chúng tôi.\n\n1. Nhân viên không phải lúc nào cũng sử dụng thuốc nhuộm gỗ và các vật liệu khác một cách hiệu quả nhất. Có thể dành thêm thời gian đào tạo cho việc này.\n\n2. Nhân viên có thể chú ý hơn đến chi phí điện — ví dụ, tắt tất cả đèn và máy móc khi không sử dụng.\n\n3. Hiện có một số nhà cung cấp dịch vụ Internet đang đưa ra mức giá ưu đãi. Chuyển sang một trong các nhà cung cấp này có thể tiết kiệm một khoản tiền đáng kể về lâu dài.\n\n4. Có thể nỗ lực hơn trong việc tái sử dụng vật tư — ví dụ, một số đồ bảo hộ cá nhân cơ bản có thể được dùng nhiều hơn một lần.","qs":[{"n":196,"q":"In his e-mail, what does Mr. Grewal indicate about the survey?","qvi":"Trong e-mail, ông Grewal cho biết điều gì về khảo sát?","opts":["It does not have an end date.","It requires the use of a password.","It can be completed on paper.","It should not be shared with others."],"ans":"D","xp":"Câu hỏi chi tiết. \"Note that this survey is for recipients of this e-mail only. Please do not forward this e-mail to others or post the link to the survey elsewhere.\" → không được chia sẻ khảo sát cho người khác → chọn (D). (A) sai: hạn chót là \"19 June\". (C) sai: khảo sát làm trực tuyến (\"online survey\"). (B) không được nhắc đến.\n(A) Nó không có ngày kết thúc.\n(B) Nó yêu cầu dùng mật khẩu.\n(C) Nó có thể được làm trên giấy.\n(D) Không nên chia sẻ nó với người khác."},{"n":197,"q":"According to the e-mail, what do some Woolf Flooring employees disagree with?","qvi":"Theo e-mail, một số nhân viên Woolf Flooring không đồng ý với điều gì?","opts":["The plan to hire consultants","The way a survey is structured","The way a budget report is presented","The departments selected to provide feedback"],"ans":"A","xp":"Câu hỏi chi tiết. \"We also plan to hire outside consultants to review our operations ... We understand that some colleagues disagree with this approach to cutting costs\" → \"this approach\" chính là kế hoạch thuê chuyên gia tư vấn bên ngoài → chọn (A).\n(A) Kế hoạch thuê chuyên gia tư vấn\n(B) Cách cấu trúc một bản khảo sát\n(C) Cách trình bày một báo cáo ngân sách\n(D) Các phòng ban được chọn để đóng góp ý kiến"},{"n":198,"q":"What can be concluded about Ms. Mair?","qvi":"Có thể kết luận gì về bà Mair?","opts":["She regularly provides ideas for change.","She has worked at Woolf Flooring for many years.","She will be helping to collect feedback.","She works in the production department."],"ans":"B","xp":"Câu hỏi kết hợp 2 văn bản (suy luận). E-mail: \"Everyone who has been chosen to take part in the survey has been with the company for at least ten years\" → ai được mời làm khảo sát đều đã làm ở công ty ít nhất 10 năm. Bà Beth Mair đã điền khảo sát (\"Name and role: Beth Mair, sales manager\") → bà đã làm ở Woolf Flooring nhiều năm → chọn (B). (D) sai: bà là quản lý bán hàng (sales manager), không thuộc bộ phận sản xuất.\n(A) Bà ấy thường xuyên đưa ra ý tưởng thay đổi.\n(B) Bà ấy đã làm việc tại Woolf Flooring nhiều năm.\n(C) Bà ấy sẽ giúp thu thập ý kiến phản hồi.\n(D) Bà ấy làm ở bộ phận sản xuất."},{"n":199,"q":"In the survey, what does Ms. Mair note about her suggestion?","qvi":"Trong khảo sát, bà Mair lưu ý điều gì về đề xuất của mình?","opts":["It may require some new equipment.","It has worked well at other companies.","It could be implemented right away.","It has been suggested to management before."],"ans":"C","xp":"Câu hỏi chi tiết. \"A new policy regarding the use of personal protective items would be easy to implement immediately and would simply require sending a company-wide e-mail to explain it.\" → dễ áp dụng ngay lập tức → \"implement immediately\" = \"implemented right away\" → chọn (C).\n(A) Nó có thể cần một số thiết bị mới.\n(B) Nó đã hiệu quả ở các công ty khác.\n(C) Nó có thể được áp dụng ngay lập tức.\n(D) Nó đã từng được đề xuất với ban quản lý trước đây."},{"n":200,"q":"What recommendation made by Miyoko Consulting corresponds with Ms. Mair's suggestion?","qvi":"Đề xuất nào của Công ty Tư vấn Miyoko tương ứng với đề xuất của bà Mair?","opts":["Recommendation 1","Recommendation 2","Recommendation 3","Recommendation 4"],"ans":"D","xp":"Câu hỏi kết hợp 2 văn bản. Bà Mair đề xuất dùng lại găng tay dùng một lần cả ngày: \"They could be using the same ones throughout the whole day ... A new policy regarding the use of personal protective items\". Báo cáo Miyoko, đề xuất 4: \"More effort could be made to reuse supplies—for example, some basic personal protective equipment could be used more than once.\" → cùng ý tái sử dụng đồ bảo hộ cá nhân → chọn (D). Đề xuất 1 về vật liệu nhuộm gỗ, 2 về tiền điện, 3 về nhà cung cấp Internet.\n(A) Đề xuất 1\n(B) Đề xuất 2\n(C) Đề xuất 3\n(D) Đề xuất 4"}]}]}};
